WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[31957] = { title = "Grand Master Shu", description = "You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.", objectives = "" }
WordHunterWoW_QuestEN[31958] = { title = "Grand Master Aki", description = "You wish to test yourself against me once more? Very well, let us fight.", objectives = "" }
WordHunterWoW_QuestEN[31959] = { title = "The Empress' Gambit", description = "Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess.\n\nWe have been fortunate to hold out this long, but we cannot survive a siege of this scale.\n\nWakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons.\n\nI will see you on the battlefield!", objectives = "" }
WordHunterWoW_QuestEN[31966] = { title = "Battle Pet Tamers: Cataclysm", description = "You have defeated Northrend's finest tamers, but you need more preparation before you are ready to face the grand masters of Pandaria. Ready yourself and hone your skills by defeating these elite tamers: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnce you have triumphed over them, you will be ready to journey to Pandaria to face the ultimate challenge.", objectives = "" }
WordHunterWoW_QuestEN[31967] = { title = "Battle Pet Tamers: Cataclysm", description = "Northrend has fallen to your hand, but you are not yet ready to face the grand masters of Pandaria. Defeat these tamers to harden your will for the coming challenges: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnly by defeating them will you be ready to journey to Pandaria.", objectives = "" }
WordHunterWoW_QuestEN[31970] = { title = "Grand Master Obalis", description = "You think yourself ready to challenge Pandaria? You truly believe that you can defeat the most powerful tamers in all of Azeroth?\n\nI shall be the judge of that notion, {race}. Face me atop the Vir'naal Dam in Uldum, and we shall see if you are truly ready.", objectives = "" }
WordHunterWoW_QuestEN[31971] = { title = "Grand Master Obalis", description = "I see the triumphant tamer returns to again test himself against me. Very well. I accept your challenge.", objectives = "" }
WordHunterWoW_QuestEN[31972] = { title = "Brok", description = "I do not yet understand the plight of these creatures well enough to help them sufficiently. Perhaps another battle would strengthen our bond?", objectives = "" }
WordHunterWoW_QuestEN[31973] = { title = "Bordin Steadyfist", description = "The natives have taught me the strength of the earth. I know it's unending endurance. Let us battle once more, and you'll see that I'm tougher than ever!", objectives = "" }
WordHunterWoW_QuestEN[31974] = { title = "Goz Banefury", description = "The power of twilight flows through me. I am a god! You have no hope of defeating me!", objectives = "" }
WordHunterWoW_QuestEN[31975] = { title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!", objectives = "" }
WordHunterWoW_QuestEN[31976] = { title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Audrey Burnhep, for further guidance.", objectives = "" }
WordHunterWoW_QuestEN[31977] = { title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Varzok in Orgrimmar and see what's next in your new career as a tamer!", objectives = "" }
WordHunterWoW_QuestEN[31978] = { title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom to deliver our brew when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", objectives = "" }
WordHunterWoW_QuestEN[31980] = { title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Varzok, for further guidance.", objectives = "" }
WordHunterWoW_QuestEN[31981] = { title = "Exceeding Expectations", description = "Run off to your trainer, Audrey Burnhep, in Stormwind. Perhaps she can find you more...worthwhile...challenges.", objectives = "" }
WordHunterWoW_QuestEN[31982] = { title = "Exceeding Expectations", description = "Run off to your trainer, Varzok, in Orgrimmar. Perhaps he can find you more... worthwhile... challenges.", objectives = "" }
WordHunterWoW_QuestEN[31983] = { title = "A Brief Reprieve", description = "Well done, for an {race}. Now, get back to Orgrimmar and talk to that brute Varzok. Maybe he can point you somewhere very far away from my family.", objectives = "" }
WordHunterWoW_QuestEN[31984] = { title = "A Brief Reprieve", description = "Well done, well done indeed! If you would, please report to Miss Audrey Burnhep in Stormwind.\n\nOh, and send her my regards. She's a beautiful young woman that could benefit from the company of an accomplished fighter such as myself.", objectives = "" }
WordHunterWoW_QuestEN[31985] = { title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Stormwind and have words with Audrey Burnhep. She will guide you further.", objectives = "" }
WordHunterWoW_QuestEN[31986] = { title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Orgrimmar and have words with Varzok. He will guide you further.", objectives = "" }
WordHunterWoW_QuestEN[31987] = { title = "LFGDungeons - Theramore Launch Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[31989] = { title = "The Peak of Serenity - Complete Your Training", description = "The time has come for you to return to the Peak of Serenity to complete your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31991] = { title = "Grand Master Zusshi", description = "I knew you would return to face me once more. Let us see who is truly wiser in the ways of battle.", objectives = "" }
WordHunterWoW_QuestEN[31998] = { title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31999] = { title = "Nazgrim's Command", description = "You have a comfortable base of operations, no Alliance around for miles, and a few Horde veterans by your side. It looks like it's time to start painting this continent red.\n\nGeneral Nazgrim should know where to start.", objectives = "" }
WordHunterWoW_QuestEN[32000] = { title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32001] = { title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32002] = { title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32003] = { title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32004] = { title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32005] = { title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32006] = { title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", objectives = "" }
WordHunterWoW_QuestEN[32007] = { title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[32008] = { title = "Audrey Burnhep", description = "Greetings, {name}! My name is Audrey Burnhep. I've been hearing quite a lot about you recently. You're becoming quite the tamer!\n\nYou should come speak with me in Stormwind. I have connections with some of the finest tamers in all of Azeroth, and I can help you grow even more!", objectives = "" }
WordHunterWoW_QuestEN[32009] = { title = "Varzok", description = "Lok'tar, {name}. My name is Varzok. I have heard much your accomplishments as a tamer recently, and I would like to introduce you to trainers around Azeroth so that you may further hone your skills.\n\nPlease speak with me in Orgrimmar so that we may begin.", objectives = "" }
WordHunterWoW_QuestEN[32016] = { title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", objectives = "" }
WordHunterWoW_QuestEN[32017] = { title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", objectives = "" }
WordHunterWoW_QuestEN[32018] = { title = "His Name Was... Stormstout", description = "An unusual pandaren came through town a few days back. He told a better tale than Pan, drank twice as much as Lee, and then beat me up in front of the bar. All while his little niece made fun of us.\n\nIt was awesome.\n\nThey said they were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", objectives = "" }
WordHunterWoW_QuestEN[32019] = { title = "They Call Him... Stormstout", description = "Things were not always like this, {race}. Oh no, they were much, much worse. Not three weeks ago, we were under siege by saurok bandits. They stole our jade, befouled our food stores, and terrorized our cubs.\n\nWe needed a hero, and a hero arrived.\n\nHe drove back their forces, defeated their leader, and returned our stolen jade. All he asked in return was a serpent ride for his niece.\n\nI was never able to thank him. If you are headed to the Valley of the Four Winds, would you relay our thanks?", objectives = "" }
