WordHunterWoW_QuestEN[32034] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32035] = { title = "Got Silk?", description = "Strange noises comin' from over at the Silken Fields.\n\nStrange smells, too.\n\nAlmost makes you think that they could use a cash-strapped {class} to complete a few odd jobs for 'em. Make a few pieces of gold.\n\nOr not.", objectives = "" }
WordHunterWoW_QuestEN[32036] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32037] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32038] = { title = "Stag Mastery", description = "I always was a fan of a good stag hunt. Stags are tough, fast, and territorial.\n\nThey may be plant eaters but they can give any hunter a run for his money.\n\nEast of here is a whole mess of Wilderland Stags just waiting for a hunter like yourself to give 'em a good run.\n\nHappy hunting.", objectives = "" }
WordHunterWoW_QuestEN[32039] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32040] = { title = "Candy Bucket", description = "", objectives = "" }
