WordHunterWoW_QuestEN[32042] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32043] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32044] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32045] = { title = "Children of the Water", description = "We are all children of the water here in the Valley of the Four Winds. It nourishes us, it grows our vegetables, it brings us life.\n\nSome creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them.\n\nI am but a simple stonecarver. You, on the other hand...", objectives = "" }
WordHunterWoW_QuestEN[32046] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32047] = { title = "Candy Bucket", description = "", objectives = "" }
