WordHunterWoW_QuestEN[32049] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32050] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32051] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32052] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[32097] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[32105] = { title = "Pristine Monument Ledger", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32106] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[32107] = { title = "Flying Tiger Gourami", description = "You've caught a unique fish... with wings.  Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.\n", objectives = "" }
WordHunterWoW_QuestEN[32108] = { title = "Domination Point", description = "Now it is time to show this new land the true strength of the Horde.\n\nReturn to the beach and light the remaining signal fire. Our fleet is waiting.", objectives = "" }
WordHunterWoW_QuestEN[32109] = { title = "Lion's Landing", description = "For too long the Horde has been allowed to run rampant across Azeroth. I will not see these new lands conquered by some barbaric \"warchief.\"\n\nAre you ready to bring Alliance justice to the shores of Pandaria?\n\nLet us return to the landing site. Use the flare launcher to bring in the fleet proper, and begin Operation: Shieldwall.", objectives = "" }
WordHunterWoW_QuestEN[32115] = { title = "Shackles of the Past", description = "The mogu are a bunch of right bastards!\n\nThey enslaved the pandaren who worked these caves even after their death. Ye' gotta go free their spirits! It's just not right.\n\nBe careful though... so much trauma, they don't know what's a friend and what's an enemy. So they'll probably fight back.", objectives = "" }
WordHunterWoW_QuestEN[32116] = { title = "Priorities, People!", description = "When I ordered the excavation of the tunnel to the northwest, I thought we'd find something useful. Gold, iron... anything!\n\nInstead, we found mogu artifacts, and I get a bunch of dwarves from the Explorers' League to baby-sit.\n\nI hear from the soldiers that there's trouble in the mines. I have orders from Wrynn that I have to support the Explorers' League, but I can't spare any troops. Can you get down there and find out what's going on?", objectives = "" }
WordHunterWoW_QuestEN[32118] = { title = "Taking Advantage", description = "The fools in the Explorers' League have excavated an ancient mogu ruin to the northeast. And - of course - in their bumbling, they've disturbed the mogu spirits within.\n\nWe are going to take advantage of their ineptitude. Take this portal and meet with Kaelis Sunsoar, my contact within the ruins.", objectives = "" }
WordHunterWoW_QuestEN[32119] = { title = "It Is A Mystery", description = "There's somethin' down there that was spookin' the workers. Some kind o' anomaly... looks like a ghost, or a magic spell... like nothing I've ever seen.\n\nI did manage to get a reading on it and put together this device to try to track it down. The display on the device will let you know roughly how close you are. \n\nOnce you get close enough, you can use it to draw out the anomaly and get rid of it for good!", objectives = "" }
WordHunterWoW_QuestEN[32120] = { title = "Legacy of Ogudei", description = "The ruins which we are occupying were built by Ogudei - an ancient mogu ruler. We know little about who he was, though the rise of the spirits in this area seems to indicate that it was related to spirit binding.\n\nWhen you destroy these spirits, a small amount of their essence will remain in this world. Bring it to us - we will analyze it and hopefully learn more about Ogudei's history - and his power.", objectives = "" }
WordHunterWoW_QuestEN[32121] = { title = "The Spirit Trap", description = "In the ruins there are a bunch of right nasty blue crystals. Look at 'em the wrong way and bloody angry ghosts run out at ya.\n\nI'm gonna be needing ye' to go in and clear some of them out so we can get our people back to work.", objectives = "" }
WordHunterWoW_QuestEN[32122] = { title = "Ogudei's Lieutenants", description = "When we dug through to an ancient section of the mogu ruins, that's when all this nasty business went down - and that's where the two worst o' these ghosties emerged.\n\nWe need them gone, friend.", objectives = "" }
WordHunterWoW_QuestEN[32123] = { title = "Death on Two Legs", description = "The Alliance has made landfall. If we do not defeat them here, any hope of a Horde presence on this continent is lost.\n\nGo to the battlefield south of here and slay Alliance you find.\n\nShow them how any Horde who still stands on two legs will be the death of ten Alliance!", objectives = "" }
WordHunterWoW_QuestEN[32126] = { title = "Tear It Up", description = "The Alliance may be cowardly, but they are not fools. Their assault would be formidable, if it were directed at lesser creatures.\n\nTo sustain a siege and put pressure on our troops they are air dropping in supplies to support their ground forces.\n\nSearch the beaches and docks to the south for any airdropped supplies and smash them.\n\nLet the Alliance see their food and ammunition destroyed before their eyes and despair.", objectives = "" }
WordHunterWoW_QuestEN[32127] = { title = "All Dead, All Dead", description = "Our Warchief has dispatched me to these shores to deal with this pitiful Alliance threat.\n\nThese humans and their allies have proven to be very dependent on their leaders. No initiative of their own.\n\nAs you walk the battlefield today look to the Alliance ships off our southern shores. Find their captains.\n\nSlay them.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[32128] = { title = "Another One Bites the Dust", description = "The Alliance have planted themselves off our southern coast and continue to pepper our ground forces with cannon fire. Let us see how great their siege is without such support.\n\nBoard the enemy vessels and destroy their reserve ammunition. This will take the teeth out of their bite.", objectives = "" }
WordHunterWoW_QuestEN[32129] = { title = "Defense Daily 06", description = "", objectives = "" }
WordHunterWoW_QuestEN[32130] = { title = "Good Luck, Have Fun", description = "I've got some customers lined up that wanna collect some good old fashioned ears. But not any old ears. They only want the absolute waxiest ears money can buy! \n\nGuess they think they're lucky or something'.\n\nAnyways, I need you to go get 'em for me. I don't want to hurt any animals, so you'll need to get 'em from the Alliance over at Lion's Landing.\n\nHave fun - and remember, only bring me the waxiest!", objectives = "" }
WordHunterWoW_QuestEN[32131] = { title = "We Require More Minerals!", description = "Gnomes are excavating a stone quarry to the northeast.\n\nThey're building stuff with it!\n\n<Zazzix rolls his eyes.>\n\nThey're too stupid to realize it's special mogu stone for creating animated statues. \n\nWE can mix with a little Goblin magic juice to make some real big explosions!\n\nBut the stuff is heavy. They've got some of their stupid bomb-bots there for excavating the stone. Blow 'em up near slabs and you'll get chunks small enough to carry. \n\nOr, just kill 'em and take it. Whatever works.", objectives = "" }
WordHunterWoW_QuestEN[32132] = { title = "Worker Harassment", description = "Our goblin friends do not have the grasp of strategy necessary to win a long term engagement, I'm afraid.\n\nThe key to eliminating any permanent establishment is to attack their ability to replenish their troops and to rebuild.\n\nIn this case, that means taking out their Peasants. Kill them, and you weaken the foundation. The rest of the keep is bound to crumble.", objectives = "" }
WordHunterWoW_QuestEN[32133] = { title = "Sentry Wards", description = "We've spotted heavy air support over their base, in the form of way too many dwarves on way too many griffons. Means we can't get any vision of the area from above.\n\nA troll... friend of mine gave us a set of Sentry Wards, which we can use to spy on their base and get a vantage point on what's going on in there.\n\nBad news, friend - you're going to be the one going in there.", objectives = "" }
WordHunterWoW_QuestEN[32134] = { title = "Hard Counter", description = "We've managed to get some Demolishers on the beach, but the stupid dwarves are also out there with their stupid mortar tubes, preventing the Demolishers from pushing forward and assaulting the keep itself!\n\nGet out there, kill some dwarves, and blow up some mortar tubes.", objectives = "" }
WordHunterWoW_QuestEN[32135] = { title = "Hero Killer", description = "There are some situations in which taking out one of their soldiers is more important than killing hundreds.\n\nThey've deployed some of their heroes to the battlefield to help rally their defenders. Not only will killing them soften their defense, it will also leave their morale crippled.\n\nSo go, take one down for me. You can handle it.", objectives = "" }
WordHunterWoW_QuestEN[32136] = { title = "Work Order: Fuel", description = "Our fuel supplies are running low. Without fuel we won't be able to operate the machinery that's building this place. They might even expect me to start helping them build!\n\nI was not built for manual labor! See these nails?! I just had them done!\n\nGet down to the refinery and get this fuel order filled! Hurry! They were fitting me for a tool-belt this morning. It didn't even match my outfit!", objectives = "" }
WordHunterWoW_QuestEN[32137] = { title = "Runnin' On Empty", description = "I've never seen this quality of oil! Problem is the oil needed a little extra refinin'.\n\nI heard of this system where you use ocean water to speed up the process. I don't have time to waste down here, so I just threw the barrels into the bay.\n\nPretty good idea, I know. Problem is, I'm not sure how to pull it out of the bay...\n\nMaybe someone of your expertise could help me out.", objectives = "" }
WordHunterWoW_QuestEN[32138] = { title = "Work Order: Lumber", description = "Everyday it's the same thing! \"We're out of this!\", \"We need more of that!\", \"Why don't you ever do anything?!\"\n\nI work! I do things! They can be so hurtful! I'm doin' my best down here!\n\nOh yeah, we need more lumber! Go down and tell that good for nothin' Zino to get his shredders in gear!", objectives = "" }
WordHunterWoW_QuestEN[32139] = { title = "Stacked!", description = "We just filled an order this morning. How could they possibly need more already?!\n\nMy team has been workin' double-time to get these trees chopped and processed.\n\nProblem is we have an infestation of Lion's Landing troops down here. I already risked my neck once today, I'm not goin' back out there!\n\nGoob will go with you and help you fill this order. He's not the brightest, but he can do the heavy liftin'.", objectives = "" }
WordHunterWoW_QuestEN[32140] = { title = "Work Order: Iron", description = "When they said they found some amazing rocks in that mine I envisioned diamonds. Everyone knows all mines have diamonds, silly! At the very least rubies!\n\nInstead, all I got was this strange iron! What am I supposed to do with this?\n\nOh well, no one said this job would be glamorous. I just do what I can to add a little class.\n\nWe just got another work order for iron. Go see Daxil down near Oregrind's Dig and get it filled pronto!", objectives = "" }
WordHunterWoW_QuestEN[32141] = { title = "Power Metal", description = "<Daxil narrows her eyes and speaks in a hushed tone.>\n\nSometimes we dig too deep, {class}. Sometimes, we uncover something so horrible we wish we hadn't started diggin'...\n\nJust kidding! I mean, don't get me wrong, we did find something unexpected. The ore we're finding down there is not your average run-of-the-mill iron.\n\nThere is just one problem; Shale Spiders! We're struggling to keep these orders filled.\n\nMaybe you can lend us a hand?", objectives = "" }
WordHunterWoW_QuestEN[32142] = { title = "We Will Rock You", description = "The orcs can NOT be allowed a foothold in this land. They will defile it just as they did Kalimdor.\n\n{name}, I need boots on the ground and horde in their graves. Get down to the coastline and bring the full force of Alliance wrath down on their heads!\n\nSlay any orcs you find. Take the wind out of their sails.\n\nFor the King!", objectives = "" }
WordHunterWoW_QuestEN[32143] = { title = "A Kind of Magic", description = "Greetings {name}! I have heard a lot about your success in the field. I would like to use your services to test my latest \"Siege-o-Matic\", a device of terrible and varied abilities.\n\nI promise it is mostly harmless to its users.\n\nWhen you are around Domination Point be on the look out for my Scout-o-Meters. They have been dispatched to get info on good siege targets. When you find one, activate it and I will pilot a Siege-o-Matic to your location.\n\nSee you in the field... as it were.", objectives = "" }
WordHunterWoW_QuestEN[32144] = { title = "Under Pressure", description = "The Horde are consumed by pride and will fight to the death without a second thought.\n\nWe need to find a way to break their will that does not involve massive loss of our numbers.\n\nLook for the Horde supplies along the coastline and near their ships. Smash their supplies.\n\nNothing breaks the will of a defender like seeing their hope of food go up in a puff of smoke.\n\nWhen you are done, find Sully behind enemy lines. He has the next task for you.", objectives = "" }
WordHunterWoW_QuestEN[32145] = { title = "Don't Lose Your Head", description = "My probes have detected three very dangerous targets in the courtyard of Domination Keep.\n\nThey have an ogre emissary, a Kor'kron officer, and an insane goblin bomb maker.\n\nMy siege-o-matics are not ready for one on one combat so it is up to you to eliminate the targets.\n\nGood luck! Report back to me on the Skyfire when done.", objectives = "" }
WordHunterWoW_QuestEN[32146] = { title = "Hammer to Fall", description = "It looks like the Horde thinks they can hide behind their heavy hitting mooks.\n\nThe mooks are tough, powerful, and dumber than an ogre with a hangover.\n\nGo down there and bring the hammer of the Alliance fury down on them!", objectives = "" }
WordHunterWoW_QuestEN[32147] = { title = "Attack Daily 06", description = "", objectives = "" }
WordHunterWoW_QuestEN[32148] = { title = "Attack! Move!", description = "Sure, they've got about plenty of grunts out there, pounding on our door, waiting to cut our heads off.\n\nI'm not worried about grunts. But they've got shamans and raiders, too. The shamans use their magic to empower the grunts, and the raiders are fast and specialize in taking out our buildings.\n\nI need you to get out there and kill some of those shamans and raiders.\n\nGo! Attack! Move!", objectives = "" }
WordHunterWoW_QuestEN[32149] = { title = "Resource Gathering", description = "Oh, the poor peasants...\n\nThey are cowards, yes, of course. But they don't know how to fight, and they go out to collect lumber for our efforts... the Horde targets them... It's just awful all around!\n\nBut, we need that lumber if we're going to hold out. Go out and collect any they've dropped.", objectives = "" }
WordHunterWoW_QuestEN[32150] = { title = "Supply Block", description = "The Horde decided to put goblins in charge of their logistics. And where you have goblins, you have carelessly placed explosives.\n\nScouts have reported that they have their supplies in carts that also contain demolisher ammunition. Look at those crates the wrong way, and they'll blow sky high. \n\nWith enough Horde resources destroyed, we'll put a time limit on their attack and save lives. So go and take out those carts!", objectives = "" }
WordHunterWoW_QuestEN[32151] = { title = "Tower Defense", description = "The gnomes are running our quarry operation to the northwest. The stone there is especially tough - the gnomes tell me the mogu used it to fashion their constructs. \n\nI don't know. What I do know is that we use that stone to build our towers, and the Horde has dispatched the Bilgewater goblins to steal it from us.\n\nGet out there and get some back. By the way - collateral damage may break up the stone slabs there. If so, pick that up, too.", objectives = "" }
WordHunterWoW_QuestEN[32152] = { title = "Siege Damage", description = "The Horde got the bright idea to send Bilgewater goblins to attack our quarry.\n\nThey've been packing heavy explosives - heavy explosives that will react with the ammunition in their demolishers.\n\nKill the Bilgewater goblins until you find an explosive, plant it on one of the demolishers... and BOOM! Siege ended.", objectives = "" }
WordHunterWoW_QuestEN[32153] = { title = "Hero Killer", description = "Look, you're tough. Tougher than the rest of the men and women I've got here. Which means I need you for a special mission.\n\nThe Horde is throwing their best against us. Heroes of their armies - Blademasters, Tauren Chieftans, you name it.\n\nI need you to go take one out. It'll be a huge blow, not just to their offensive but also to morale.", objectives = "" }
WordHunterWoW_QuestEN[32154] = { title = "Burn Out!", description = "Those goblins are gettin' out of hand! First they level the forest and set up that abomination of a rig. Then, they start dumpin' their oil barrels into the bay!\n\nWe got to put a stop to this madness! At the very least we need ta set them back.\n\nWe need to take out their fuel supply! Maybe you'll even get to kill a few goblins in the process!", objectives = "" }
WordHunterWoW_QuestEN[32155] = { title = "Necessary Breaks", description = "It goes against me nature to break things on purpose, but in this case it's necessary.\n\nThat rig the goblins are usin' is held together by a wish an' some bubblegum. We need to exploit the situation a little more.\n\nWe have some saboteurs down there already, but we can use someone of your expertise to hurry the job along.\n\nGet down there an' start breakin' and stealin' some valves!", objectives = "" }
WordHunterWoW_QuestEN[32156] = { title = "It's Only Right", description = "This is barbaric warfare, {class}! We've lost so many trying to keep the Bilgewater operation from spreading any further.\n\nThose fallen soldiers fought honorably and deserved to be given their last rights. At the very least we need to be able to notify their next of kin.\n\nPerhaps you can collect their identification tags so we can honor them in some small way.", objectives = "" }
WordHunterWoW_QuestEN[32157] = { title = "The Only Good Goblin...", description = "The destruction in Krasarang is unforgivable, {class}. The only way to put an end to this is to destroy the Bilgewater operation.\n\nThis is for the greater good of Pandaria and the Alliance. Go to Bilgewater Beach and cut them down! No doubt the Horde will come to their assistance.\n\nDestroy them!", objectives = "" }
WordHunterWoW_QuestEN[32158] = { title = "Two Step Program", description = "Shredmaster Packle is responsible for much of the devastation down there, {class}.\n\nRumor has it he modified the shredders to work more quickly with less regard for the collateral damage they can inflict.\n\nImagine the agony the trees must endure being hacked at. It will be difficult to recover from this level of destruction.\n\nThe first step in any recovery is acknowledging the problem. Step two is eliminating that problem.", objectives = "" }
WordHunterWoW_QuestEN[32159] = { title = "Circle of Life", description = "We should attempt to offset the destruction being wrought on this continent as much as possible. For every tree they destroy, we will plant a new one!\n\nTake these seeds and begin the regrowth process, {name}.\n\nDo not linger for too long though. Nature is unpredictable, and no doubt the anger and hate exuding from Domination Point has seeped into the ground.\n\nI cannot guarantee that the plant that springs from these seeds will not be hostile.", objectives = "" }
WordHunterWoW_QuestEN[32161] = { title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds are not tempted by simple things like food. You will need to play on the creatures' emotions if you wish to draw them from their hiding places in the jungle.\n\nCranes abound on both the Cradle of Chi-ji and the Narsong Spires, both of which can be found east of here. Pluck those cranes' quills, then place them in a visible spot near the Crane Temple. Your quarry will come running to you.", objectives = "" }
WordHunterWoW_QuestEN[32162] = { title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttonous creatures, and large game is hard to come by in this jungle. If you wish to tempt the most elder cats out of their hiding places, you may do so with a meal.\n\nJust on the other side of the Serpent's Spine, you will find a herd of yaks. Slay them, bring their meat to the jungle's edge, set up your trap, and wait.", objectives = "" }
WordHunterWoW_QuestEN[32163] = { title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, primordial creatures, with wildly different motivations than you or I.\n\nSmall crabs are easy to find and hunt, but the large ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southeast allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", objectives = "" }
WordHunterWoW_QuestEN[32164] = { title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds don't care about simple things like food. You need to play on the creatures' emotions if you want to draw them out of the jungle.\n\nThere's plenty of cranes on the Cradle of Chi-ji and on the Narsong Spires, both to the west of here. Pluck some of those cranes' quills, then put them in a visible spot near the Crane Temple. Your quarry will come running to you.", objectives = "" }
WordHunterWoW_QuestEN[32165] = { title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttons, and big game is hard to come by in this jungle. If you want to tempt the elder cats out of their hiding places, you need a tempting meal.\n\nJust on the other side of the Serpent's Spine, you can find a herd of yaks. Kill them, bring their meat to the jungle's edge, set up your trap, and wait.", objectives = "" }
WordHunterWoW_QuestEN[32166] = { title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, old creatures, with different motivations than us.\n\nSmall crabs are easy to find and hunt, but the big ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southwest allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", objectives = "" }
WordHunterWoW_QuestEN[32167] = { title = "Ancient's Fall", description = "The crane has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32168] = { title = "End of an Elder", description = "The tiger has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32169] = { title = "A Colossal Victory", description = "The crab has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32170] = { title = "Ancient's Fall", description = "The crane has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32171] = { title = "End of an Elder", description = "The tiger has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32172] = { title = "A Colossal Victory", description = "The crab has fallen.", objectives = "" }
WordHunterWoW_QuestEN[32173] = { title = "Build Portal 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[32174] = { title = "Build Portal 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[32175] = { title = "Darkmoon Pet Battle!", description = "Are you prepared to test the mettle of your pets...?", objectives = "" }
WordHunterWoW_QuestEN[32181] = { title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32182] = { title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32183] = { title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32184] = { title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32185] = { title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32186] = { title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", objectives = "" }
WordHunterWoW_QuestEN[32189] = { title = "A Shabby New Face", description = "A strange fellow in a pointy hat showed up this morning trying to sell some kinda special seeds. Claimed they were magic.\n\nI welcome a little competition - business is business, after all - but this gentleman had a certain... shabby look to him. Oh, and he stunk somethin' FIERCE.\n\nWould you check up on him, just to make sure he's on the level? He's over there by Jian Ironpaw, making a meal out of the samples.", objectives = "" }
WordHunterWoW_QuestEN[32190] = { title = "To Mogujia", description = "Throm-ka, {class}. While we were busy defending our foothold here, Regent Lord Lor'themar Theron led a research expedition north into Kun-Lai Summit.\n\nUnfortunately, it seems they have encountered trouble.\n\nWarchief Garrosh Hellscream has already departed to lend his assistance, but he will require additional reinforcements.\n\nGo northward into the mountains of Kun-Lai. Speak to Tak-Tak for transportation.", objectives = "" }
WordHunterWoW_QuestEN[32191] = { title = "Ancient Guardians", description = "Before the mogu overwhelmed our scouting party, we found relics scattered amongst the ruins to the north.\n\nI would like to collect some samples, but the mogu's terracotta watchdogs are too much for us to handle.\n\nIf you could clear the area of their presence, we will be able to resume our work.", objectives = "" }
WordHunterWoW_QuestEN[32192] = { title = "Bloodlines", description = "We managed to fend off the mogu wardens and their dogs, but many of the blood elves from the scouting party were not as lucky.\n\nMany of my people are trapped inside the ruins to the north. We are devising a solution to break them out, but I believe there may be a more straightforward approach.\n\nGo to the ruins and kill the wardens guarding each prisoner. If my intuition is correct, this will free our comrades.", objectives = "" }
WordHunterWoW_QuestEN[32193] = { title = "To Mogujia", description = "The Explorers' League sent an expedition north some days ago.\n\nWe haven't heard from them since, and I'd sleep better at night knowing our folks aren't in some sort of trouble.\n\nLast I heard, Brann Bronzebeard was heading toward Mogujia in the Kun-Lai Summit.\n\nFind him and report back with their status. Fennie over there can give you a ride if you need one.", objectives = "" }
WordHunterWoW_QuestEN[32194] = { title = "Bad Blood", description = "The Explorers' League is here to excavate the ruins, and it's my job to protect them.\n\nWhen we arrived, we found this place crawling with blood elves. Apparently,the Horde are just as interested in the mogu as we are.\n\nThis gives quite an opportunity to thin our enemies' numbers, and steal their findings, too.\n\nSlay any blood elves you find in the ruins, and bring back whatever they are digging up.", objectives = "" }
WordHunterWoW_QuestEN[32195] = { title = "Anger Remains", description = "From the looks o' our initial survey, this entire area is humming with residual sha energy.\n\nYou know what ta do, {name}. Destroy any last traces ye can find o' the stuff!", objectives = "" }
WordHunterWoW_QuestEN[32197] = { title = "Mystery Meatloaf", description = "We've been gettin' complaints right and left that the Boss-Lady gets all the good grub and leaves the scraps for the others.\n\nBetween you and I, they may be onto somethin' here. I don't even get to eat as good as she does!\n\nWe need somethin' Sezik can make a lot of that at least attempts to disguise how inedible the food is here...\n\nI got it! Mystery Meatloaf!", objectives = "" }
WordHunterWoW_QuestEN[32198] = { title = "One Magical, Flying Kingdom's Trash...", description = "Before we enter into a business relationship, I am required by the terms of my rehabilitation program to inform you that I am a recovering potion addict.\n\nThere, now that THAT's out of the way, let's talk portals!\n\nYou see, the big portals in the cities - the ones running all day and night - leak tons of magical energy. It crystallizes around the edges and is generally regarded as trash.\n\nBut I noticed during my, uh... hiatus in the sewers of Dalaran, that these shards still had power.\n\nInterested?", objectives = "" }
WordHunterWoW_QuestEN[32199] = { title = "Krasarang Steampot", description = "The Boss-Lady desires crabs!\n\nWhy are you looking at me like that? It's not uncommon for a classy person, such as her loveliness, to want crab for dinner. What did you think I meant?\n\nThere are some big crabs wandering around on Bilgewater Beach that should be suitable for her refined palate.\n\nBring Sezik the best crab meat you can find!", objectives = "" }
WordHunterWoW_QuestEN[32200] = { title = "Dangers of Za'Tual", description = "{name}, what I ask of you is little short of genocide, but it is a task that must be done.\n\nFind trolls within their town or on the beach and slay them, for the good of us all.", objectives = "" }
WordHunterWoW_QuestEN[32201] = { title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[32204] = { title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Horde takes full control of this island, we can look for more permanent solutions.", objectives = "" }
WordHunterWoW_QuestEN[32205] = { title = "Gather Scout Reports", description = "", objectives = "" }
WordHunterWoW_QuestEN[32206] = { title = "This Just Won't Do", description = "The Zandalari here are very powerful, {class}. They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords.\n\nMore arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly.\n\nAid us in clearing this area, {class}. Perhaps we can even learn something from them in the process.", objectives = "" }
WordHunterWoW_QuestEN[32207] = { title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.", objectives = "" }
WordHunterWoW_QuestEN[32208] = { title = "Maximum Capacitor", description = "The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy.\n\nWe need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods.\n\nOh - and while you're there, take out whoever is running the operation.", objectives = "" }
WordHunterWoW_QuestEN[32209] = { title = "Save Our Scouts!", description = "The heavy mogu presence in the mines let us know it was a place of great importance - but we needed to gather more information on their activities there, so we sent agents into the mines to spy on them.\n\nUnfortunately, many were captured, and we've found that some are being tortured in the mines. You have to go rescue them - nobody deserves what they are going through...\n\nAnd, when you finish, kill whoever captured them. No mercy, {name}!", objectives = "" }
WordHunterWoW_QuestEN[32212] = { title = "The Assault on Zeb'tula", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", objectives = "" }
WordHunterWoW_QuestEN[32213] = { title = "Old Enemies", description = "So Jaina and the Kirin Tor think they can push us out again? I will not stand by and allow them to repeat the events of Dalaran!\n\nThis time we fight back! This time we do the pushing...\n\nGo to Violet Rise and slay any Kirin Tor agent you find.", objectives = "" }
WordHunterWoW_QuestEN[32214] = { title = "Bilgewater Infiltrators", description = "There is nothing more unnerving than walking along, minding your own business, and hearing someone following you. I swear I hear it all over the place down here! We're being watched!\n\nI have a feeling the entire beach is just crawling with spies!\n\nI made some improvements to our infrared goggle tech to put an end to the sabotogery. That's right sabotogery! Now I just need you to try 'em out! Feel free to dispose of any spies you happen to catch.", objectives = "" }
WordHunterWoW_QuestEN[32215] = { title = "Heinous Sacrifice", description = "The Zandalari perform heinous rites against our people! They must be stopped!\n\nDelve into the heart of the Za'Tual and destroy their altars.", objectives = "" }
WordHunterWoW_QuestEN[32216] = { title = "Pterrible Ptorment", description = "The Zandalari treat their skyscreamer pets as little more than scuttling vermin, bending them to their will with violence and torment.\n\nI can hear one writhing in pain at their hands.\n\nFind the tormented skyscreamer within Za'Tual and help it break free of its captors.", objectives = "" }
WordHunterWoW_QuestEN[32217] = { title = "Dark Offerings", description = "The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people.\n\nDestroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.", objectives = "" }
WordHunterWoW_QuestEN[32218] = { title = "Ashes of the Enemy", description = "The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", objectives = "" }
WordHunterWoW_QuestEN[32219] = { title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. I can't have these quilen threatening my research expedition.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", objectives = "" }
WordHunterWoW_QuestEN[32220] = { title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nHorde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", objectives = "" }
WordHunterWoW_QuestEN[32221] = { title = "Storming the Beach", description = "Our lumber supply is being jeopardized by constant attacks from Lion's Landing.\n\nWe've been able to keep the attackers at bay, but it's time to really show 'em some muscle!\n\nHead down to the coast and start splitting some skulls!", objectives = "" }
WordHunterWoW_QuestEN[32222] = { title = "WANTED: Chief Engineer Cogwrench", description = "Wanted for crimes against the Bilgewater Operation!\n\nChief Engineer Cogwrench was last seen building what appeared to be a giant spider tank on the edge of Bilgewater Beach.\n\nExtreme caution should be used when approaching.\n\nA large reward has been posted for Cogwrench's destruction.", objectives = "" }
WordHunterWoW_QuestEN[32223] = { title = "WANTED: Lieutenant Ethan Jacobson", description = "Wanted for crimes against the Domination Point forces!\n\nLieutenant Ethan Jacobson is responsible for leading several ground assaults against the Bilgewater lumber operation.\n\nLast spotted occupying an island south of Quickchop's Lumber Farm.", objectives = "" }
WordHunterWoW_QuestEN[32224] = { title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", objectives = "" }
WordHunterWoW_QuestEN[32225] = { title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory.\n\nThere is no time to delay. You must stop their ritual at once.", objectives = "" }
WordHunterWoW_QuestEN[32226] = { title = "Into the Crypts", description = "The Reliquary is having a field day out here, literally!\n\nEvery day, the researchers find more relics to study and catalog.\n\nRecently, one of our adventurers found this scroll at the Court of Bones.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", objectives = "" }
WordHunterWoW_QuestEN[32227] = { title = "Preventing a Future Threat", description = "The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become.\n\nIf you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.", objectives = "" }
WordHunterWoW_QuestEN[32228] = { title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", objectives = "" }
WordHunterWoW_QuestEN[32230] = { title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", objectives = "" }
WordHunterWoW_QuestEN[32232] = { title = "What's Inside Counts", description = "I noticed something strange on my last scouting mission. A group of Zandalari are performing a ritual on what appears to be a very large sentry. They may be trying to re-animate it.\n\nWe need that ritual stopped and the sentry destroyed. Anything that large can't be good.\n\nI've sent a scout ahead to observe their actions. Meet with her and figure out how to stop them.", objectives = "" }
WordHunterWoW_QuestEN[32233] = { title = "Very Disarming", description = "Look around you, {class}. What do you see? I see an opportunity.\n\nThe casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size.\n\nIn my scouting I've noticed the weapons are not very well guarded. This is where you come in...\n\nIf we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.", objectives = "" }
WordHunterWoW_QuestEN[32234] = { title = "Knowledge Is Power", description = "The Zandalari here practice a different kind of magic. We must understand it before we can defeat it, {class}.\n\nTheir control over the arcane and shadow is impressive. I wish to learn how they have achieved what so many others have not.\n\nI believe their ritual artifacts may hold the answers I seek. Bring me a sampling of the artifacts you find, and I will ensure you are rewarded properly.", objectives = "" }
WordHunterWoW_QuestEN[32235] = { title = "Flash! Aaaaaahhhh!", description = "The gnomes have brought their flying contraptions. I want my skies CLEAR!\n\nGet up there on whatever mount you have with you and destroy those paltry devices.\n\nYou may use this grog I \"acquired\" from our goblin allies. It would be better served blasting down gyrocopters than in the gullet of those little green fiends.", objectives = "" }
WordHunterWoW_QuestEN[32236] = { title = "Bug Off!", description = "This cave is crawlin' with nasty shale spiders! How's a girl supposed to get any work done with them gobbling up the miners AND the ore?!\n\nThis seemed like a good opportunity to use my newest invention, Bug Off. See, all you have to do is spray this stuff all over the shale spiders. They hate it and it doesn't seem to have many long term side-effects for the miners!\n\nWhat could possibly go wrong?\n\nTake this handy sprayer and get to work!", objectives = "" }
WordHunterWoW_QuestEN[32237] = { title = "Precious Resource", description = "What we have here is too much of a good thing, {name}!\n\nOur rig just can't handle the amount of oil we're pumping out of the ground. It's literally bursting at the seams! To be more accurate, it's bursting at the valves.\n\nI've been working double-time to get the valves repaired, but every time I finish the rounds, they're all broken again.\n\nIt's as if someone is following me... That's ridiculous though....\n\nMaybe you'll have better luck. Try getting as many of those valves tightened as you can.", objectives = "" }
WordHunterWoW_QuestEN[32238] = { title = "Universal Remote-Explode", description = "The Mecha-Pounders are really making things difficult down here, but I think I may have the solution!\n\nI made this universal remote for myself, but it looks like I hit a specific frequency that has an useful result!\n\nApparently this frequency weakens their armor!\n\nUse the remote to take them down a few notches then punch 'em in the face!", objectives = "" }
WordHunterWoW_QuestEN[32242] = { title = "Buried Secrets", description = "I am told that the mogu once possessed hundreds of hidden armories full of earth-shattering weapons.\n\nWhen a mogu army prepared for war, they struck fear and terror into the hearts of their enemies.\n\nTHIS is the knowledge I seek here on Pandaria!\n\nI have sent an expedition to study some ruins to the west, but they work as slowly as dim-witted peons!\n\nGo speak to Fanlyr Silverthorn, their leader. Tell him that I want to see results immediately.", objectives = "" }
WordHunterWoW_QuestEN[32243] = { title = "The Source of Korune Power", description = "Why hullo there! Have ya ever seen tha like o' these statues? Fascinatin'!\n\nI was scouting up along the ruins earlier, and I spotted somethin' innerestin' up on the highest rise.\n\nI couldn't get close enough, but I think it might be one o' these mogu statues, 'cept it was movin'!\n\nI can't get through all those nasty blood elves, but you look like you could.\n\nWould you mind going up there and bringing me back anything of interest?", objectives = "" }
WordHunterWoW_QuestEN[32244] = { title = "The Korune", description = "These terracotta wardens are fearsome, but not nearly as horrifying as the creature that we found at the top of the ruins.\n\nSome of our surviving scouts reported seeing some kind of mogu spellweaver on the highest rise to the north.\n\nHe practices a type of magic unlike any other we have seen.\n\nWe must learn whatever we can from this creature. Slay him, and bring me anything you find.", objectives = "" }
WordHunterWoW_QuestEN[32246] = { title = "Meet the Scout", description = "It has been two months since the parting of the mists. Alliance scouts, seeking a suitable landing site for the fleet, have engaged Horde forces on a beach in Krasarang Wilds.\n\nMeet with Scout Lynna and help secure the landing site.", objectives = "" }
WordHunterWoW_QuestEN[32247] = { title = "A King Among Men", description = "There's no time to waste, we need to find Troteman and secure the beach.\n\nWe should check on the dwarves, too - the Explorers' League is tough, but they're no army. They should be along the cliff just north of here.\n\nLet us ride, {class}. For our friends. For the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[32248] = { title = "A Little Patience", description = "King Varian needs decisive adventurers to help him resolve a showdown between Tyrande Whisperwind and a detachment of Horde warriors holed up in the Temple of the Red Crane.\n\nReport to him immediately!", objectives = "" }
WordHunterWoW_QuestEN[32249] = { title = "Meet the Scout", description = "It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds.\n\nMeet with Scout Rokla and help secure the landing site.", objectives = "" }
WordHunterWoW_QuestEN[32250] = { title = "The Might of the Warchief", description = "Come, {class}! I want to inspect this island and ensure that my landing team has done their job.\n\nBlood Guard Gro'tash should be somewhere on the northern side of the island looking for a suitable place to build our keep. The goblin survey team will have gone up the eastern coast in search of oil.\n\nLet us crush this pitiful display and claim this land for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[32251] = { title = "Dagger in the Dark", description = "Shadow Hunter Vol'jin has joined a group of Kor'kron scouts on an important mission for the warchief.\n\nOf course a proud member of the Horde such as yourself is welcome to go along, but be warned - it could get ugly.", objectives = "" }
WordHunterWoW_QuestEN[32252] = { title = "Harbingers of the Loa", description = "Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience.\n\nWe do not know what power the loa might possess, but I must ask you to put a stop to their rituals, {class}.", objectives = "" }
WordHunterWoW_QuestEN[32254] = { title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", objectives = "" }
WordHunterWoW_QuestEN[32255] = { title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Sunreaver property under my watch.", objectives = "" }
WordHunterWoW_QuestEN[32256] = { title = "Rise Of An Empire", description = "Warchief Garrosh Hellscream travels north with a squad of his most elite soldiers.\n\nReport to him with news of our continued victory against the Alliance.\n\nSpeak to Tak-Tak for transportation.", objectives = "" }
WordHunterWoW_QuestEN[32257] = { title = "Voice of the Gods", description = "Too slowly!? We are working as quickly as possible for the Warchief!\n\nWe must excavate carefully, catalogue each find, and of course follow safety procedures. He must understand!\n\nWell, we may have something to show him soon. Do you see that stone statue to the west?\n\nWe suspect it is an ancient stone storage vessel. Now we just have to find a way to open it.\n\nIf you would care to help us with our excavation, please go about it carefully.", objectives = "" }
WordHunterWoW_QuestEN[32262] = { title = "Captive Audience", description = "The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners!\n\nThere will be no discussion of prisoner exchange. We will handle this ourselves.\n\nGo to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.", objectives = "" }
WordHunterWoW_QuestEN[32264] = { title = "Spellbound", description = "Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items.\n\nA tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it.\n\nNow that we fight on opposite sides I see no issue in removing the tome from her possession.", objectives = "" }
WordHunterWoW_QuestEN[32265] = { title = "Charged Moganite", description = "We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Kirin Tor base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[32266] = { title = "Mana Manifestations", description = "Manafiends are nasty creatures. Small and easy to underestimate, but deadly to our magic casters. The Kirin Tor have these pests crawling all over Violet Rise.\n\nWe will need to handle them carefully. Alone they are easily managed, but in groups they become a different challenge altogether.\n\nGo to Violet Rise and cut down their numbers.", objectives = "" }
WordHunterWoW_QuestEN[32268] = { title = "Tactical Mana Bombs", description = "Ah, {name}, just the {race} I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Violet Rise to the southeast.\n\nHere, take these. I do not trust our standard soldiers with such firepower. Oh... and don't shake them, whatever you do.\n\nPlant one of the Kirin Tor ships, another one near their supplies, and the last on the construct they are building. ", objectives = "" }
WordHunterWoW_QuestEN[32269] = { title = "Breaking Down the Defenses", description = "We need to keep a close watch on the Kirin Tor and their day-to-day activities. Normally this would be easy. We would sneak in a spy and have them report back to us.\n\nHowever, we've run into a slight problem I believe you can help us with.\n\nThe Kirin Tor perimeter wards have increased in power. It's next to impossible to get someone past their lines. If they were disabled we might be able to sneak in before they can be repaired.", objectives = "" }
WordHunterWoW_QuestEN[32274] = { title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", objectives = "" }
WordHunterWoW_QuestEN[32275] = { title = "Surgical Death", description = "The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp.\n\nFind them in Za'Tual and remove the threat.", objectives = "" }
WordHunterWoW_QuestEN[32276] = { title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32277] = { title = "To the Skies!", description = "We can use the pterrorwing that you found to strike a decisive blow against the mogu. \n\nTheir mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there.\n\nLet me know when you are ready!", objectives = "" }
WordHunterWoW_QuestEN[32278] = { title = "Decisive Action", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", objectives = "" }
WordHunterWoW_QuestEN[32279] = { title = "The Fall of Shan Bu", description = "Long ago, Lei Shen found a rare clutch of storm dragon eggs. One of these creatures - Nalak - was particularly brutal, and Lei Shen took it for his own.\n\nThe Thunder King's servant, Shan Bu, works to resurrect Lei Shen's dragon, Nalak.\n\nWe must defeat Shan Bu and, if we are able, prevent him from resurrecting the dragon.", objectives = "" }
WordHunterWoW_QuestEN[32282] = { title = "Compy Stomp", description = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", objectives = "" }
WordHunterWoW_QuestEN[32283] = { title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", objectives = "" }
WordHunterWoW_QuestEN[32284] = { title = "Someone You Should See", description = "{name}? It is good fortune I find you.\n\nChen Stormstout says to give this to you and ask you to meet him at Binan Village of the Kun-Lai Summit.\n\nHe found a friend of yours who needs much luck to get healthy.\n\nChen say speak to Tak-Tak for fast travels.", objectives = "" }
WordHunterWoW_QuestEN[32285] = { title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[32287] = { title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.", objectives = "" }
WordHunterWoW_QuestEN[32288] = { title = "Bolstering the Defenses", description = "This island holds many dangers for us. Threats loom from every side. We must defend our hold on these shores at all costs.\n\nPerimeter wards have been placed around Dawnseeker Promontory. By default they will inflict damage, but are not fatal in their attack.\n\nNow is not the time to be merciful, {race}. The perimeter wards need to be deadly!\n\nGo and empower the perimeter wards surrounding our camp.", objectives = "" }
WordHunterWoW_QuestEN[32292] = { title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", objectives = "" }
WordHunterWoW_QuestEN[32293] = { title = "Among the Bones", description = "My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[32294] = { title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", objectives = "" }
WordHunterWoW_QuestEN[32295] = { title = "An Unusual Tome", description = "The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen.\n\nPerhaps one of your demonic companions can tell you more.", objectives = "" }
WordHunterWoW_QuestEN[32296] = { title = "Treasures of the Thunder King", description = "My scouts have returned with word that more of the treasures from Lei Shen's tomb are being brought up into the citadel. We have access to a secret sewer entrance, but a door bars us from intercepting the shipment. If we're going to succeed in this raid, we will need a key that only the most trusted of Lei Shen's forces carry.\n\nIf you get your hands on such a key, bring it to me.\n\nYou can keep whatever spoils you steal from our raid. I simply want to see that this shipment never makes it to Lei Shen.", objectives = "" }
WordHunterWoW_QuestEN[32297] = { title = "Direhorn or Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", objectives = "" }
WordHunterWoW_QuestEN[32298] = { title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", objectives = "" }
WordHunterWoW_QuestEN[32299] = { title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", objectives = "" }
WordHunterWoW_QuestEN[32300] = { title = "Disarming Irony", description = "Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs.\n\nI would enjoy the irony if these bombs were less dangerous.\n\nSearch for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.", objectives = "" }
WordHunterWoW_QuestEN[32301] = { title = "Old Enemies", description = "To think, we were once on the same side! The Sunreavers' treachery caught us all off guard. Never again!\n\nThey have shown their true natures to us. Siding with Garrosh and his madness has marked them all for death.\n\nKill any agent of the Sunreavers that you find. We will show them no mercy here.", objectives = "" }
WordHunterWoW_QuestEN[32302] = { title = "Desconstruction", description = "The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat.\n\nGo to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated!\n\nThis will be a message the Kirin Tor cannot easily ignore.", objectives = "" }
WordHunterWoW_QuestEN[32303] = { title = "Made for War", description = "Jaina thinks this battle will be easily won. I intend to show her how wrong she is!\n\nThe Kirin Tor brought a weapon with them that must be destroyed. The Arcane Destroyer is a large construct capable of turning the tides of war in their favor.\n\nDestroying this monstrosity would send a very clear message to Proudmoore.", objectives = "" }
WordHunterWoW_QuestEN[32304] = { title = "High Recognition", description = "", objectives = "" }
WordHunterWoW_QuestEN[32305] = { title = "Overpowered", description = "The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue.\n\nYou'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can.\n\nEach mana focus we destroy is another small victory for our cause.", objectives = "" }
WordHunterWoW_QuestEN[32307] = { title = "Reader for the Dead Tongue", description = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", objectives = "" }
WordHunterWoW_QuestEN[32309] = { title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", objectives = "" }
WordHunterWoW_QuestEN[32310] = { title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", objectives = "" }
WordHunterWoW_QuestEN[32311] = { title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Alliance!\n\nFind General Nazgrim in Domination Point and convince him of the importance of your mission.", objectives = "" }
WordHunterWoW_QuestEN[32312] = { title = "Enlistment Orders", description = "After the Council returned from their journey, they passed the knowledge of what they learned to all of the Warlock sects.\n\nHowever, they disappeared shortly afterwards...\n\n{name}! The tome you possess may be just the thing we need to convince them to join us in our assault against the Horde!\n\nFind Admiral Taylor in Lion's Landing and convince him of the importance of your mission.", objectives = "" }
WordHunterWoW_QuestEN[32313] = { title = "Hunt Helheim", description = "{name}... You've heard correctly. Warchief Garrosh tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, I have heard word that the Alliance is ahead of us. I heard that some Human Warlock by the name of Hareem Helheim has information which will help us locate them.\n\nHead to Lion's Landing, infiltrate their base and obtain the documents before Helheim's courier departs. Show Helheim no mercy.", objectives = "" }
WordHunterWoW_QuestEN[32314] = { title = "Slaughter Selenora", description = "{name}... You've heard correctly. King Varian tasked me with tracking down this Council of the Black Harvest.\n\nUnfortunately, the Horde is seeking them out as well. One of my spies recently sent word that Shadowmancer Selenora has the second piece of their journal.\n\nHead to Domination Point, slaughter Selenora and bring back whatever you find on her rotting cadaver.", objectives = "" }
WordHunterWoW_QuestEN[32315] = { title = "Anduin's Plea", description = "Ah, just the {class} I was looking for. I have received an urgent letter from the young Prince Anduin.\n\nHe is playing host to his father, King Wrynn, and several other Alliance dignitaries at the Shrine of Seven Stars in the Vale of Eternal Blossoms.\n\nAccording to his most recent correspondence, something bad is happening at the city.\n\nPlease go at once and speak with him. I must settle some affairs here at Lion's Landing, but I will join you soon.\n\nSpeak to Fennie if you'd like a ride to the Vale.", objectives = "" }
WordHunterWoW_QuestEN[32316] = { title = "Heart Of The Alliance", description = "I can't believe this has happened, {name}. After all we have been through here on Pandaria, will our people never learn from their past mistakes?\n\nBrann's expedition returned recently from Mogujia, bearing a sample of sha for study.\n\nI had my reservations about this endeavor in the first place, and my worst fears have been realized.\n\nThe sha has escaped containment. I do not need to explain the horror of bringing the sha into the heart of the Vale.\n\nWe must dispel any sha we can find, and quickly!", objectives = "" }
WordHunterWoW_QuestEN[32317] = { title = "Seeking the Soulstones", description = "{name}, take this - the journal of Jubeka Shadowbreaker.\n\nRead the journal and use the information contained within to track down where she went.\n\nFind her soulstones and use them to locate her.", objectives = "" }
WordHunterWoW_QuestEN[32318] = { title = "Regeneration Takes Time", description = "Vol'jin would be dead if he were any race other than a troll. His regeneration is impressive, but it is being blocked by a poison.\n\nWe need to cleanse this poison so that he can regenerate the damage.\n\nTake to the skies and travel southeast. Across the mountain tops of the Secret Aerie you will find needle sprites. Bring me some of the hardest needles from them you can find.\n\nWith them I can attempt an acupuncture technique that should purge the poison from his body and accelerate his regeneration.", objectives = "" }
WordHunterWoW_QuestEN[32319] = { title = "Find Thrall!", description = "<Vol'jin half opens an eye and begins to move his lips as if to speak.  Though no sound comes, you decipher two words.>\n\nFind Thrall.\n\n<With an effort, Vol'jin thrusts a hearthstone into your hands and then passes out.>", objectives = "" }
WordHunterWoW_QuestEN[32320] = { title = "The Horde Is Family", description = "This hearthstone was part of a conversation Vol'jin and I shared a long time ago.\n\nHe believes his people are in danger. I don't know what all has transpired in my absence, but I can at least do this for my friend.\n\nCome, {name}, travel with me to the Echo Isles. We must make sure that the Darkspear are safe.", objectives = "" }
WordHunterWoW_QuestEN[32321] = { title = "The Monkey King", description = "Ever since the Horde captured the Divine Bell I have been searching for a means to counter its power.\n\nMy research got as far as this tomb. I am going inside. If you follow me, I will share the rest as we go.\n\nIf we get separated, meet me back here at the entrance to the tomb. Speak to me when you are ready to proceed.", objectives = "" }
WordHunterWoW_QuestEN[32324] = { title = "Seek the Signal", description = "The soulstone shards fuse together easily in your hands.\n\nStrangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.", objectives = "" }
WordHunterWoW_QuestEN[32325] = { title = "Infiltrating the Black Temple", description = "It's clear that Jubeka's soulstone has lead you here to the Black Temple. \n\nThe question remains... why?\n\nThe only remaining option is to head inside and figure out why they were here.", objectives = "" }
WordHunterWoW_QuestEN[32326] = { title = "Insertion", description = "{name}! You'll do perfectly.\n\nWe know where the Alliance have hidden the Divine Bell. We've already inserted an agent into enemy territory, we just need you to help him execute his mission.\n\nPack up, {name}. You're headed to Darnassus.", objectives = "" }
WordHunterWoW_QuestEN[32327] = { title = "The Darnassus Mission", description = "The Divine Bell is in the city. We don't want to cause a scene, we just want the artifact. I need you to find a way in, WITHOUT getting caught. That means no mounts, no flying, no fighting.\n\nI can provide aid. I will magically cloak you, so you may move with stealth. I will also give you a small charm that you may use to return to safety, should you get in trouble.\n\nNow go, {name}. Go, locate the bell, and tag it to be teleported back with you.", objectives = "" }
WordHunterWoW_QuestEN[32328] = { title = "Victorious Return", description = "The portal by my side will return you safely to Domination Point. I will return behind you; I must clean up our tracks a bit before we leave, so that Proudmoore doesn't discover our involvement.", objectives = "" }
WordHunterWoW_QuestEN[32329] = { title = "Get My Results!", description = "Ah, {name}. The Warchief has instructed me to dispatch you to Silvermoon.\n\nHe grows impatient with the progress of Lor'themar's research and feels they might benefit from your... unique... experiences with the mogu.\n\nGo to Silvermoon and demand that Lor'themar increase the speed of his research.", objectives = "" }
WordHunterWoW_QuestEN[32330] = { title = "What's in the Box?", description = "We are trying to uncover the secrets of one of the mogu artifacts Garrosh insisted we investigate. It is proving most difficult, as anyone who probes it magically is greatly affected by raw, negative emotions.\n\nI called in the assistance of Arch-mage Aethas of the Sunreavers in the hopes that he and Rommath could crack this puzzle. They asked for you specifically - apparently you have some relevant experience?\n\nGo to the chamber below Farstrider Square east of here and see if you can assist them.", objectives = "" }
WordHunterWoW_QuestEN[32331] = { title = "The Kirin Tor", description = "{name}, King Varian has asked that I send you after his son to Dalaran. He believes you can help negotiate the withdrawal of blood elves there.\n\nThese \"Sunreavers\" claim fealty to the Horde and represent a major threat to the war effort.\n\nNow that our very own Jaina Proudmoore is in charge of the Kirin Tor it should be easy to convince her to remove this Horde threat to her city.\n\nUse the portal here in Lion's Landing to go to the Purple Parlor and lend what aid you can to Prince Anduin.", objectives = "" }
WordHunterWoW_QuestEN[32332] = { title = "The First Riddle: Mercy", description = "So, you wake up the Monkey King for a mallet hmmm? Answer first, these riddles three, and then the mallet you shall see.\n\nFirst riddle!\n\n  \"Softly singing a song of pain\n\n    There is a creature tortured and lame.\n\n    Way down south and beyond the wall,\n\n    It hides from its wikket masters' call.\n\n    Seek out the creature sad and somber,\n\n    And free it from its untamed amber.\"\n\nBring me the untamed amber.", objectives = "" }
WordHunterWoW_QuestEN[32333] = { title = "The Second Riddle: Fellowship", description = "You want to stop the Divine Bell? We need the mallet first.\n\nYou want the mallet? We need to be friends first.\n\nYou want to be friends? We need a Metal brew first. \n\nYou want a Metal brew? You need to go to the Shrine of Fellowship first. \n\nYou want to go to the Shrine of Fellowship? Great! It's in the Jade Forest southeast of the Tian Monastery.\n\nRing the bell and get the Monkey King some brew while there. Oh... you may have to fight for it.", objectives = "" }
WordHunterWoW_QuestEN[32334] = { title = "The Third Riddle: Strength", description = "The mallet you seek is not a toy for children,\n\nIt calls trouble like the song of a siren.\n\nA test of strength the Monkey King will require,\n\nBefore you receive this tool of your desire.\n\nAt the Temple of the White Tiger you will find\n\nA challenger to test how well you are resigned\n\nStep through the main door and then turn right down the ramp\n\nChallenge the ook waiting for you there like a champ!", objectives = "" }
WordHunterWoW_QuestEN[32335] = { title = "The Greatest Prank", description = "So riddles three you answered me. Good good. The Monkey King is not so old that he tells just anyone his tricks.\n\nIt was the greatest prank ever!\n\nYou want to hear story of the Mallet and the Monkey? Too bad! No choice!", objectives = "" }
WordHunterWoW_QuestEN[32336] = { title = "The Handle", description = "There once was a Chief named Ingoo Ingoo,\n\nWho beat me in a drink drink boogaloo.\n\nHe took the mallet's handle for winning,\n\nNot knowing you can't beat the King in drinking.\n\nMonkey King had to hide the mallet from the bell,\n\nBut Ingoo's children do not use the handle well.\n\nOver the years they have used the handle to do harm,\n\nNow we must find the current chief so we can disarm.\n\nGo south to Unga Ingoo, Monkey King meet you there.\n\nOnly wikkets show to a party with hands bare.", objectives = "" }
WordHunterWoW_QuestEN[32337] = { title = "The Head", description = "Monkey King receive word on where to find the head,\n\nThe hozen who got it has long since been dead. \n\nKunzen chiefs pass the relic from father to son, \n\nBut then virmen Skiggit came and the head it won. \n\nNow the wikket worships it in a hollow. \n\nSince it was too ookin' big for him to swallow. \n\nI sent a royal finder north to find him and stand. \n\nLook for finder in mountains west of the Heartland.", objectives = "" }
WordHunterWoW_QuestEN[32338] = { title = "The Harmonic Ointment", description = "Legends are not born, they are made.\n\nMuch like your next target, a mogu named \"The Blade.\" \n\nIn his bags you will find,\n\nAn ointment whose sound plays with the mind.\n\nBring this nibby ointment to the Monkey King!\n\nAnd with it, he shall make the mallet sing!\n\nTravel north along the wall, and when you reach the end, turn left.", objectives = "" }
WordHunterWoW_QuestEN[32340] = { title = "Plunder the Black Temple", description = "While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...", objectives = "" }
WordHunterWoW_QuestEN[32341] = { title = "Demonstrate Your Power", description = "Akama and his men are under siege by the forces you unleashed in the Reliquary of Souls. \n\nDemonstrate your power to Akama by saving his men from the demonic forces!", objectives = "" }
WordHunterWoW_QuestEN[32342] = { title = "The Spirit Trap", description = "Within the ruins we have identified several powerful mogu artifacts. They trapped spirits within, probably to use them in some ritual or conjuration.\n\nThey are a type of device that we haven't identified and desperately need to study - they may reveal more of the secrets of the mogu's spirit binding techniques. \n\nGo, find us a few samples so that we may continue a proper study.", objectives = "" }
WordHunterWoW_QuestEN[32343] = { title = "Ogudei's Lieutenants", description = "There are two extremely powerful mogu spirits that the Alliance unearthed in their ineptitude.\n\nThese are choice targets for us, {class}. If you kill them and collect each of their essences, we could make great progress on decoding the history of this strange ruin.", objectives = "" }
WordHunterWoW_QuestEN[32344] = { title = "It Is A Mystery", description = "We have detected several... anomalies in these mines, of an arcane or spiritual nature. They are disrupting our attempts to discern the nature of the magic used in the spirit binding rituals here.\n\nThey are quite elusive, but we've managed to isolate the arcane signature of one of these anomalies, and one of our mages has enchanted this bauble with its signature.\n\nTake the bauble. It will begin to glow more brightly as you approach the anomaly. Once you reach it, you can use the bauble to draw it out.", objectives = "" }
WordHunterWoW_QuestEN[32345] = { title = "We're Not Monsters!", description = "The Reliquary may have had a bad name in the past, but we're not monsters. We simply hold different views about archaeology than the Explorers' League.\n\nWe do focus on performing acts of heroism from time to time. So go, liberate some of the pandaren slave spirits in the ruins.", objectives = "" }
WordHunterWoW_QuestEN[32346] = { title = "Oi Ain't Afraid o' No Ghosts!", description = "Look. We got a nasty problem here, and ol' Troteman back at Lion's Landing's gonna throw us out of here if we don't get things under control.\n\nGive us a hand, please!", objectives = "" }
WordHunterWoW_QuestEN[32347] = { title = "Eviction Notice", description = "The bloody Reliquary's snuck into the ruins. They've taken the lower section and are conducting all kinds of magical shenanigans down there.\n\nIt's time we gave 'em an eviction notice, in the form of your boot in their rear!", objectives = "" }
WordHunterWoW_QuestEN[32348] = { title = "Kick 'em While They're Down", description = "The Alliance may think they have a stranglehold on the ruins, given that their base of operations is close.\n\nWe're going to disabuse them of that notion. Go take out some of their guards.", objectives = "" }
WordHunterWoW_QuestEN[32351] = { title = "Echoes of Thunder", description = "Ah, {name}, we meet again. I have heard some wondrous news.\n\nHigh Chieftain Baine Bloodhoof of the tauren has arrived here on Pandaria.\n\nHe meets with Warchief Garrosh Hellscream and Regent Lord Lor'themar Theron now, at the Shrine of Two Moons in the Vale of Eternal Blossoms.\n\nHe sent me a strange request - to send him a loyal champion of the Horde, capable of combat... and discretion.\n\nI can think of none better to send than you. Speak to Tak-Tak if you seek transport.", objectives = "" }
WordHunterWoW_QuestEN[32352] = { title = "A Gathering Storm", description = "If General Nazgrim sent you, then I trust you are capable of discretion.\n\nWhen I arrived here, I found Garrosh... experimenting... with some ancient power that he found in the mountains to the north.\n\nHe believes that this \"sha\" can strengthen our soldiers.\n\nUnfortunately, so far the results have been quite the opposite.\n\nOur troops are erupting into random violence. Go and interrogate them. If they threaten you, be prepared to defend yourself.", objectives = "" }
WordHunterWoW_QuestEN[32355] = { title = "The Harmonic Mallet", description = "{name}! Prince Anduin has somehow slipped his guards again. His control over the light is greatly increasing.\n\nHe was last seen heading to Kun-Lai Summit. He gave our mages the slip around the Valley of Emperors.\n\nCan you find him? He insists on searching for what he claims is a counter to the Divine Bell. Perhaps you can talk some sense into him before he seizes control of your mind and has you dance your way back here.\n\nTalk to Fennie for a ride into the mountains.", objectives = "" }
WordHunterWoW_QuestEN[32358] = { title = "The Soulcore", description = "The naaru looks at you expectantly and an image of the soulcore appears in your mind.", objectives = "" }
WordHunterWoW_QuestEN[32359] = { title = "The Eye of the Naaru", description = "The soulcore has transformed into a crystal. This is clearly the artifact that Kanrethad and Jubeka were attempting to create, but you still have no idea where they went.\n\nSeek out the Black Prince in the Tavern of the Mists and see if you can acquire some information on where they went.", objectives = "" }
WordHunterWoW_QuestEN[32360] = { title = "Awaiting the Black Harvest", description = "{name}, I have never heard of this Council of the Black Harvest. However, the fact that they are interested in my father's power concerns me greatly.\n\nHowever, I do have... contacts, who may be able to help us track them down. Most of my agents are preoccupied with the Alliance and Horde battle in Krasarang. Once that has settled down, I will help you.\n\nFor now, feel free to leave the Naaru relic in my protection, or not - just don't end up dead somewhere at the bottom of a swamp.", objectives = "" }
WordHunterWoW_QuestEN[32362] = { title = "The Fate of Dalaran", description = "Jaina is refusing to hear me out. Father was hoping I would have some pull with her, but I think she still sees me as a child.\n\nYou, on the other hand, are a hero of the Alliance and I know she respects your deeds.\n\nIs there something you can say to her to convince her we need her help?", objectives = "" }
WordHunterWoW_QuestEN[32363] = { title = "The Kun-Lai Expedition", description = "I have another message for you from High Chieftain Bloodhoof.\n\nIt seems you've made quite the impression on him.\n\nHe travels with the Warchief's vanguard into Kun-Lai Summit, to the north. They have set up an outpost, Garrosh'ar Advance, just east of One Keg.\n\nYou had best not keep him waiting. Speak to Tak-Tak for swift travel.", objectives = "" }
WordHunterWoW_QuestEN[32364] = { title = "Pandaren Medicine", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to find the ingredients for me.\n\nThe recipe can be found in a book near my other things, just behind me.", objectives = "" }
WordHunterWoW_QuestEN[32366] = { title = "A Lick of Fire", description = "6 Ruqin Firewine. This intense liquor helps relax the mind, allowing the recovery of past memories.\n\n<Scrawled along the side is another note.>\n\n(Note: May result in a terrible hangover.)", objectives = "" }
WordHunterWoW_QuestEN[32367] = { title = "A Bit of Yak", description = "3 Fresh Yak's Milk. Helps strengthen teeth and bones. Allows imbibers to return from their dream state.\n\n<The now-familiar handwriting now leaves a cryptic message.>\n\n(Why do all yaks look alike!?)", objectives = "" }
WordHunterWoW_QuestEN[32368] = { title = "Memory Wine", description = "The tincture is ready. Now, drink.", objectives = "" }
WordHunterWoW_QuestEN[32370] = { title = "The Kun-Lai Expedition", description = "Glory to the Alliance, {class}. We are making gains against the Horde in the Krasarang Wilds, albeit slowly.\n\nWhile we hold the front here, we need your help to fight a different battle - one that strikes at our enemy's heart.\n\nOur SI:7 informant, Agent Connelly, has sent word that a Horde vanguard is moving up into the northern reaches of Kun-Lai Summit.\n\nGo without delay. Make contact with Agent Connelly in the field, and find out what is going on.\n\nSpeak to Fennie over there for a flight in.", objectives = "" }
WordHunterWoW_QuestEN[32371] = { title = "Memory Wine", description = "<The radio static crackles, and Agent Connelly continues speaking.>\n\nNow comes the real challenge, laddie. \n\nHead on over to the center of camp and see what you can overhear.", objectives = "" }
WordHunterWoW_QuestEN[32372] = { title = "De-Subjugation", description = "The Kor'kron have been trained to be the finest, most loyal soldiers of the Warchief. Their presence here means that Garrosh fears an uprising.\n\nVol'jin and his people are as much a part of the Horde as any orc.\n\nWe must break this occupation and free the trolls. It pains me to say this, but you must eliminate enough of the Kor'kron so that the trolls can retake their city. Then meet me at Darkspear Hold so we might challenge their officer directly.", objectives = "" }
WordHunterWoW_QuestEN[32373] = { title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. The Alliance has landed on the shores with the full might of its navy. Your King aims to check Horde aggression in this new land.\n\nGarrosh Hellscream is propelling the Horde headfirst into battle, but King Varian Wrynn is a little more of a mystery to me. Do you have a moment? I'd like to talk to you about this leader of yours.", objectives = "" }
WordHunterWoW_QuestEN[32374] = { title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Alliance deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", objectives = "" }
WordHunterWoW_QuestEN[32375] = { title = "A Dash of That", description = "100 Buttonbelly Mushrooms. Must be freshly harvested from a wet, dark place.\n\n<Scrawled along the edge of the page is a hand-written note.>\n\nFungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)", objectives = "" }
WordHunterWoW_QuestEN[32376] = { title = "To the Valley!", description = "This sealed communication was sent for you, along with urgent orders to travel to the Valley of Emperors in Kun-Lai Summit.\n\nThis looks serious. I'd not delay if I were you.\n\nSpeak to Tak-Tak for transportation.", objectives = "" }
WordHunterWoW_QuestEN[32377] = { title = "A Kor'kron In Our Midst", description = "Garrosh is hell-bent on finding that Divine Bell. I wouldn't be surprised if he tore Kun-Lai Summit apart to find that artifact.\n\nThe Warchief's called a gathering at Garrosh'ar Advance, just to our north.\n\nI need to stay here to monitor troop movements, so you'll have to infiltrate their camp and overhear their discussion.\n\nGo to Garrosh'ar Advance and steal some Kor'kron Armor from Reavers, Honor Guards, and Scouts.\n\nTake this radio earpiece. Don't contact me... I'll contact you.", objectives = "" }
WordHunterWoW_QuestEN[32378] = { title = "Clearing a Path", description = "First thing's first. If we're going to take the leader captive, we'll need to thin the numbers of his agents.\n\nBe careful. These mogu are particularly dangerous - they appear to be manipulating the sha in ways we haven't seen before.", objectives = "" }
WordHunterWoW_QuestEN[32379] = { title = "Legacy of the Korune", description = "I'm not prepared to throw away more of our people fighting against an enemy we don't know or understand. \n\nSee if you can find any clues in the area as to who exactly these \"Korune\" mogu are. A contingency in case this operation doesn't go as planned.", objectives = "" }
WordHunterWoW_QuestEN[32380] = { title = "The Best Around", description = "We're going to need help if we hope to figure out Garrosh's plans for Pandaria.\n\nI have someone specific in mind, but he will not be easy to convince.\n\nAgent Connelly considers himself retired, but one does not simply leave the SI: 7. We've had an undercover agent following his every move for months.\n\nCurrently, he is disguising himself as a high roller at Bizmo's Brawlpub. Something about settling an old debt.\n\nMeet with our undercover agent in the Brawler's Guild.", objectives = "" }
WordHunterWoW_QuestEN[32381] = { title = "To Catch A Spy", description = "Now, I could tell you who Connelly is, but that would be too easy! To catch a spy you have to think like a spy.\n\nYou have to pass the test first!\n\nThe small things can say a lot about a person. It's all in the details.\n\nI'm going to give you a drink to deliver. I will give you a small detail about something the recipient is wearing. From there it will be up to you.\n\nBe careful who you pick to give drinks to. People here tend to get pretty hostile if you give them the wrong order!", objectives = "" }
WordHunterWoW_QuestEN[32382] = { title = "He's In Deep", description = "Agent Connelly has managed to infiltrate Garrosh's camp in Kun-Lai! He's been following their every move.\n\nConnelly requested you specifically to assist him in gathering some vital intelligence.\n\nHe sent along a disguise for you. Make sure you put it on before approaching the camp! It will no doubt be heavily guarded.\n\nHe insists you will know him when you see him. Something about your keen eye for details...\n\nGo talk to Fennie over there for a drop-off.", objectives = "" }
WordHunterWoW_QuestEN[32383] = { title = "Bugging Out", description = "I've managed to plant a few bugs around the camp, but there could always be more.\n\nI disguised the bugs to look like statues. They blend in perfectly with the other artifacts lying around.\n\nYour disguise should allow you to move freely around the camp. Just don't go near the dog and don't linger around Garrosh! Nero and Garrosh will see through your disguise.\n\nIf you get caught I can't help you. I can't compromise the mission!", objectives = "" }
WordHunterWoW_QuestEN[32384] = { title = "Trapping the Leader", description = "It is time to make our move. Go to the Tomb of Shadows, weaken him, and take him captive.\n\nI will stay here in case Garrosh arrives. He must be delayed so that we can take our prize before he destroys it in his anger.\n\nHurry!", objectives = "" }
WordHunterWoW_QuestEN[32388] = { title = "A Change of Command", description = "There's an orc general I've been keeping a close eye on. Warlord Bloodhilt curried a lot of favor with Garrosh Hellscream by beating back an Alliance advance in Southern Barrens. He's now entrenched within the fortress at Domination Point.\n\nI doubt the Alliance can take him out. But... you've proven me wrong before.\n\nIf you wish to finish him off, bring friends. Lots of friends.  ", objectives = "" }
WordHunterWoW_QuestEN[32389] = { title = "The Lion Roars", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", objectives = "" }
WordHunterWoW_QuestEN[32390] = { title = "Call of the Packmaster", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on your King. Would you be interested to hear what I've learned?", objectives = "" }
WordHunterWoW_QuestEN[32391] = { title = "The Ruins of Korune", description = "Garrosh sent a hundred riders to search the northern coast of Kun-Lai Summit, to seek a mogu crypt matching the one you saw in Shan Kien's memory.\n\nOut of those, one found the resting place of the Divine Bell.\n\nBlademaster Ishi is leading an advance party to secure the bell now.\n\nGo and assist him. Defend that artifact from anyone who might stand in your way!\n\nSpeak to Tak-Tak without delay. He can take you there.", objectives = "" }
WordHunterWoW_QuestEN[32392] = { title = "The Divine Bell", description = "If the Alliance thought they could steal the Divine Bell from us, they were wrong!\n\nEven now, we have them trapped in the crypts beneath us.\n\nDeath will be the price they pay for defying us.\n\nCome, {class}. Let us show them the error of their ways.", objectives = "" }
WordHunterWoW_QuestEN[32393] = { title = "The Ruins of Korune", description = "It's time for our boldest move yet, {name}.\n\nSince you acquired intel on the location of the Divine Bell, we've amassed a top team to excavate the artifact without delay.\n\nCommander Sarannha Skyglaive leads the expedition into the northern-most reaches of Kun-Lai Summit.\n\nJoin them at once, and use whatever skills you need to make the endeavor a success.\n\nGood luck, {class}. I don't need to tell you how important this mission is to the Alliance.\n\nSpeak to Fennie. She'll get you there quickly.", objectives = "" }
WordHunterWoW_QuestEN[32394] = { title = "The Divine Bell", description = "There's no telling what lies below, so I will lead the initial scouting party myself.\n\nIf your report was correct, then the Korune mogu hid the Divine Bell in the rooms below our very feet.\n\nI have a feeling they would not have left such a precious artifact unguarded.\n\nI could use a capable {class} such as yourself to watch my back. Let me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[32397] = { title = "He Won't Even Miss It", description = "I've noticed Garrosh and that Reliquary blood elf carrying around some sort of journal.\n\nThe journal is never more than a stone's throw away. It must be important!\n\nIf you can cause enough of a distraction, you may be able to swipe the journal off the table.\n\nThese yaks might just do the trick. Give one of 'em a tap and they'll do the rest.\n\nJust be ready to move fast!", objectives = "" }
WordHunterWoW_QuestEN[32398] = { title = "The Bell Speaks", description = "Your efforts have culminated in this moment, {class}.\n\nWarchief Garrosh gathers the most elite champions of the Horde in Kun-Lai Summit to witness the ringing of the Divine Bell.\n\nYou have more than earned the right to participate.\n\nGo now. The dawn of the new Horde begins today.\n\nSpeak to Tak-Tak. He should be able to secure your travel arrangements.", objectives = "" }
WordHunterWoW_QuestEN[32399] = { title = "Breath of Darkest Shadow", description = "It is time, {name}. We have traveled a long path to reach this moment.\n\nToday, our Warchief, Garrosh Hellscream, will change the course of our people's history forever.\n\nToday, we witness the birth of Garrosh's Horde!\n\nDo not let anything interfere with the ceremony!", objectives = "" }
WordHunterWoW_QuestEN[32400] = { title = "The Bell Speaks", description = "Horde forces are amassing in huge numbers at the Emperor's Reach, high up in the mountains of Kun-Lai Summit.\n\nThe area is an ancient mogu palace, and certainly a source of untold power.\n\nThis can only mean one thing. Garrosh is going to use the Divine Bell, and Anduin... and the Harmonic Mallet... are both missing.\n\nI have no doubt that the fool boy went north by himself.\n\nI don't have time to gather an elite force to detain him. You must go and stop Anduin.\n\nFennie can take you.", objectives = "" }
WordHunterWoW_QuestEN[32401] = { title = "Breath of Darkest Shadow", description = "Garrosh is right over there, and he's going to ring that bell at any moment.\n\nWe don't have time to wait for my father's army. This is our only chance to stop him!\n\nI'll attempt to appeal to his senses before resorting to using the Harmonic Mallet.\n\nCharge in whenever you're ready, {name}. I'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[32402] = { title = "The Situation In Dalaran", description = "The night elves learned that the Divine Bell was stolen. This much we anticipated.\n\nHowever, they've also found out that the \"neutral\" Sunreavers of Dalaran were complicit. Now, we've got a situation.\n\nI need you to go to Dalaran. Speak with Kromthar for a ride. You are to rendezvous with Grand Magister Rommath once you arrive.", objectives = "" }
WordHunterWoW_QuestEN[32403] = { title = "It Starts in the Sewers", description = "Compared to the rest of the city, this part of the sewers is relatively calm. This is good - we can extract more Sunreavers in peace than we can in war.\n\nFind as many citizens as you can. Tell them that it is not safe here, that they must leave the city at once.\n\nAnd try to stay clear of the Silver Covenant. We don't want to cause a scene if we can avoid it. Not yet, anyhow.", objectives = "" }
WordHunterWoW_QuestEN[32404] = { title = "Violence in the Arena", description = "As I suspected, it gets worse up ahead. The Silver Covenant is outright attacking innocent Sunreavers!\n\nThis cannot stand. While our prime directive is to rescue Aethas Sunreaver, we must also protect as many blood elves as we can.\n\nI will continue to scout ahead. Fight well, {class}!", objectives = "" }
WordHunterWoW_QuestEN[32405] = { title = "Hand of the Silver Covenant", description = "Every Sunreaver Jaina expels from this city is a new blade that fights for the Horde. For US.\n\nI'm off to gather more strong elves. You've proven your hand in combat thus far - go take care of that creep in the black market.\n\nWhen you're done, we'll meet at the ramp and prepare to go aboveground.", objectives = "" }
WordHunterWoW_QuestEN[32406] = { title = "A Tactical Assault", description = "If we're to survive up above ground, we're going to need a base of operations.\n\nI'm going to try to take the center of the city. It's risky, but hopefully Jaina and the Silver Covenant won't expect it.\n\nStay by my side now, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32408] = { title = "The Silver Covenant's Stronghold", description = "I have it on good authority that Archmage Aethas Sunreaver is being held in the Silver Enclave, home of the Silver Covenant. Arcanist Rathaella holds him in captivity.\n\nMost Covenant agents are out slaughtering Sunreavers right now, which means our chance is ripe. Slay Rathaella, and spring Aethas from his prison.", objectives = "" }
WordHunterWoW_QuestEN[32409] = { title = "The Kirin Tor's True Colors", description = "Any pretense that the Kirin Tor might have had at being a \"neutral\" group can officially be discarded. I'm now hearing that Jaina's got Alliance troops stowed away near Antonidas Memorial.\n\nThe area's free of Sunreavers, but it still makes my blood boil to see such blatant favoritism from the Kirin Tor.\n\nGo visit the memorial, {name}... and give those Alliance dogs a good kick on your way through.", objectives = "" }
WordHunterWoW_QuestEN[32410] = { title = "Krasus' Landing", description = "We can rescue as many Sunreavers as we want, but if they can't escape, then there's no point.\n\nThe Silver Covenant will certainly be subduing and killing the Sunreavers' dragonhawks. Put a stop to it.", objectives = "" }
WordHunterWoW_QuestEN[32411] = { title = "The Remaining Sunreavers", description = "There's still a number of significant Sunreavers who haven't been accounted for. Odds are that they're in the Sunreaver's Sanctuary, caught by surprise.\n\n<Rommath hands you an artifact, clearly made by blood elf hands.>\n\nThe place is crawling with Silver Covenant. You'll need to get in, use the Tear to evacuate the VIPs, and then get out.\n\nStay alive, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32412] = { title = "One Last Grasp", description = "We've looked everywhere he's likely to be, except for one place: the Violet Citadel.\n\nFind out if Archmage Aethas is being held within the citadel, {name}. We may get lucky. If not... at least we saved a number of lives today.", objectives = "" }
WordHunterWoW_QuestEN[32413] = { title = "A Return to Krasarang", description = "Wherever your loyalties might lie - with Rommath and I, with Garrosh, or elsewhere - one thing is true: your acts today were truly heroic.\n\nI can arrange for your transport back to Krasarang Wilds. Speak with me if you would like passage back to Pandaria, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32414] = { title = "Darnassus Attacked?", description = "As you know, our night elven allies moved the Divine Bell you retrieved to Darnassus for safekeeping and study. Moments ago, they portaled some Highbourne mages over here to ask for backup. Details are hazy - some sort of stealth attack on the city?\n\nI don't know what to make of it, but Jaina Proudmoore is already on the scene and I suspect they need all the help they can get.\n\nSpeak to Seamus Goldenkicks over there for a quick portal to Darnassus. Find Jaina!", objectives = "" }
WordHunterWoW_QuestEN[32416] = { title = "Jaina's Resolution", description = "For too long, I have toiled to mend fences between Alliance and Horde. Time and time again, I've given the Horde the benefit of the doubt - and time and time again, they stab me in the back.\n\nI refuse to be betrayed again! If the Horde intends to use the Kirin Tor as a weapon against the Alliance, then they have no place in Dalaran.\n\nCome with me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32417] = { title = "Sewer Cleaning", description = "Jaina's doing a good job taking care of Sunreavers above ground, but there's still plenty rooting around in the sewers.\n\nGo find those lying rats and exterminate them!", objectives = "" }
WordHunterWoW_QuestEN[32418] = { title = "Unfair Trade", description = "Most shopkeepers in the Magus Commerce Exchange have sided with the Silver Covenant, but there remain a few holdouts that must be taken care of.\n\n<Vereesa shows you a list of names.>\n\nThey will not go easily.", objectives = "" }
WordHunterWoW_QuestEN[32419] = { title = "Nowhere to Hide", description = "The Sunreaver's Sanctuary is still crawling with those Horde-loving Sunreavers.\n\nJaina will have sent the reasonable ones to the Violet Hold. The rest refuse to leave, raising their weapons against us.\n\nShow them the cost of their defiance. They now face the judgment of the Alliance, the Silver Covenant, and the Kirin Tor!", objectives = "" }
WordHunterWoW_QuestEN[32420] = { title = "Cashing Out", description = "I just saw one of the Sunreavers - Brasael, I think his name was - running off in the direction of the bank to the north. No doubt he's trying to gather whatever assets he can before he leaves.\n\nHead him off and make sure he doesn't steal any resources from our coffers. He relinquished whatever funds he left in the bank when he and his Sunreaver kind betrayed us.", objectives = "" }
WordHunterWoW_QuestEN[32421] = { title = "Nowhere to Run", description = "Compliant Sunreavers will be sent to the Violet Hold. Defiant ones are put to the sword.\n\nNONE are to escape.\n\nThe Sunreavers keep their dragonhawk mounts on Krasus' Landing. Take this dust, and use it to render them incapable of flying.\n\nOr kill them. I don't care.", objectives = "" }
WordHunterWoW_QuestEN[32423] = { title = "What Had To Be Done", description = "Thank you for your aid today, {name}. I will be handling the purge from here on out.\n\nJaina will soon be off to Lion's Landing, to speak with King Varian. She asked for your attendance.", objectives = "" }
WordHunterWoW_QuestEN[32426] = { title = "Stirred, Not Shaken", description = "Alright, I'll tell you how to find Connelly.\n\nAgent Connelly is currently posing as the high roller, Professor Kilt. He spends most of his time in the Boom Room. Rumor has it he's after one of the fighters for some long forgotten betrayal.\n\nUnfortunately, the lounge is by invitation only. Lucky for you I just happen to have an invitation.\n\nTry not to look too obvious when you walk past the bouncers. If you get caught you didn't get this pass from me.\n\nIn fact you and I have never met!", objectives = "" }
WordHunterWoW_QuestEN[32427] = { title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. Your Warchief aims to impress the Pandaren with the full might of the Horde's military. He will lay claim to the resources of this land, with or without Pandaren aid.\n\nI understand your leader's aims, but I really want to understand the Warchief himself. What drives him? And where is the Horde ultimately going? I'd like to talk to you about this leader of yours.", objectives = "" }
WordHunterWoW_QuestEN[32428] = { title = "Pandaren Spirit Tamer", description = "Legend tells of legendary pandaren spirits that roam the lands of Pandaria.  Find them and defeat them in a pet battle.", objectives = "" }
WordHunterWoW_QuestEN[32429] = { title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Horde deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", objectives = "" }
WordHunterWoW_QuestEN[32430] = { title = "A Change of Command", description = "There's an Alliance dwarf I've been keeping a close eye on. High Marshal Twinbraid proved to be a nuisance in Southern Barrens when he struck back at the Horde after the loss of Bael Modan. He's now entrenched within the Alliance stronghold in Lion's Landing, helping to orchestrate the Krasarang counter-offensive.\n\nOnly a legendary group of Horde heroes could possibly defeat him.\n\nIf you wish to finish him off, bring friends. Lots of friends.", objectives = "" }
WordHunterWoW_QuestEN[32431] = { title = "Glory to the Horde", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", objectives = "" }
WordHunterWoW_QuestEN[32432] = { title = "The Soul of the Horde", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on Garrosh Hellscream. Would you be interested to hear what I've learned?", objectives = "" }
WordHunterWoW_QuestEN[32433] = { title = "Undermining the Under Miner", description = "Grezik Oregrind has become a nuisance that must be eliminated.\n\nThis land responds to all of our actions as I am sure you are aware, {class}. Because of this, we cannot allow the goblins to haphazardly destroy it.\n\nOur scouts have reported Sha emerging from Oregrind's Dig. The brains behind the operation is a goblin named Grezik Oregrind.\n\nDestroy him and perhaps we will stall the operation just long enough to contain the Sha.", objectives = "" }
WordHunterWoW_QuestEN[32434] = { title = "Burning Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "" }
WordHunterWoW_QuestEN[32439] = { title = "Flowing Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "" }
WordHunterWoW_QuestEN[32440] = { title = "Whispering Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "" }
WordHunterWoW_QuestEN[32441] = { title = "Thundering Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "" }
WordHunterWoW_QuestEN[32442] = { title = "Impending Danger", description = "Our scouts have sighted a fel command ship looming on the horizon, Grandmaster. It appears to be headed on a collision course with the Wandering Isle.\n\nWe should prepare our troops for the worst case situation - an all out attack.\n\nIn the meantime, let us send our champions ahead to try and divert the Legion ship's attention.", objectives = "" }
WordHunterWoW_QuestEN[32446] = { title = "Dis-Assembly Required", description = "Those shredders are becoming a problem down there, {class}.\n\nWe've sent in the Mecha-Pounders, but it just isn't enough. They're getting damaged faster than we can repair 'em!\n\nI happened upon this strange remote while scouting. With a little bit of re-configurin' I think we can use it.\n\nTry usin' it on the Jungle Shredders. Hopefully it will destroy them and then you can bring me the scrap metal.", objectives = "" }
WordHunterWoW_QuestEN[32448] = { title = "Ties with the Past", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to recover the essential ingredient for me. We need the spirit essence of a mogu that lived in the time of the memory we wish to see.\n\nYou should be able to find just such a spirit inside the Path of Conquerors, to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[32449] = { title = "The Ruins of Ogudei", description = "Our scouts at Sparkrocket Outpost have reported some new activity near an area called the Ruins of Ogudei.\n\nWe need to gather intelligence on what it is the Alliance are doing, and more importantly what it is they found. We cannot afford to have any unknowns.\n\nMeet up with Belloc Brightblade in Sparkrocket Outpost and find out what he knows.", objectives = "" }
WordHunterWoW_QuestEN[32450] = { title = "The Time Is Now!", description = "Now we take the fight to them, {class}!\n\nReport to Shademaster Kiryn in Sparkrocket Outpost. She will have your orders.\n\nNow we'll see how they handle the full might of the Horde rushing at their precious keep!", objectives = "" }
WordHunterWoW_QuestEN[32451] = { title = "Send A Message", description = "It's time we show these Horde mongrels the full strength of the Alliance! Today we bring the battle to their door.\n\nReport to Admiral Rogers aboard the Skyfire. She will have further instructions.\n\nGood luck out there, {class}. Do the Alliance proud!", objectives = "" }
WordHunterWoW_QuestEN[32452] = { title = "And Then There Were Goblins", description = "We're fighting a war on all fronts, {class}. Even Pandaria itself needs our protection.\n\nThe Bilgewater goblins are destroying land that doesn't belong to them. They must be stopped!\n\nReport to Sky Admiral Rogers aboard the Skyfire. From her vantage point she should have a good idea of where their weak spots are.", objectives = "" }
WordHunterWoW_QuestEN[32455] = { title = "The Silence", description = "D..did we... do it?\n\n<Anduin mumbles the words, even though the effort clearly costs him.>\n\nL..look... in.. my... bag...\n\nUse... flare...", objectives = "" }
WordHunterWoW_QuestEN[32457] = { title = "The Thunder King", description = "Are you aware of recent events in Kun-Lai Summit? The Zandalari have landed on the northern shores in great numbers and have set about renewing old alliances. To that end, they have resurrected The Thunder King.\n\nEven among the mogu, the name of the first emperor commands awe and fear. The Thunder King founded a vast empire of slavery and suffering... but also of power, riches, and splendor.\n\nWe will take the fight to him soon. Find me when your faction makes its move.", objectives = "" }
WordHunterWoW_QuestEN[32458] = { title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! My father's fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our ships to these shores. We just need to collect charms of good fortune to make it happen.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", objectives = "" }
WordHunterWoW_QuestEN[32460] = { title = "Tracking the Thieves", description = "We WILL get to the bottom of this.\n\n{name}, you're coming with me. We'll search every inch of this city if we have to, but we'll find out how they took the bell... and where.\n\nI'm picking up traces of arcane magic here... we need to follow the trail!", objectives = "" }
WordHunterWoW_QuestEN[32461] = { title = "The Order of the Cloud Serpent", description = "Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent.\n\nBefore you may fly the skies on this powerful creature, you must first earn the skill to ride it.\n\nThe Order of the Cloud Serpent can teach you the knowledge that you seek.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "" }
WordHunterWoW_QuestEN[32468] = { title = "Crystal Clarity", description = "You know, there is a way we can improve your S.E.L.F.I.E. cam, if you're interested. With the right focusing lens, I could add all kinds of features to that thing.\n\nI've heard that way out on old Yojamba Isle in Stranglethorn Vale, the mother of all basilisks has been seen. Her hide is dotted with gems that'd make the perfect lens, if I could get my hands on them.\n\nShe's not going to go down easy, though. You might want to bring some friends along.", objectives = "" }
WordHunterWoW_QuestEN[32469] = { title = "Crystal Clarity", description = "Hi again! Oh, I forgot to tell you! I've devised a foolproof way to improve your S.E.L.F.I.E. cam! \n\nIn fact, with just the right gemstones, I can make a lens that would allow us to do all sorts of things!\n\nSome fellow explorers have told me about a large basilisk out on Yojamba Isle in Stranglethorn Vale. Her hide is dotted with tons of high-quality crystals! What a perfect coincidence!\n\nShe sounds pretty tough, though! You should bring some friends!", objectives = "" }
WordHunterWoW_QuestEN[32470] = { title = "Light Camera Action", description = "Oh, hi! Isn't this a great shot? I love my S.E.L.F.I.E. camera!\n\nDo you want me to make you one, too? I only need a few parts!\n\nFor the strap, I'll need a Russet Belt from one of the armor merchants in Stormwind.\n\nI've already ordered more housings, you're welcome to take one, you just have to find where my shipment ended up!\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nOk, are you ready for a little photography action?!", objectives = "" }
WordHunterWoW_QuestEN[32471] = { title = "Light Camera Action", description = "You look like you've got a discerning eye for the visual arts, want to try your hand at photography?\n\nI can make you one of these S.E.L.F.I.E. cameras, I just need a few parts.\n\nFor the strap, grab me a Russet Belt from one of the armor merchants around here.\n\nI've got a shipment of extra housings waiting by the back entrance to the city, grab me one when you're over there.\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nNow get out there, kid. Fame awaits!", objectives = "" }
WordHunterWoW_QuestEN[32475] = { title = "A Spark of Life", description = "The Thunder-Laced Egg burns your hand as you hold it. You recall that Yalia Sagewhisper of the Shado-Pan discussing the history of the Thundering Cloud Serpents, perhaps she will know what to do with it.", objectives = "" }
WordHunterWoW_QuestEN[32485] = { title = "Bolstering the Defenses", description = "This island is a dangerous place, {name}. We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers.\n\nI had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings!\n\nWith your help we can super-charge the wards into a more deadly defense system.", objectives = "" }
WordHunterWoW_QuestEN[32489] = { title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in the Undercity.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", objectives = "" }
WordHunterWoW_QuestEN[32491] = { title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", objectives = "" }
WordHunterWoW_QuestEN[32493] = { title = "They All Fall Down", description = "The Zandalari do not tolerate weakness in their ranks, {class}.\n\nThose that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds.\n\nI wish to study their essence. For this I will need your help.\n\nTake this resonance crystal and siphon the spirits from the sentry corpses.\n\n Do not allow them to escape!", objectives = "" }
WordHunterWoW_QuestEN[32494] = { title = "Power Play", description = "The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power.\n\nTwo such items exist here. To be specific, two masks, worn by two brothers.\n\nSpiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed.\n\nKill them and return their masks to me. I will make sure the masks are disposed of.", objectives = "" }
WordHunterWoW_QuestEN[32495] = { title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", objectives = "" }
WordHunterWoW_QuestEN[32496] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[32497] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32498] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32499] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32500] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32501] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32502] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[32503] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[32505] = { title = "The Crumbled Chamberlain", description = "You there! Assist me.\n\nIn life I was the Royal Chamberlain for his majesty, the Thunder King. For my dedication, I was condemned to this stone form, forever forced to watch over a portion of his wealth.\n\nSomeone has desecrated my glorious body and sent pieces of it across the island. The thought of spending an eternity as nothing more than a head depresses me.\n\nSearch the island, recover these pieces and I shall grant you one of his majesty's treasures.", objectives = "" }
WordHunterWoW_QuestEN[32506] = { title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", objectives = "" }
WordHunterWoW_QuestEN[32507] = { title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Sunreavers behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "" }
WordHunterWoW_QuestEN[32509] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[32510] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[32517] = { title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", objectives = "" }
WordHunterWoW_QuestEN[32520] = { title = "Competing Magic", description = "My scouts have spotted a dangerous Zandalari just this side of Za'Tual. I need someone capable to see him dispatched. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[32521] = { title = "Encroaching Force", description = "My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[32522] = { title = "Imposing Threat", description = "My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for me?", objectives = "" }
WordHunterWoW_QuestEN[32523] = { title = "The Beast Pens", description = "We need to counter the beasts the Zandalari are using to strike at our camp. I have dispatched Scout Captain Elsia to the Beast Pens along with some war mages to provide cover.\n\nGo and find her east of here near the breaches in the wall and help her trim down the cavalry and siege beasts being levied against us.\n\nThey are masked, so look for the shimmers of their magical cloaking spells.", objectives = "" }
WordHunterWoW_QuestEN[32524] = { title = "The Beating of Troll Drums", description = "Do you hear that, {class}? The beating of war drums in the distance. The Zandalari are preparing for us.\n\nLet's not give them the luxury of time to organize their defenses. We need to push the attack now!\n\nReport to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.", objectives = "" }
WordHunterWoW_QuestEN[32525] = { title = "Ashes of the Enemy", description = "The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", objectives = "" }
WordHunterWoW_QuestEN[32526] = { title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nAlliance or Horde, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", objectives = "" }
WordHunterWoW_QuestEN[32527] = { title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[32528] = { title = "Into the Crypts", description = "Every day, we uncover additional relics from the Court of Bones.\n\nRecently, we discovered this scroll amongst the gravestones in one of the deepest crypts.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", objectives = "" }
WordHunterWoW_QuestEN[32529] = { title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise.\n\nThere is no time to delay. You must stop their ritual at once.", objectives = "" }
WordHunterWoW_QuestEN[32530] = { title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter.\n\nHe thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", objectives = "" }
WordHunterWoW_QuestEN[32531] = { title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", objectives = "" }
WordHunterWoW_QuestEN[32532] = { title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", objectives = "" }
WordHunterWoW_QuestEN[32533] = { title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. These quilen are too dangerous to ignore.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", objectives = "" }
WordHunterWoW_QuestEN[32535] = { title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Alliance takes full control of this island, we can look for more permanent solutions.", objectives = "" }
WordHunterWoW_QuestEN[32536] = { title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", objectives = "" }
WordHunterWoW_QuestEN[32537] = { title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Silver Covenant property under my watch.", objectives = "" }
WordHunterWoW_QuestEN[32538] = { title = "Heinous Sacrifice", description = "Some of the strongest of the spiritbinders perform heinous rites to their wretched gods.\n\nWe've devised a method to destroy their altars, so the difficult task will be getting to each altar alive.\n\nVenture into the depths of Za'Tual and destroy their altars.", objectives = "" }
WordHunterWoW_QuestEN[32539] = { title = "Dark Offerings", description = "The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process.\n\nDestroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.", objectives = "" }
WordHunterWoW_QuestEN[32540] = { title = "Harbingers of the Loa", description = "If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil.\n\nPlease, venture into the troll camp and put a stop to these unspeakable rituals.", objectives = "" }
WordHunterWoW_QuestEN[32541] = { title = "Preventing a Future Threat", description = "It pains me to think of the torture the poor skyscreamers  must endure as the trolls train them to become implements of war.\n\nThe hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.", objectives = "" }
WordHunterWoW_QuestEN[32542] = { title = "Surgical Strike", description = "Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day.\n\nDispose of these threats in Za'Tual, {race}, and watch the might of the trolls weaken.", objectives = "" }
WordHunterWoW_QuestEN[32543] = { title = "Dangers of Za'Tual", description = "The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, {name}.\n\nEnter Za'Tual to and show them the risks associated with opposing the likes of you.", objectives = "" }
WordHunterWoW_QuestEN[32544] = { title = "Pterrible Ptorment", description = "One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters.\n\nKill those that inflict such torment on the creature and we can only hope that it will return to the skies.", objectives = "" }
WordHunterWoW_QuestEN[32545] = { title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", objectives = "" }
WordHunterWoW_QuestEN[32546] = { title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", objectives = "" }
WordHunterWoW_QuestEN[32547] = { title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in Booty Bay.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", objectives = "" }
WordHunterWoW_QuestEN[32548] = { title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", objectives = "" }
WordHunterWoW_QuestEN[32549] = { title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Kirin Tor behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "" }
WordHunterWoW_QuestEN[32550] = { title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.", objectives = "" }
WordHunterWoW_QuestEN[32551] = { title = "Compy Stomp", description = "The raptors and saurid of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", objectives = "" }
WordHunterWoW_QuestEN[32552] = { title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", objectives = "" }
WordHunterWoW_QuestEN[32553] = { title = "Direhorn vs Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", objectives = "" }
WordHunterWoW_QuestEN[32554] = { title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", objectives = "" }
WordHunterWoW_QuestEN[32555] = { title = "Centuries in Sentries", description = "Sacrifices are common place in Zandalari society. There is however one oddity among these barbaric rituals; volunteers. They treat it as a great honor!\n\nThe weak still seek to contribute, even if that means giving their lives to be bound to the sentries you see walking around. Locked away in service to their people.\n\nTake this resonating crystal. Once destroyed, drain the sentry of its Zandalari inhabitant. Return the crystal to me when your task is complete.", objectives = "" }
WordHunterWoW_QuestEN[32556] = { title = "The More You Know", description = "This whole area is littered with Zandalari artifacts. I would be lying if I said studying them didn't interest me. I am fascinated by the significance of these objects to their rituals.\n\nThe more we understand our enemies, the better prepared we are to defeat them.\n\nIf I am to study them, I will need to see them up close. Bring me as many artifacts as you can find. ", objectives = "" }
WordHunterWoW_QuestEN[32557] = { title = "Out of Enemy Hands", description = "Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands.\n\nThe Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage.\n\nSteal as many of the weapons as you can find.", objectives = "" }
WordHunterWoW_QuestEN[32558] = { title = "All In the Family", description = "Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated.\n\nTheir power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on.\n\nWe must deal with the brothers and destroy their masks before they fall into the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[32559] = { title = "Even Giants Fall", description = "The Zandalari worship the loa; animal spirits they often call to their aid. They may be trying to bind these spirits into a huge golem. The outcome would be disastrous.\n\nI've sent ahead a scout to gather more information, but I think this task may require your expertise.\n\nStop that ritual at all costs!", objectives = "" }
WordHunterWoW_QuestEN[32560] = { title = "Keep It Secret", description = "The Zandalari here are a threat to our campaign, {class}.\n\nTheir use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence.\n\nWe cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic.\n\nTheir numbers must be thinned. I will leave this task to you.", objectives = "" }
WordHunterWoW_QuestEN[32561] = { title = "Competing Magic", description = "One of my scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[32562] = { title = "Imposing Threat", description = "One of my scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[32563] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", objectives = "" }
WordHunterWoW_QuestEN[32564] = { title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", objectives = "" }
WordHunterWoW_QuestEN[32565] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", objectives = "" }
WordHunterWoW_QuestEN[32567] = { title = "The Beast Pens", description = "I do not want to see another Zandalari beast rider breach our defenses!\n\nI have dispatched Scout Captain Daelin and some war mages to the Beast Pens northwest of here. Their mission is to infiltrate and harass the Zandalari siege and cavalry units. I want you to join them and lend your expertise.\n\nKeep an eye out for the tell tale shimmer of their magical cloaking spell.", objectives = "" }
WordHunterWoW_QuestEN[32568] = { title = "No Time To Rest", description = "We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold.\n\nNow, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.", objectives = "" }
WordHunterWoW_QuestEN[32570] = { title = "Gather Scout Reports", description = "", objectives = "" }
WordHunterWoW_QuestEN[32571] = { title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", objectives = "" }
WordHunterWoW_QuestEN[32572] = { title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[32573] = { title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.", objectives = "" }
WordHunterWoW_QuestEN[32574] = { title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", objectives = "" }
WordHunterWoW_QuestEN[32575] = { title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", objectives = "" }
WordHunterWoW_QuestEN[32576] = { title = "Competing Magic", description = "One of the scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to handle this?", objectives = "" }
WordHunterWoW_QuestEN[32577] = { title = "Imposing Threat", description = "One of Vereesa's scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to handle this?", objectives = "" }
WordHunterWoW_QuestEN[32578] = { title = "Among the Bones", description = "The scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. We need someone capable to see him dispatched. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[32579] = { title = "Competing Magic", description = "The scouts have spotted a dangerous Zandalari just this side of Za'Tual. We need someone capable to see him dispatched. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[32580] = { title = "Encroaching Force", description = "We've received word of a Zandalari war party up the beach, north of our foothold. We need them hunted down and killed.\n\nAre you willing to do this thing for us, {class}?", objectives = "" }
WordHunterWoW_QuestEN[32581] = { title = "Imposing Threat", description = "The scryers have spotted a mogu leader at the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for us?", objectives = "" }
WordHunterWoW_QuestEN[32582] = { title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", objectives = "" }
WordHunterWoW_QuestEN[32583] = { title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", objectives = "" }
WordHunterWoW_QuestEN[32584] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", objectives = "" }
WordHunterWoW_QuestEN[32585] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", objectives = "" }
WordHunterWoW_QuestEN[32586] = { title = "Maximum Capacitor", description = "The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore.\n\nIf you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons.\n\nOh, also, kill whoever is in charge, will you?", objectives = "" }
WordHunterWoW_QuestEN[32587] = { title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", objectives = "" }
WordHunterWoW_QuestEN[32588] = { title = "On Her Magic-ey Secret Service", description = "Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines.\n\nThey were captured, and are being subjected to who-knows-what kind of awful tortures.\n\nYou must free them and kill whoever captured them. We don't leave anyone behind!", objectives = "" }
WordHunterWoW_QuestEN[32589] = { title = "Life Blood", description = "Scouts unearthed this strange construct hidden within the Lightning Vein Mine. A secret weapon of the Thunder King no doubt.\n\nPerhaps, there is a chance we can use this discovery to our benefit. If we can re-animate it, we can study it. More importantly, we can discover its weakness.\n\nGo to the Throne of Thunder and use this crystal to capture whatever essence animates these constructs.\n\nReturn to me when the task is complete.", objectives = "" }
WordHunterWoW_QuestEN[32590] = { title = "Meet Me Upstairs", description = "There's someone I'd like you to meet. Stormwind's own crown prince recently paid a visit to this humble inn. I've instructed my guards to defend him from any Horde aggression - I don't want to draw any undue attention to myself.\n\nHe and I have been discussing world events, such as the battle along the southern shores, his encounter with Garrosh, and the upcoming assault on the Thunder King.\n\nCome! Let's talk upstairs...", objectives = "" }
WordHunterWoW_QuestEN[32591] = { title = "Secrets of the First Empire", description = "For two thousand years the mogu ruled this entire land. So brutal was their regime that its name is never uttered aloud: Pandaren call it either the \"Old Kingdom\" or \"First Dynasty.\"\n\nThe Thunder King was its founder and first emperor. He amassed enormous power on what is now the Isle of Thunder.\n\nHis time has passed, {name}. We should claim some of his power for ourselves. Gather mogu relics for me from the Throne of Thunder, and amass some trillium - I have a plan!", objectives = "" }
WordHunterWoW_QuestEN[32592] = { title = "I Need a Champion", description = "You are a superb representative of your people, {race}. But I need someone special. I have big plans. And to enact them I will need a champion to carry my flame to the four corners of the world.\n\nAre you the one?\n\nProve it to me on the Isle of Thunder! Lay waste to any mogu, Zandalari, or saurok that you find. Impress me!", objectives = "" }
WordHunterWoW_QuestEN[32593] = { title = "The Thunder Forge", description = "Everything is prepared, {name}, and I have selected you to be my champion.\n\nNext, we must infiltrate the legendary Thunder Forge of Lei Shen himself! You and your faction will need to advance forward until the Thunder Forge is exposed, if it isn't already.\n\nOnce you have infiltrated the forge, meet me there. Be ready for a fight!", objectives = "" }
WordHunterWoW_QuestEN[32594] = { title = "Spirit of the Storm Lord", description = "Our next objective is to temper this weapon with the blood of a demigod, one imbued with the Thunder King's powers.\n\nMy agents tell me that the mogu named Shan Bu is creating just such a creature, intended to guard the Thunder King's citadel.\n\nOnce your faction has fought your way to the front gates, attack Storm Lord Nalak and thrust this lance into his side. The creature will do everything in his power to stop you - stay alive long enough to siphon out the power of the Storm Lord!", objectives = "" }
WordHunterWoW_QuestEN[32595] = { title = "The Crown of Heaven", description = "Do you recall Mason's Folly, the hilltop east of here where you and I met before?\n\nI'm going to use the Lightning Lance to create something special, and I certainly can't do it in here.\n\nMeet me atop Mason's Folly so that we may celebrate our victories together!", objectives = "" }
WordHunterWoW_QuestEN[32596] = { title = "Echoes of the Titans", description = "I'm beginning to see the bigger picture, now, and how the mogu relate to the Titans. But every answer brings with it more questions!\n\nThe only way to put this puzzle together is to find every scrap of Titan information we can scavenge from the Thunder King's palace. Destroy the Thunder King and his minions and collect as many Titan runestones as you can find!", objectives = "" }
WordHunterWoW_QuestEN[32597] = { title = "Heart of the Thunder King", description = "The Thunder King. Dead for twelve thousand years, only to be brought back by Zandalari voice. No doubt Titan power preserved his vile corpse.\n\nTitan power that's mine by right.\n\n{name}! Bring me the heart of the Thunder King. I will have it, and once it is mine, none will ever be able to resurrect him again.\n\nBring it to me, {class}. Bring me his cold, dead heart! ", objectives = "" }
WordHunterWoW_QuestEN[32598] = { title = "A Reckoning", description = "The Thunder King is dead, and his instruments of oppression are being picked over by the Alliance and Horde for their own ends.\n\nWe come now to the climax of the pandaren campaign. Hellscream's machinations have brought the Alliance down on his head - but even more importantly, he's fractured the unity of the Horde. As the Pandaren say: \"The Wok is Hot.\" Something is about to give, and all of our work comes down to this.\n\nI need time to plan. See me as soon as your faction is ready to make its move!", objectives = "" }
WordHunterWoW_QuestEN[32599] = { title = "Securing A Future", description = "It is rumored that the Thunder King's power comes directly from a hidden source within his palace.\n\nEven when he is defeated a new tyrant, Garrosh perhaps, could still use this magic to a terrible end.\n\nThat is unless we make the first move!\n\nTake my staff into the Pinnacle of Storms. Once Lei Shen has been defeated place my staff in the center of his dais.\n\nWe will drain the rest of his power and make sure it stays in our hands.", objectives = "" }
WordHunterWoW_QuestEN[32600] = { title = "The Zandalari Prophecy", description = "Dear {name},\n\nI have read your reports on the Zandalari and believe I have some clues as to their most recent aggression.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[32601] = { title = "Rumbles of Thunder", description = "Dear {name},\n\nThe foreboding sound of thunder has haunted my people for generations. And as you have discovered in your own research, Lei Shen is at the heart of that fear.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[32602] = { title = "Gods and Monsters", description = "Dear {name},\n\nIs it true that the mogu are really connected to the titans? I find this very hard to believe. But looking over your research, some of the truth about the mogu begins to take shape.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[32603] = { title = "Beasts of Fable", description = "Have you ever read the great Pandaren book of fables?  Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.", objectives = "" }
WordHunterWoW_QuestEN[32604] = { title = "Beasts of Fable Book I", description = "The stories of Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?", objectives = "" }
WordHunterWoW_QuestEN[32605] = { title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.", objectives = "" }
WordHunterWoW_QuestEN[32606] = { title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.", objectives = "" }
WordHunterWoW_QuestEN[32607] = { title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", objectives = "" }
WordHunterWoW_QuestEN[32608] = { title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", objectives = "" }
WordHunterWoW_QuestEN[32613] = { title = "Giant Dinosaur Bone", description = "What do you bring Ku'ma?", objectives = "" }
WordHunterWoW_QuestEN[32614] = { title = "More Giant Dinosaur Bones", description = "Give them! Give them to me!", objectives = "" }
WordHunterWoW_QuestEN[32615] = { title = "Many More Giant Dinosaur Bones", description = "Who are you? Why have you returned? Hehehe...", objectives = "" }
WordHunterWoW_QuestEN[32618] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32621] = { title = "Lightning Steel", description = "Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?", objectives = "" }
WordHunterWoW_QuestEN[32627] = { title = "Charged Moganite", description = "We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Sunreaver base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[32628] = { title = "Tactical Mana Bombs", description = "Ah, {name}, just the {race} I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest.\n\nHere, take these. It is time to give the Sunreavers a taste of their own medicine.\n\nPlant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base. ", objectives = "" }
WordHunterWoW_QuestEN[32630] = { title = "Chief Engineer Jard's Journal", description = "What an unusual power source. Wonder how it works? And what it can be used to create?", objectives = "" }
WordHunterWoW_QuestEN[32631] = { title = "High Recognition", description = "", objectives = "" }
WordHunterWoW_QuestEN[32632] = { title = "Made for War", description = "Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction.\n\nA massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.", objectives = "" }
WordHunterWoW_QuestEN[32633] = { title = "Spellbound", description = "Grand Magister Rommath has something in his possession that I want.\n\nHe brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands.\n\nLocate Rommath's book of incantations and bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[32634] = { title = "Breaking Down the Defenses", description = "Even the strongest defense can still have a weakness, {class}. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible.\n\nScouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly.\n\nDisabling them would allow us to keep closer watch on their activities.", objectives = "" }
WordHunterWoW_QuestEN[32635] = { title = "Enough with the Bombs!", description = "The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated.\n\nLook for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.", objectives = "" }
WordHunterWoW_QuestEN[32636] = { title = "Captive Audience", description = "The Sunreavers will stoop to even the lowest levels to get what they want, {name}.\n\nI received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this.\n\nHopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.", objectives = "" }
WordHunterWoW_QuestEN[32637] = { title = "Overpowered", description = "The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain.\n\nI think it would be wise to investigate their camp to see if you can find the source of this extra power.\n\nOnce you find it, use this crystal to overload and destroy it.", objectives = "" }
WordHunterWoW_QuestEN[32638] = { title = "Mana Scavengers", description = "Sometimes, even the smallest creatures can be the biggest threat.\n\nThe Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them.\n\nThey must be dealt with and quickly.", objectives = "" }
WordHunterWoW_QuestEN[32639] = { title = "Deconstruction", description = "Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory.\n\nIf left unchecked they will pose a considerable threat should the Sunreavers mount an attack.\n\nThe only answer is a preemptive strike. We'll destroy them before they can attack us!", objectives = "" }
WordHunterWoW_QuestEN[32640] = { title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", objectives = "" }
WordHunterWoW_QuestEN[32641] = { title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", objectives = "" }
WordHunterWoW_QuestEN[32642] = { title = "Work Order: Dominance Offensive I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Horde I decided to pass this order your way.\n\nThe Dominance Offensive has requested an order of red blossom leeks.\n\nThe troops down there just can't seem to get enough of them!", objectives = "" }
WordHunterWoW_QuestEN[32643] = { title = "Work Order: Dominance Offensive II", description = "Once your red blossom leeks are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your red blossom leeks will be a part of your faction's efforts in Pandaria!", objectives = "" }
WordHunterWoW_QuestEN[32644] = { title = "The Assault on Shaol'mara", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", objectives = "" }
WordHunterWoW_QuestEN[32645] = { title = "Work Order: Operation: Shieldwall I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Alliance I decided to pass this order your way.\n\nOperation: Shieldwall has requested a whole heap of witchberries.\n\nI can't be sure, but I think they have an idea to use them in some sort of weapon.", objectives = "" }
WordHunterWoW_QuestEN[32646] = { title = "Work Order: Operation: Shieldwall II", description = "Once your witchberries are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your witchberries will be a part of your faction's efforts in Pandaria!", objectives = "" }
WordHunterWoW_QuestEN[32647] = { title = "Work Order: Golden Lotus I", description = "<Yoon kept this order request short.>\n\nThe Golden Lotus have requested a large number of white turnips.\n\nTheir request mentioned something about trouble-making sprites wreaking havoc on Mistfall Village. Apparently the sprites don't like turnips!", objectives = "" }
WordHunterWoW_QuestEN[32648] = { title = "Work Order: Golden Lotus II", description = "Well, hopefully these crops will be suitable!\n\nOnce your white turnips are ready to be picked, you'll need only to package them for pick-up.", objectives = "" }
WordHunterWoW_QuestEN[32649] = { title = "Work Order: Shado-Pan I", description = "<Yoon's writing seems rushed. He must have been excited.>\n\nThe Shado-Pan want crops from you! What an honor indeed!\n\nA request came in this morning for green cabbages. Apparently, they make a rather tasty cabbage soup with them.\n\nOnly the finest will do for the Shado-Pan!", objectives = "" }
WordHunterWoW_QuestEN[32650] = { title = "Work Order: Shado-Pan II", description = "Well, your work is done for the day! Now to wait for the harvest tomorrow.\n\nOnce your green cabbages are ready to be picked, you'll need only to package them for pick-up.\n\nOnly the finest cabbage will do for the Shado-Pan!", objectives = "" }
WordHunterWoW_QuestEN[32652] = { title = "To the Skies!", description = "We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari.\n\nSpeak to me when you're ready to learn more.", objectives = "" }
WordHunterWoW_QuestEN[32653] = { title = "Work Order: The August Celestials I", description = "<Yoon's familiar writing scrolls across the tattered paper.>\n\nThe trainees out at the Cradle of Chi-Ji are in need of striped melons. Apparently, they use them in their training exercises.\n\nA representative will be by tomorrow to collect whatever striped melons you can spare.", objectives = "" }
WordHunterWoW_QuestEN[32654] = { title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[32655] = { title = "A Bold Idea", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", objectives = "" }
WordHunterWoW_QuestEN[32656] = { title = "The Fall of Shan Bu", description = "Lei Shen found a clutch of rare storm dragon eggs early in his campaign. One - known as Nalak - was particularly brutal and killed all of its handlers, so he took it for his own.\n\nNow, Shan Bu, one of Lei Shen's most loyal servants, works to resurrect the dragon.\n\nIt is time for us to strike against Shan Bu!\n\nSpeak to me when you are ready to launch the assault!", objectives = "" }
WordHunterWoW_QuestEN[32657] = { title = "Work Order: The August Celestials II", description = "Once your striped melons are ready to be picked, you'll need only to package them for pick-up.\n\nA trainee from the Cradle of Chi-Ji will be along shortly to collect their order.", objectives = "" }
WordHunterWoW_QuestEN[32658] = { title = "Work Order: The Klaxxi I", description = "<Though Yoon's writing leaves something to be desired, it's nice to still have a little piece of him on the farm.>\n\nAn order came in this morning from the Klaxxi. Strangely enough they are requesting mogu pumpkins for some kind of research.\n\nI find it's best not to ask them too many questions...\n\nBest get started on their order. I'd hate to see what a bug of that size could do to your crops if you don't!", objectives = "" }
WordHunterWoW_QuestEN[32659] = { title = "Work Order: The Klaxxi II", description = "Once your mogu pumpkins are ready to be picked, you'll need only to package them for pick-up.\n\nI wouldn't dilly-dally if I were you. The Klaxxi aren't known for their patience!", objectives = "" }
WordHunterWoW_QuestEN[32661] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Aalun at the entrance to the Exodar on Azuremyst Isle.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32662] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32663] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32664] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Jartsam at the Cenarion Enclave in Darnassus.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32665] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Mei Lin north of the Dwarven District in Stormwind.  Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32667] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Softpaws in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32668] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Perascamin at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32669] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32670] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32671] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32672] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32673] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!", objectives = "" }
WordHunterWoW_QuestEN[32676] = { title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", objectives = "" }
WordHunterWoW_QuestEN[32677] = { title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", objectives = "" }
WordHunterWoW_QuestEN[32678] = { title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Sunreavers awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Scout Captain Elsia for further instructions.", objectives = "" }
WordHunterWoW_QuestEN[32679] = { title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Kirin Tor awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Vereesa Windrunner for further instructions.", objectives = "" }
WordHunterWoW_QuestEN[32680] = { title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives Jaina and the Kirin Tor more of a hold on the Isle.\n\nLor'themar awaits us. Speak to me when you are ready to depart. I will escort you there myself.", objectives = "" }
WordHunterWoW_QuestEN[32681] = { title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives the Sunreavers more of a hold on the Isle.\n\nLady Jaina Proudmoore awaits us. We should not make her wait any longer.\n\nSpeak to me when you are ready to depart. I will escort you there myself.", objectives = "" }
WordHunterWoW_QuestEN[32682] = { title = "Inherit the Earth", description = "As you know, {name}, I'm getting along in my years. One can't stay a spry young pandaren forever, you know.\n\nI'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon.\n\nHe's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart.\n\nDo you think he'd be interested?", objectives = "" }
WordHunterWoW_QuestEN[32683] = { title = "So You Want to Be a Blacksmith...", description = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key.", objectives = "" }
WordHunterWoW_QuestEN[32684] = { title = "You Want Fish?", description = "Are you looking for golden carp? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.", objectives = "" }
WordHunterWoW_QuestEN[32685] = { title = "No Fishing Pole Necessary!", description = "You don't even need to equip a fishing pole in Pandaria!\n\nThe waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!", objectives = "" }
WordHunterWoW_QuestEN[32686] = { title = "Pristine Banner of the Mantid Empire", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32687] = { title = "Pristine Ancient Sap Feeder", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32688] = { title = "Pristine Praying Mantid", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32689] = { title = "Pristine Sound Beacon", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32690] = { title = "Pristine Remains of a Paragon", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32691] = { title = "Pristine Mantid Lamp", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32692] = { title = "Pristine Pollen Collector", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32693] = { title = "Pristine Kypari Sap Container", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
WordHunterWoW_QuestEN[32706] = { title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", objectives = "" }
WordHunterWoW_QuestEN[32707] = { title = "Secrets in the Isle of Thunder", description = "I do have one thing I would ask of you, {class}.\n\nWe've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals.\n\nIf you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.", objectives = "" }
WordHunterWoW_QuestEN[32708] = { title = "Setting the Trap", description = "Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies.\n\nYou will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants.\n\nWhen your enemy shows itself, show no mercy. ", objectives = "" }
WordHunterWoW_QuestEN[32709] = { title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", objectives = "" }
WordHunterWoW_QuestEN[32710] = { title = "Something Foul is Afoot", description = "You notice a stronger-than-usual smell permeating from ahead. Your stomach lurches as the thick smell fills your nostrils.\n \nYou recognize this smell, it's saurok. Rotting, discarded saurok flesh infused with the foul waste of the sewer.", objectives = "" }
WordHunterWoW_QuestEN[32711] = { title = "Agony and Anima", description = "You notice the initials A.K. skillfully and with calligraphic precision engraved onto the side of the Animus.\n\nBefore you stands Archritualist Kelada, the shaper of the Animus. By command of the Thunder King, Kelada worked tirelessly to craft the perfect vessel to harness the great power of the anima. Something functional, magnificent, sentient, but most importantly... something deadly.\n\nHe must be stopped before his next imagination is brought to life by the Thunder King.", objectives = "" }
WordHunterWoW_QuestEN[32712] = { title = "Zao'cho the Wicked", description = "Electricity hums in the distance, tickling your ears and sending impulses down your spine. Your fingers go numb, and  your heart races as you approach the door ahead.\n\nZao'cho stands arrogantly atop the steps ahead, weaving lightning between his fingers and smirking at you with demented glee.", objectives = "" }
WordHunterWoW_QuestEN[32713] = { title = "Rocks Fall, People Die", description = "Words fail to describe the massive horror of rock, bone, and blood that rumbles mindlessly and aimlessly ahead of you.\n \nMassive earthquakes crack the seemingly hollow shell of ground beneath the figure, leaving destruction in its wake. It appears that the creature is unaware of your presence.", objectives = "" }
WordHunterWoW_QuestEN[32714] = { title = "Taming the Tempest", description = "You hear a fierce and militant voice roaring in the distance. A crackling storm swells and swirls around a clouded, shadowy figure. Lightning flashes and No'ku Stormsayer appears, his scornful gaze aimed directly at you.", objectives = "" }
WordHunterWoW_QuestEN[32715] = { title = "Requiem for a Queen", description = "A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara, the last Queen of the Mogu.\n\nHer sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara's last moments... her brutal murder by the hand of Lei Shen.\n\nSong turns to sadness and Monara weeps, wailing louder and louder into the darkness.", objectives = "" }
WordHunterWoW_QuestEN[32716] = { title = "Eyes of the Thunder King", description = "As the fog dissipates from the fallen sentries, you feel a sudden rumbling.\n\nThe rocks blocking the sewer tunnels tumble forward and crash into the outflow tanks below, as four putrid eyes lunge from the darkness.", objectives = "" }
WordHunterWoW_QuestEN[32720] = { title = "Choose Your Assignment", description = "", objectives = "" }
WordHunterWoW_QuestEN[32721] = { title = "Choose Your Assignment", description = "", objectives = "" }
WordHunterWoW_QuestEN[32722] = { title = "Forge Ahead!", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", objectives = "" }
WordHunterWoW_QuestEN[32724] = { title = "Forge Ahead!", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", objectives = "" }
WordHunterWoW_QuestEN[32726] = { title = "So You Want to Be a Blacksmith...", description = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key.", objectives = "" }
WordHunterWoW_QuestEN[32728] = { title = "The Court of Bones", description = "The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable {class} to see this task through.\n\nGo to him. Aid in whatever ways that you are able.", objectives = "" }
WordHunterWoW_QuestEN[32729] = { title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to Halduron when you are best able. He will have work for you.", objectives = "" }
WordHunterWoW_QuestEN[32730] = { title = "Ihgaluk Crag", description = "Aethas has taken over at Ihgaluk Crag, to the southeast, continuing his effort to turn the Saurok against the Zandalari and mogu.\n\nGo to him, and help in any way that you can.", objectives = "" }
WordHunterWoW_QuestEN[32731] = { title = "The Court of Bones", description = "The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable {class} to see this task through.\n\nGo to her. Aid in whatever ways that you are able.", objectives = "" }
WordHunterWoW_QuestEN[32732] = { title = "Ihgaluk Crag", description = "Archmage Modera has taken over at Ihgaluk Crag, to the southeast, continuing her efforts to turn the Saurok against the Zandalari and mogu.\n\nGo to her, and help in any way that you can.", objectives = "" }
WordHunterWoW_QuestEN[32733] = { title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Archmage Lan'dalock to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to him when you are best able. He will have work for you.", objectives = "" }
WordHunterWoW_QuestEN[32783] = { title = "Ga'nar's Vengeance", description = "My brother's head is as thick as his axe and he is as stubborn as a gronn.\n\nWhen Ga'nar left he took with him some of the finest warriors in the clan and headed north to the Daggermaw Ravine. If they are still out there, you must find them. Ga'nar will not listen to me.\n\nHelp him see his vengeance through if you must but please bring him back to us.", objectives = "" }
WordHunterWoW_QuestEN[32791] = { title = "Let the Hunt Begin!", description = "I have no time for my brother's whimpering. We hunt for vengeance or death.\n\nThe Thunderlord chieftain slew my father and left me for dead, so I shall take his three sons, the first of which is this runt in my hand.\n\nThis filth has revealed the number and positions of the Thunderlords in the ravine beyond.\n\nJoin us, if you dare, and you will witness how real warriors of the Frostwolf clan fight. Get in my way, and I will end you.", objectives = "" }
WordHunterWoW_QuestEN[32792] = { title = "Leave Nothing Behind!", description = "The Thunderlord clan has become a thorn in my side I will no longer tolerate.\n\nGo east and leave none alive! Burn their supplies! Leave them nothing to cling to.\n\nConverge on the Savage Crag to the east when it is done.", objectives = "" }
WordHunterWoW_QuestEN[32794] = { title = "Wrath of Gronn", description = "The Thunderlord are capturing gronn for the Iron Horde. Show these fools why gronn are NOT pets. \n\nFollow us into Grulloc's Grotto and sunder the chains of the captive gronn. Let the beasts seek to gain their own vengeance against the Thunderlord.\n\nMeet us at Grulloc's Lair beneath the grotto when you are done.", objectives = "" }
WordHunterWoW_QuestEN[32795] = { title = "The Eldest", description = "There is Hatock, last and eldest son of the Iron Wolf. One of the greatest hunters the Thunderlord have ever fielded.\n\nHe was there when his father murdered my father and left me for dead.\n\nWhen I am done with him he will regret not finishing the job.", objectives = "" }
WordHunterWoW_QuestEN[32796] = { title = "To the Garrison", description = "My father is avenged. The sons of the Iron Wolf are all slain.\n\nGo to the garrison your people are constructing in the south. There, herald my return to my laggard brother.\n\nThe time has come for the \"chieftain\" to be reminded of what it means to be a Frostwolf.", objectives = "" }
WordHunterWoW_QuestEN[32804] = { title = "Articles of the Fallen", description = "Even when on a mission of vengeance we must remember to uphold the honor that is required of a member of the Frostwolves.\n\nIn the grotto below are the fallen corpses of many good Frostwolf orcs. They must be remembered.\n\nWhile you carry out Ga'nar's task, look for articles of our fallen brethren. Bring these articles to me so that I might pass them to a shaman for final burial as is our tradition.", objectives = "" }
WordHunterWoW_QuestEN[32805] = { title = "Celestial Blessings", description = "I would like to grant you my full array of draconic power, but sadly, it would tear your mortal frame apart. Still, it's not hopeless - I believe I can create a powerful vessel that you can use.\n\nTo craft it, I will need the blessings of the four August Celestials in Pandaria. Travel with me to the four temples and we will speak to each. To be worthy of their gifts, you must defeat one of their challenges.\n\nThey will not be easy - chose the one challenge best suited to your equipment and skills!", objectives = "" }
WordHunterWoW_QuestEN[32806] = { title = "The King and the Council", description = "I am glad you are here, {name}. I have been using my dream brew to experience events around the world, but the more I learn, the more confused I become.\n\nFor instance, King Wrynn has asked the dwarves of Ironforge for more troops, but they do not all support him.\n\nI will tell you more, but I would also like to hear from your experience firsthand...", objectives = "" }
WordHunterWoW_QuestEN[32807] = { title = "The Warchief and the Darkness", description = "I see now how the Alliance king leads his people. But what is the Horde warchief up to? Just below us, a swarm of goblins are burrowing into the sacred vale on his orders. What does he hope to find there? We must find out!", objectives = "" }
WordHunterWoW_QuestEN[32815] = { title = "The Old Seer", description = "I can help you collect the pieces a story, but it is up to you tie them together. And I may know just where you could do such a thing.\n\nI have heard tales of an elderly scholar named Seer Hao Pham Roo. He is something of an... expert on Pandaria's history, and may be able to shed light on Pandaria's current turmoil.\n\nSeek him out, {name}. Last I heard, he was planning to retrace the emperor's steps by scaling Mount Neverest, in Kun-Lai.", objectives = "" }
WordHunterWoW_QuestEN[32816] = { title = "Path of the Last Emperor", description = "In his time of uncertainty, the last emperor walked a lonely path up this mountain, until he had at last found his answers.\n\nI am here to walk the same path, and it seems you have questions of your own to be answered. Perhaps you will join me, and we can both be satisfied?\n\nOh, but I am getting old, and this blizzard is proving too much for my bones. Could you climb ahead and anchor this rope? I can hoist myself along from there.\n\nTogether we shall walk the path of the last emperor.", objectives = "" }
WordHunterWoW_QuestEN[32861] = { title = "Cloak of Virtue", description = "We have what we need. I can create an item that will harness the power of the celestials and, with a little work, may also be able to contain some of my own.\n\nMeet me atop Mason's Folly, east of the Tavern in the Mists in the Veiled Stair, where we've met before. You will be delighted with the results!", objectives = "" }
WordHunterWoW_QuestEN[32863] = { title = "What We've Been Training For", description = "Are you ready to put your pets to the test? The battle pet arena is no place for low-level rabbits, you'd better have a rocketbot in your pocket and be ready for action. If you've got three fully-experienced pets, find battles against trainers of similar skill and show the world what you've got. You can find the instructions in your Pet Journal.", objectives = "" }
WordHunterWoW_QuestEN[32868] = { title = "Beasts of Fable Book II", description = "The stories of Lucky Yi, Greyhoof, and Skitterer Xi'a will exist in this land, always. Do you wish to meet them in battle once more?", objectives = "" }
WordHunterWoW_QuestEN[32869] = { title = "Beasts of Fable Book III", description = "The stories of No-No, Ti'un the Wanderer, and Gorespine will exist in this land, always. Do you wish to meet them in battle once more?", objectives = "" }
WordHunterWoW_QuestEN[32870] = { title = "Preparing to Strike", description = "Events are in motion, {name}. We have one final task to complete before we are ready to move into the final act of my plan.\n\nMy agents tell me that King Wrynn has reassembled a naval fleet after his losses at Theramore, and Vol'jin is marching north across Durotar in open rebellion against the warchief.\n\nSpeak with me again as soon as they are ready to converge on the gates. We will bring this war to a glorious conclusion!", objectives = "" }
WordHunterWoW_QuestEN[32900] = { title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", objectives = "" }
WordHunterWoW_QuestEN[32901] = { title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", objectives = "" }
WordHunterWoW_QuestEN[32929] = { title = "They Rely on Numbers", description = "Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers.\n\nSo... to win, we must cull their numbers.\n\nAs we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.", objectives = "" }
WordHunterWoW_QuestEN[32942] = { title = "Work Order: Sunreaver Onslaught I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Horde. The Sunreaver Onslaught, located out on the Isle of Thunder, has requested a bushel of scallions.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "" }
WordHunterWoW_QuestEN[32943] = { title = "Work Order: Sunreaver Onslaught II", description = "Once your scallions are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your scallions will feed so many hungry soldiers on the front lines!", objectives = "" }
WordHunterWoW_QuestEN[32944] = { title = "Work Order: Kirin Tor Offensive I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Alliance. The Kirin Tor Offensive, located out on the Isle of Thunder, has requested a bushel of juicycrunch carrots.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "" }
WordHunterWoW_QuestEN[32945] = { title = "Work Order: Kirin Tor Offensive II", description = "Once your juicycrunch carrots are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your juicycrunch carrots will feed so many hungry soldiers on the front lines!", objectives = "" }
WordHunterWoW_QuestEN[32952] = { title = "TEST", description = "I need help! Dragons made off with my sheep! Can you kill 10 of them?", objectives = "" }
WordHunterWoW_QuestEN[32974] = { title = "Rolo's Riddle", description = "<The leather vellum is very old. Stained by age, it bears the following letters:>\n\nOn the isle of time are tall men four\nRound and strong and nothing more\nOf these brothers the shortest be\nWhere the trail leads to me.", objectives = "" }
WordHunterWoW_QuestEN[32975] = { title = "Rolo's Riddle", description = "<Another dirty scrap of parchment is buried beneath the soil.>\n\nSomewhere hope stands, wings held forth\nFrom its feet turn to the north\nPass beyond an ancient gate\nBehind a stone pair, I await.", objectives = "" }
WordHunterWoW_QuestEN[32976] = { title = "Rolo's Riddle", description = "The final step, my treasure calls\nAbove the place where water falls\nBeneath the shade on vantage high\nNo path to walk but air and sky.", objectives = "" }
WordHunterWoW_QuestEN[32979] = { title = "Garrison Campaign: Farseer's Rock", description = "Draka and Drek'Thar are travelling to Farseer's Rock. It is a sacred place, not a safe one. But Draka insists that Drek'Thar must rebuild his connection to the elements.\n\nI can feel the spirits of this land are becoming restless. Something is about to happen, and I suspect these two will need all the help they can get.\n\nPlease, {name}, go to them and lend what aid you can. I care for these two a great deal.", objectives = "" }
WordHunterWoW_QuestEN[32980] = { title = "Eaters of the Elements", description = "Drek'Thar has already begun his ritual, and it is powerful enough to draw the attention of the local goren. Those beasts are drawn to elemental magic like flies to a corpse.\n\nI will have my hands full soon enough. Help us if you like but Drek'Thar must be allowed to finish his ritual.", objectives = "" }
WordHunterWoW_QuestEN[32981] = { title = "Only the Winner", description = "I am Gronnstalker Rokash, and I only serve the winning side.\n\nI have heard of some of your deeds, commander, and seen the corpses left in the wake of you and your forces.\n\nI have grown tired of my current clan. They are soft, weak, and losing.\n\nI offer you this challenge: enter Colossal's Fall to the north and slay Sky-Singer Strag. Claim her totem as a trophy and I will hail you as my new chieftain.", objectives = "" }
WordHunterWoW_QuestEN[32983] = { title = "In the Shadow of Giants", description = "The goren and the magnaron are ravaging the element spirits and smelting their essence as one would smelt steel.\n\nCommander, take my totem, travel east to Magnarok. Please, find them, and free them.\n\nDraka and I will make our way to the Ascent of Frostfire. Meet us there if you are successful.", objectives = "" }
WordHunterWoW_QuestEN[32984] = { title = "The Ascent", description = "I can feel the voice of the Fury at the top of the ascent. Come, let us climb these stairs together.\n\nBe on your guard. The goren of this area are likely to be drawn by the smell of a shaman.\n\nIf we get separated, fall back to the base of the stairs and regroup.", objectives = "" }
WordHunterWoW_QuestEN[32985] = { title = "Fury of Frostfire", description = "The moment I begin the ritual to free Exurotus you can expect Kron to be drawn to us. \n\nIt would normally take an army of seasoned warriors to defeat a magnaron. We have only the three of us.\n\nLook for my fire totem upon the battlefield. I will try to gain what boons I can from Exurotus. Step near the totems and become one with the Fury.\n\nWith these boons, slay Kron! Lok'tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[32989] = { title = "Securing the South", description = "We have an outpost to the southeast that was boxed in by Thunderlord forces as they marched through the canyons to Wor'gol.\n\nI have sent reinforcements to secure the outpost and press east to Grom'gar. We will push the Thunderlords out of our lands completely, and pursue them all the way back to that reeking corpse they call home.\n\nDraka's sister, Lokra, was among the orcs who volunteered to clean up Stonefang Outpost.", objectives = "" }
WordHunterWoW_QuestEN[32990] = { title = "They Who Held Fast", description = "The siege has been broken - they underestimated the resilience of Stonefang, and our reinforcement wave from Bladespire caught them completely off-guard.\n\nOnce we finish cleaning up here, we rally anyone who can still fight and prepare to march for Grom'gar.\n\nThe outpost captain, Karg Bloodfury, should have come out to meet us by now. Can you get him out here?\n\nTell him Lokra is waiting. He knows how much I hate to be kept waiting.", objectives = "" }
WordHunterWoW_QuestEN[32991] = { title = "Into the Boneslag", description = "The Thunderlords took prisoners into the Boneslag?\n\nWell what are we waiting for?! We have to go after them!\n\nYou look for the missing villagers - Asha and I will track Karg.", objectives = "" }
WordHunterWoW_QuestEN[32992] = { title = "Moving Target", description = "Karg's captors are moving east - probably retreating to Grom'gar with their tails between their legs!\n\nThey think they outrun me, but Asha here is the fastest thing on four legs. We'll run them down in the Icewind Drifts.", objectives = "" }
WordHunterWoW_QuestEN[32993] = { title = "The Strength of Our Bonds", description = "Asha has passed, but we share a bond that cannot be severed by death. Even now, her spirit urges me onward to Grom'gar.\n\nThe Iron Wolf claims our attachments make us weak... that love makes us vulnerable.\n\nHe is wrong.\n\nKarg is my strength, and I his. I will free him from his chains, and together we will show the Thunderlord clan the strength of our bonds.", objectives = "" }
WordHunterWoW_QuestEN[32994] = { title = "Enfilade", description = "If we leave now, my clan's final assault on Grom'gar will be a disaster.\n\nThough our warriors are unmatched in melee, the Thunderlords have new ranged weapons - our forces would be decimated as they cross the Icewind Drifts.\n\nBut WE are already here. We can overtake those weapons before they ever fire.\n\nBlackrock orcs help our enemies forge these \"cannons\" in the workshops on the south side. If we use their own tools to sabotage the weapons, we leave Grom'gar wide open to a Frostwolf raid.", objectives = "" }
WordHunterWoW_QuestEN[33008] = { title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons.\n\nShe should be able to settle you in.", objectives = "" }
WordHunterWoW_QuestEN[33010] = { title = "The Iron Wolf", description = "My brother Ga'nar stands beside me.\n\nWor'gol, Stonefang, and your garrison hold strong.\n\nOur clan is united, and the Thunderlord are already on the run. We are ready. The time has come to face this \"Iron Wolf.\"", objectives = "" }
WordHunterWoW_QuestEN[33013] = { title = "Of Fire and Thunder", description = "The Iron Wolf... brought weapons...\n\n<cough>\n\n...weapons of fire and thunder.\n\nOur warriors have never seen such weapons. We were not ready.\n\n<wheeze> We must learn... to overcome...", objectives = "" }
WordHunterWoW_QuestEN[33018] = { title = "Noodle Secrets Long Forgotten", description = "Searching amidst the rubble, you find the fragment of an old sign. Wiping away the dust, you can make out the well-weathered pandaren characters for \"Noodles\" and \"Lin.\"\n\nLooking above, you suspect that the establishment this sign belonged to was situated on the bridge, which now lies in rubble about you. An eatery placed on a bridge sounds very temporary, so its owner would likely live nearby.\n\nPerhaps there is a clue to be found in the village here on the island?", objectives = "" }
WordHunterWoW_QuestEN[33019] = { title = "NC S1 Q2", description = "Well hello there. I am Lin, Chao-Wei. Have you come here to try my family's famous noodle soup? I'm afraid you're all out of luck. My father passed away before he could teach me the secret ingredient to his secret ingredient noodle soup. He did mention writing down the recipe for a friend of his that went to the Temple of the Jade Serpent. Perhaps you can find it there?", objectives = "" }
WordHunterWoW_QuestEN[33020] = { title = "The Lost Secret of the Secret Ingredient", description = "If you've come here to try my family's famous noodle soup, I'm afraid you're out of luck.\n\nMy father passed away before he could teach me the secret ingredient. He did mention writing down the recipe for a friend of his that studied at the Temple of the Jade Serpent.\n\nPerhaps you can find it there?", objectives = "" }
WordHunterWoW_QuestEN[33021] = { title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", objectives = "" }
WordHunterWoW_QuestEN[33022] = { title = "Catch and Carry", description = "Oh my! Grandpa used to tell me stories of the famous Lin family noodle shop.\n\nIt is sad that the scroll has been warped, but I think we can work together to solve the riddle!\n\nTo start, we're going to need lots of grain to make noodles.\n\nHead down to the granary and catch some grain with this sack. After you've caught some, drop it off at the wagon I've placed at the granary.", objectives = "" }
WordHunterWoW_QuestEN[33023] = { title = "NC S1 Q6", description = "", objectives = "" }
WordHunterWoW_QuestEN[33024] = { title = "Is That A Real Measurement?", description = "Well done, {name}. I can see you're ready to continue exploring the mysteries of Lin's secret ingredient soup.\n\nFrom what I can tell, Lin used Stormstout brew for his soup broth.\n\nI think the next steps for you are to create a Noodle Cart of your own and to head to the Stormstout Brewery to collect some sloshes of brew.", objectives = "" }
WordHunterWoW_QuestEN[33025] = { title = "NC S2 Q2", description = "", objectives = "" }
WordHunterWoW_QuestEN[33026] = { title = "These Aren't Your Fatty Goatsteaks", description = "I'm so excited, {name}. We've nearly mastered all the ingredients for noodle soup!\n\nWe have plenty of vegetables and spices here, but the Lin family had access to exotic meats not seen in Pandaria for some time. We need some nice, fatty meats.\n\nGrandpa used to tell me of ancient turtles living off the shores of the Timeless Isle. Something that lives that long has to have some nice fatty meat on its bones.\n\nCreate a deluxe noodle cart and gather some fatty turtle steaks and we'll continue.", objectives = "" }
WordHunterWoW_QuestEN[33027] = { title = "The Secret Ingredient Is...", description = "The best way to go about doing this is through hands-on experience.\n\nI've arranged for merchants, scholars, and farmers from all over Pandaria to come for a taste test of your soups. We'll get the best results if you can match them to the soups they prefer.\n\nIt's time to find the secret ingredient!", objectives = "" }
WordHunterWoW_QuestEN[33059] = { title = "The Fate of Karabor", description = "Threads of the future weave together, winding and unwinding, creating tapestries that change in form and color from one moment to the next.\n\nI must have clarity. I must focus on the ONE strand that will become reality.\n\nWhen you are ready to share in my vision, drink the elixir.\n\nWhen the vision begins, be on your guard. The events of the vision are as deadly as anything we experience in this reality.", objectives = "" }
WordHunterWoW_QuestEN[33062] = { title = "Catching His Eye", description = "For what must be done, I need someone I can trust. You're one of those few.\n\nThe woods and the orc village, Gul'var, are protected from my scrying magic. We need to pierce that veil. I think I know a way.\n\nThere's a fel presence within the woods. A demonic watcher is there, hidden in a cave from which it casts its all-seeing gaze.\n\nI would like for you and the warden to capture it.", objectives = "" }
WordHunterWoW_QuestEN[33066] = { title = "Soul Shards of Summoning", description = "It's good to know what Teron'gor and Cho'gall are up to. It's more important that we stop Gul'dan.\n\nSome of his disciples can summon minor demons. To do this, these lesser warlocks must use a soul shard. The foul crystal creates a connection to the Twisting Nether, pulling a demon through against its will.\n\nGul'dan's as much demon as he is orc. If we can gather some of the more potent shards, we can combine them into something that just might capture him.", objectives = "" }
WordHunterWoW_QuestEN[33070] = { title = "Think of the Children!", description = "When the Shadowmoon attacked Arbor Glen, everything was thrown into chaos.\n\nMany of us escaped, but there are still three children missing.\n\nI believe they are still back in the village.\n\nPlease save them!", objectives = "" }
WordHunterWoW_QuestEN[33072] = { title = "Into Twilight", description = "The safety of my people is of the utmost priority.\n\nIt is likely that Ner'zhul has taken the prisoners to Shaz'gul, his stronghold to the southwest.\n\nI do not wish to use aggression against him, but he may force my hand.\n\nMeet me at Twilight Glade, {name}. Then, we shall try our best to recover the prisoners.", objectives = "" }
WordHunterWoW_QuestEN[33075] = { title = "A Hero's Welcome", description = "Prophet Velen has asked me to show you around Shadowmoon Valley.\n\nWe will go first to Embaari Village, where my sister Samaara is waiting for us. I have not seen her since the Iron Horde took me to Tanaan.\n\nThe village is just one of many trading villages between the Temple of Karabor and Shattrath.\n\nFollow the road east and make your way to Embaari Village. I will accompany you, my friend.", objectives = "" }
WordHunterWoW_QuestEN[33076] = { title = "The Clarity Elixir", description = "I see a thousand glimpses of the future, swimming in a chaotic blur.\n\nIt is possible to focus my energies to see the true eventuality - the future most likely to come to pass.\n\nI will need an oracle stone to focus my power, and a special elixir to still my mind.\n\nTo make the elixir, I will need the following ingredients: wing dust from Swamplighters along the river, fresh hearts from a monstrously-sized hydra, and a rare star lily.\n\nMeet me at Moonwillow Peak when this task is done.", objectives = "" }
WordHunterWoW_QuestEN[33077] = { title = "A Grandmother's Remedy", description = "Oh my, such a vigorous young lad! Such a spring in your step, and such a sparkle in your eye!\n\nWhen you get to my age, it's all aches and pains.\n\nLuckily, I have a recipe for an unguent that would soothe my joints. I just need the ooze from the skin of belly toads in the swamp.\n\nWould you be a dear and help an old woman out?", objectives = "" }
WordHunterWoW_QuestEN[33078] = { title = "The Dark that Blinds Us", description = "After years of research, there is still so much I do not understand about the Shadowmoon.\n\nTo the southwest are stone monuments detailing the orcs' history.\n\nI'm not able to get close enough to examine the stones, but perhaps you can.\n\nIf you could take a chalk rubbing of the words written on those stones, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[33080] = { title = "Going Undercover", description = "Yrel leads my rangers on a search for the prisoners at the Shadowmoon village.\n\nTheir work is extremely dangerous, so I need you to carry out a contingency mission.\n\nSylene has mastered an illusion spell which will allow you to infiltrate Shaz'gul safely. Speak to her to disguise yourself.\n\nThen, plant explosives at the quartermaster's depot, the main lodge, and the ritual altar.\n\nIn case anything goes wrong, set them off to create a distraction.", objectives = "" }
WordHunterWoW_QuestEN[33081] = { title = "Escape From Shaz'gul", description = "I've failed, {name}...\n\nMy squadron was caught by a wandering patrol. We fought fiercely, but the alarm had been raised. The rangari forced me into hiding before surrendering themselves to the enemy.\n\nThey were under MY command, and they gave their lives... for what? I... I'm not sure what to do, {name}.\n\nWe need to get out of here, but how?", objectives = "" }
WordHunterWoW_QuestEN[33082] = { title = "Ancestor's Memory", description = "I believe that you should know the price of the lives you take.\n\nSo before I will help you find Ner'zhul, you must understand why he joined the Iron Horde.\n\nIn a cave beneath this village is an artifact that we call the Ancestral Totem. On it is carved the names of every Shadowmoon clan member since its founding.\n\nThe opening of the cave lies directly south. I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[33083] = { title = "On the Offensive", description = "We cannot enter these gates, but you can, {class}.\n\nYour mission is critical, and the Shadowmoon will kill you on sight. Do not hesitate to return the favor.", objectives = "" }
WordHunterWoW_QuestEN[33084] = { title = "The Big Haul", description = "Ey commander, fancy runnin' inta ya out here!\n\nTha garrison's got plenty a hungry mouths ta feed, with more folks comin' by every day.\n\nWe're really gonna need a big haul o' meat ta keep everyone happy.\n\nWouldya care ta lend us a hand? It'll be faster work with an extra pair a hands.", objectives = "" }
WordHunterWoW_QuestEN[33087] = { title = "Meet Me Back at the Inn", description = "I'm certain you're eager to test out your new cloak. Let's put it to use.\n\nMeet me back inside the inn! A new development has come to my attention that we'll want to take advantage of.", objectives = "" }
WordHunterWoW_QuestEN[33088] = { title = "A Timeless Discovery", description = "Pandaria. Just when I think I've gotten its mysteries figured out, I discover something new.\n\nIt's called \"The Timeless Isle.\" Once hidden in the mists, it appears and disappears seemingly of its own will. I've heard that time has no meaning there, that the sun neither rises nor sets.\n\nWe can take advantage of this anomaly, {name}! If I could time-lock your cloak, the power it could contain would be... immense.\n\nOur path is clear. Fly southeast of the Jade Forest and meet me at the Timeless Isle!", objectives = "" }
WordHunterWoW_QuestEN[33098] = { title = "Secrets of the Timeless Isle", description = "There is a currency minted only on this island - \"timeless coins.\" They are immune to the island's temporal distortions... I would like to figure out why.\n\nGather some for me! Venture into the jungles of this forgotten paradise. Destroy the mysterious foes who lurk in this timeless place, discover hidden caches of treasure, and explore forgotten treasure hoards - whatever it takes. I will be waiting!", objectives = "" }
WordHunterWoW_QuestEN[33100] = { title = "The Emperor's Way", description = "Recently, the August Celestials of Pandaria presented you with a challenge - and you triumphed.\n\nBut can you defeat them in combat? They are testing the mettle of all of Pandaria's heroes.\n\nThis challenge is not impossible, but you'll need to follow the advice of the last Pandaren Emperor and tackle it with unwavering inner strength. You'll also need a small army, so find a group of people you trust.\n\nDefeat the four celestials here in the Celestial Court, and our journey is almost complete...", objectives = "" }
WordHunterWoW_QuestEN[33104] = { title = "A Pandaren Legend", description = "I have learned so much in this timeless place, friend. Between the wisdom of the celestials and the curious power of these timeless artifacts, I know now how to safely augment your cloak with my own considerable power.\n\nI need a sacred place to complete my final incantations. Quickly! Meet me in the Vale of Eternal Blossoms, within the Seat of Knowledge above the Mogu'shan Palace.\n\nToday, your legend begins!", objectives = "" }
WordHunterWoW_QuestEN[33105] = { title = "Judgment of the Black Prince", description = "Now. To the final stage of my plan. Time to fulfil your grand purpose.\n\nUsing your newfound powers, it is time to bring this war to its conclusion. Destroy Garrosh Hellscream. Your people demand it, and future generations will sing your praises as the harbinger for the glorious new world we shall build together.\n\nI have no reward to offer you. I have already done everything in my power to ensure that you succeed. You are on your own.\n\nEnd Hellscream's reign.", objectives = "" }
WordHunterWoW_QuestEN[33107] = { title = "Bad Feeling, Worse Result", description = "<As you open the scroll, you realize your worst fears have come true: the sha energies have corrupted the Lin recipe.>\n\n<Your only choice is to defeat the released energies in the hope that the scroll can be saved.>", objectives = "" }
WordHunterWoW_QuestEN[33111] = { title = "Bounty: Twisted Ancient", description = "The ancients of the Cursed Woods have been corrupted by demonic magic. Since they need to be destroyed, we might as well make use of their resources. Waste not, want not.\n\nBeware: these woodland behemoths are no easy targets. Gather trusted friends before you engage these twisted ancients.\n\n-- Baros Alexston", objectives = "" }
WordHunterWoW_QuestEN[33112] = { title = "Ominous Portents", description = "Now that Priestess Moonfang has created the blessed water, it is time to deal with the demon.\n\nTake the water and the scripture of Elune.\n\nThrough the power of each, you will compel the demon to show us what the orcs are up to at Gul'var.", objectives = "" }
WordHunterWoW_QuestEN[33113] = { title = "Shadowmoonwell", description = "The archmage has asked me to prepare this moonwell. Once it is completed, I'll be able to sanctify its water for use against the demon.\n\nOnly one thing remains.\n\nA piece of one of Draenor's moons has fallen into a nearby pool on the far side of the woods. Such a thing is perfect for use in the dedication of the moonwell to Elune.\n\nWill you bring it back for me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[33114] = { title = "Forging the Soul Trap", description = "The fiery heart of Krosnis is in the forge. We have the soul shards.\n\nNow all that is left to do is to stoke the fires and combine all of these foul components into a trap for Gul'dan.", objectives = "" }
WordHunterWoW_QuestEN[33115] = { title = "Shrouding Stones", description = "Long ago, the shaman of the Shadowmoon clan erected three stones in the woods. There, they performed their sacred rituals, blessing the beasts and the trees.\n\nNow, someone has placed a fel magic upon those stones. This corruption is what shrouds the village of Gul'var.\n\nBefore we can use the captured demon to safely peer into the Shadow Council's village, we must bring down those stones.", objectives = "" }
WordHunterWoW_QuestEN[33116] = { title = "To Catch a Shadow", description = "Gul'dan is on the Shadow Rise just up the hill to the west. But, you must hurry, {name}. We know that he's about to leave for Talador and Frostfire Ridge.\n\nThe use of the soul trap is straightforward. Simply point and shoot to ensnare Gul'dan. The crystal will take care of the rest.\n\nI'll see you back at Starfall Outpost when you have him.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[33119] = { title = "Slavery and Strife", description = "We have their citadel, but they still have some of my people enslaved at the Sootstained Mines.\n\nWe have no one to spare, but you seem more than capable of handling a few ogres on your own.\n\nI ask that you release any enslaved Frostwolves you find there, and keep an eye out for Mulverick.", objectives = "" }
WordHunterWoW_QuestEN[33120] = { title = "A Curse Upon the Woods", description = "Cordana tells me that the creatures of the woods are cursed by the same fel energies keeping Khadgar from scrying into the orc village.\n\nThis will not do.\n\nIf we were on Azeroth, I could find a cure in a reasonable timeframe. However, we are not, nor do we have the luxury of time.\n\nBetter to put a swift end to their suffering rather than allow these poor creatures to linger with demonic energy.", objectives = "" }
WordHunterWoW_QuestEN[33125] = { title = "A Proper Parting", description = "The ogres outnumbered us, *cough* but we made them pay for their deeds in blood.\n\nEven so, I was forced to abandon my fallen brothers and sisters on the battlefield. They deserve better than to have their corpses despoiled by the ogre filth.\n\nHere, take this torch *cough* and do what I could not: burn the corpses of my fallen brothers and sisters to the west.", objectives = "" }
WordHunterWoW_QuestEN[33132] = { title = "Gut Guttra", description = "Snowpaw was able to help me to here so that I might strike against their leader, Guttra, but I have lost too much blood. My time is near.\n\nDo you have the strength to help me avenge my fallen brothers and sisters and kill Guttra Wolfchew?\n\nThe monster resides in the tallest tower of Grimfrost.", objectives = "" }
WordHunterWoW_QuestEN[33135] = { title = "Cleaning Up Gul'var", description = "Just because we need to focus on Gul'dan doesn't mean we're not going to take down the Shadow Council in the process.\n\nThis village is filthy with Shadow Council villains. Let's do something about them.", objectives = "" }
WordHunterWoW_QuestEN[33136] = { title = "The Rainy Day is Here", description = "", objectives = "" }
WordHunterWoW_QuestEN[33137] = { title = "The Celestial Tournament", description = "The Timeless Isle is home to a special tournament created to test the leadership of its participants.  Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the celestials themselves.\n\nEach time you win the tournament, I will honor you with a single ceremonial coin.  When you have enough coins, speak with me again to further discuss your reward.", objectives = "" }
WordHunterWoW_QuestEN[33138] = { title = "Why Do We Fight?", description = "Oh my friend, today you and your companions have put an end to the sha that has plagued Pandaria since before time was recorded. You have accomplished that which even the titans and their mogu servants could not: destroying the last breaths of Y'Shaarj.\n\nCome, will you join me in the Vale of Eternal Blossoms? There is something I would like you to bear witness to.", objectives = "" }
WordHunterWoW_QuestEN[33139] = { title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", objectives = "" }
WordHunterWoW_QuestEN[33146] = { title = "Noodle Time", description = "Hello, {name}. Care to work the noodle stand again?\n\nJust let me know when you're ready to work another shift and I'll get everything set up.", objectives = "" }
WordHunterWoW_QuestEN[33147] = { title = "The Last Gasp of Y'Shaarj", description = "A dark, vaporous substance stains the floor of the room. This is all that remains of the Old God Y'Shaarj.", objectives = "" }
WordHunterWoW_QuestEN[33156] = { title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway down this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", objectives = "" }
WordHunterWoW_QuestEN[33160] = { title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway up this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", objectives = "" }
WordHunterWoW_QuestEN[33161] = { title = "A Timeless Tour", description = "You should first familiarize yourself with the island.\n\nExplore. Investigate anything that catches your interest. Return when you're done, and I'll reward you for whatever information you've gathered about this strange place.\n\nAnd do be careful! Monstrous beasts and supernatural creatures abound.", objectives = "" }
WordHunterWoW_QuestEN[33168] = { title = "Heart On Fire", description = "We have the shards, but now they must be combined. There's a forge here, but even its fires aren't hot enough for our purposes.\n\nHowever, there is a demon nearby that burns hot as the sun.\n\nGul'dan, or perhaps Razuun, has managed to summon an infernal. The thing calls itself Krosnis, which means \"furnace.\"\n\nThe demon's heart burns hotly enough. All you need do is collect it.", objectives = "" }
WordHunterWoW_QuestEN[33211] = { title = "A Timeless Question", description = "Destiny. Fate. Karma. Words like these imply that the timeways are unassailable.\n\nWould that were the case. To this day, many of Azeroth's inhabitants yearn to change the past. Yet just as our experiences shape us, they also shape the world around us.\n\nConsider how those threads have woven the fabric of today's reality. Cut enough threads, and causation inevitably fails, unraveling that fabric. Indeed, cutting even a single thread short can result in disaster, provided it is the right thread.", objectives = "" }
WordHunterWoW_QuestEN[33222] = { title = "Little Tommy Newcomer", description = "I've got a battle pet, too! Want to battle? It'll be fun, I promise!", objectives = "" }
WordHunterWoW_QuestEN[33228] = { title = "Time In Your Hands", description = "Inhabitants of this strange island barter with a special currency, immune from the fickle fluctuations of time.\n\nYou would do well to gather as many of these \"timeless coins\" as possible! They can be found hidden away in small caches, or gathered from creatures all around the island. Larger, rarer creatures are a better source of coins - you may find it profitable to venture forth as part of a group.\n\nIntroduce yourself to Mistweavers Ai and Ku across the Celestial Court, and gather some coins for me.", objectives = "" }
WordHunterWoW_QuestEN[33229] = { title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", objectives = "" }
WordHunterWoW_QuestEN[33230] = { title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", objectives = "" }
WordHunterWoW_QuestEN[33231] = { title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Lara. She will guide you to our chief investigator.", objectives = "" }
WordHunterWoW_QuestEN[33232] = { title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Alundra. She will guide you to our chief investigator.", objectives = "" }
WordHunterWoW_QuestEN[33233] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33248] = { title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Taijing.\n\n<Taijing sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", objectives = "" }
WordHunterWoW_QuestEN[33249] = { title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Jinho.\n\n<Jinho sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", objectives = "" }
WordHunterWoW_QuestEN[33252] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[33255] = { title = "The Righteous March", description = "The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city.\n\nExarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders.\n\nCome and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!", objectives = "" }
WordHunterWoW_QuestEN[33256] = { title = "The Defense of Karabor", description = "Defend Karabor from the Iron Horde.\n\nAt the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting.\n\nOnce we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.", objectives = "" }
WordHunterWoW_QuestEN[33263] = { title = "Gloomshade Grove", description = "<This looks like one of the pack mules from your garrison. It's strange that it's wandering out here alone.\n\nYou probably should investigate.>", objectives = "" }
WordHunterWoW_QuestEN[33269] = { title = "Cleaning Up Gul'var", description = "Khadgar wants you to concentrate on Gul'dan, but that doesn't mean we're not going to take down the Shadow Council in the process.\n\nGul'var's filthy with Shadow Council villains. Let's do something about them.", objectives = "" }
WordHunterWoW_QuestEN[33271] = { title = "Game of Thorns", description = "<Jarrod is clearly injured. He winces in pain as he begins to talk.>\n\nMy lead forest operator, Shelly... she is being held not far from here...", objectives = "" }
WordHunterWoW_QuestEN[33331] = { title = "Captured Critters", description = "This poor critter is about to be podling food. It would be pretty easy to set this little guy free.", objectives = "" }
WordHunterWoW_QuestEN[33332] = { title = "Hints From The Past", description = "There is much to learn of this place, yet it does not yield its secrets willingly.\n\nSomething you mentioned the last time that we spoke intrigues me. This Mistweaver Ai, she carries a time-worn journal, if I recall? This may be the answer to many of our questions, or it may simply raise more. I suppose that it all depends on the diligence of the explorer that put pen to paper in this preposterous place.\n\nObtain a time-worn journal and return to me with it. We shall delve into its mysteries together.", objectives = "" }
WordHunterWoW_QuestEN[33333] = { title = "Timeless Treasures", description = "The journal indicates that treasures abound across the island, sometimes temptingly out of reach, and other times hidden in dark caves and hollows. What might have been secreted away here, many generations ago?\n\nAnd perhaps more importantly, by whom?\n\nSearch the island for such treasures, and return to me with your findings. Be warned that all that glitters is not gold, yet the reverse is also true. Sometimes the simple hollowed-out stump is the best hiding place for one's valuables.", objectives = "" }
WordHunterWoW_QuestEN[33334] = { title = "Strong Enough To Survive", description = "An island lost in time and yet it returns flourishing with life!\n\nWhere did this island travel to? Did it simply hop forward in time, or did it languish in the dark reaches of the Twisting Nether?\n\nThere is one thing for certain: the creatures that inhabit this place are far more than they seem. I sense a hidden power in them, forged by the eons. Seek out the champions of their species, duly marked by their power and prowess, and vanquish five such creatures.\n\nIn death, we may find the clues we seek.", objectives = "" }
WordHunterWoW_QuestEN[33335] = { title = "The Last Emperor", description = "From what I have gathered, this place used to be a tournament ground of sorts, where warriors from throughout Pandaria would show their prowess by following in the footsteps of their last emperor, Shaohao.\n\nI have heard that when Shaohao completed his trials, he became one with the land, and enveloped Pandaria in a thick mist, obscuring it from even our abilities to penetrate the passages of time.\n\nThat sounds quite interesting, perhaps you should speak with him?", objectives = "" }
WordHunterWoW_QuestEN[33336] = { title = "The Essence of Time", description = "It is about time that I revealed to you my purpose on this island.\n\nThe bronze dragonflight's powers have diminished greatly - we can now only catch furtive glimpses through time. It is... quite frustrating.\n\nBut we are not entirely without means. I hold in my hand the Vision of Time, an artifact of my own creation. The creatures of this isle have passed through time, and may carry with them some of its essence. With it, we will fill the hourglass, granting us a window into the timeways once more.", objectives = "" }
WordHunterWoW_QuestEN[33337] = { title = "A Vision in Time", description = "Look at how the Vision reacts! Astounding! Even now it shows shadows of timeways that flit around us constantly. Though not true sands of the Hourglass of Time, the finely-ground epoch stones certainly have a power all their own. Our first task is to use them to calibrate the Vision of Time.\n\nTake the Vision of Time to a location where history is in the making: the Siege of Orgrimmar. Once there, turn the hourglass and see what happens.", objectives = "" }
WordHunterWoW_QuestEN[33338] = { title = "Empowering the Hourglass", description = "The hourglass gives us glimpses into the streams of time we once walked as easily as a well-worn path.\n\nGather additional epoch stones, so that we may continue to use the power of the hourglass to delve into the mysteries of the timeways.\n\nThe future depends on it.", objectives = "" }
WordHunterWoW_QuestEN[33340] = { title = "Timeless Nutriment", description = "As you have surmised, the flora and fauna of this island are quite unusual. Not all explanations are mysterious, however. Sometimes, we must listen to the land, to hear the tales of the world around us. Have you considered that the creatures of this island grew to such proportions simply from the nutriment of the land you walk upon?\n\nYou will find nutriment in abundance throughout the island: ripe fruits, eggs, meat, flowers, nuts, and even the stones themselves. Eat, and discover the power of the land.", objectives = "" }
WordHunterWoW_QuestEN[33341] = { title = "Wayshrines Of The Celestials", description = "Many years ago, these grounds were a place where my people would come in pilgrimage. Here, they would listen to the words of the celestials, and meditate for many days. In their meditations, they found the fear, anger, despair, doubt, and violence that plagued their spirits.\n\nBefore them would be a pathway to enlightenment. For each, the pathway would be different. For all of them, the pathway began with wisdom.\n\nTravel the island, as they did, and discover one of the lost wayshrines of the celestials.", objectives = "" }
WordHunterWoW_QuestEN[33342] = { title = "Drive Back The Flame", description = "The pandaren once existed in harmony with the Ordon yaungol. When the island suddenly disappeared, the Ordon faced certain death. In their desperation, the chief shaman called out for aid to the Fire Lords, and was answered.\n\nOrdos was his name. Now, he is a creature of anger and violence. Though his people were saved, he burns endlessly in molten agony.\n\nThere is harmony no longer. The Ordon seek to take the Celestial Court, and sacrifice us all to Ordos. Drive them back, and restore balance.", objectives = "" }
WordHunterWoW_QuestEN[33343] = { title = "The Archiereus Of Flame", description = "Your efforts have driven back the Ordon and brought peace to the Celestial Court, but it will not last. It is time to silence the great emissary of Ordos - the Archiereus of Flame.\n\nSpeak with Mistweaver Ku and purchase a scroll of challenge, then travel to Three-Breeze Terrace to the north. Issue a challenge at the challenge stone, it will undoubtedly catch the attention of the Ordon, drawing the archiereus out of the Ordon Sanctuary. It is your only chance.", objectives = "" }
WordHunterWoW_QuestEN[33344] = { title = "Armed and Dangerous", description = "Ligra was sent with extra weapons to equip enslaved Frostwolves.\n\nArm the Frostwolf Slaves so they can cut their way from their slavers.", objectives = "" }
WordHunterWoW_QuestEN[33354] = { title = "Den Mother's Demise", description = "This is the pelt of Darkmoon Island's monstrous den mother.\n\nYebb Neblegear, beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.", objectives = "" }
WordHunterWoW_QuestEN[33358] = { title = "Noodle Time: Bonus", description = "Hello, {name}. Think you're a truly extraordinary noodle chef?\n\nLet's see what you've got!", objectives = "" }
WordHunterWoW_QuestEN[33359] = { title = "Meet Us at Starfall Outpost", description = "The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know.\n\nAs soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.", objectives = "" }
WordHunterWoW_QuestEN[33374] = { title = "Path of the Mistwalker", description = "You have heard the words of the celestials, but what did you learn on your path to the shrines?\n\nThe wisdom of the pilgrimage is in its silence and simplicity. As you listen to the wind rustling in the trees, and note even the smallest butterfly, your mind is open to learning the deepest lessons the trials have to teach us. Perhaps you noticed the many great beasts that roam the island?\n\nTherein lies your trial. You have learned much from Pandaria, now let us put your knowledge to the test.", objectives = "" }
WordHunterWoW_QuestEN[33375] = { title = "Refining The Vision", description = "I have finished grinding the stones, and have attuned the hourglass to a new series of timeways. Will you return to the Siege of Orgrimmar and turn the hourglass once more?\n\nReturn quickly, I am most curious.", objectives = "" }
WordHunterWoW_QuestEN[33376] = { title = "Seeking Fate", description = "I have not been completely forthright with you, despite all that you have done to aid the Timewalkers. I cannot tell you everything, not yet, but know this - there is a traitor amongst us. Tell no one of your mission today, and take caution around any of my flight while you hold the Vision of Time.\n\nQuickly now, return to the Siege of Orgrimmar once more and use the hourglass.\n\nAnd be safe.", objectives = "" }
WordHunterWoW_QuestEN[33377] = { title = "Hidden Threads", description = "You have kept our mission a secret, and for that I thank you. Knowledge of the timeways, when in the wrong hands, can cause catastrophic devastation. My flight has little power to repair it, now. We must be careful.\n\nThe hourglass grows in power. I believe it can now be used to see much further than before. I wish you to push it to its limits.\n\nReturn to the Siege of Orgrimmar, and focus the hourglass on the most devastating timeway you can find.", objectives = "" }
WordHunterWoW_QuestEN[33378] = { title = "Courting Destiny", description = "The Vision of Time is nearly perfected, we now have much more control over the visions we seek. Your efforts have been instrumental in completing the artifact and restoring the strength of not only my flight, but also our allies in the Timewalkers. All of us are in your debt.\n\nQuite fortunately, I have located a sort of crux in time - an intersection of timeways - right here in Pandaria. Take the Vision of Time to the Temple of the White Tiger. There, in the cellars, turn the hourglass.", objectives = "" }
WordHunterWoW_QuestEN[33379] = { title = "One Final Turn", description = "I do not wish to ask this of you again, but I do not know who I can trust any longer. I have been using the Vision of Time to gather information, and in my searches, I believe I have found another crux in time. It is in the Caverns of Time itself.\n\nI did not want to believe it when the vision first came to me, but I cannot sit idly by and let this information pass. The Caverns of Time - you must go there, now, and use the Vision of Time.\n\nMove quickly!", objectives = "" }
WordHunterWoW_QuestEN[33406] = { title = "Northshire Sprint Trial: 12", description = "For this challenge: Run through the arch, then get to the blue marker, the green marker, and return here before the bell tolls 12 times.", objectives = "" }
WordHunterWoW_QuestEN[33408] = { title = "Great Balls of Fire!", description = "Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall, also went to lend his skills.\n\nFollow the ramp on the south end of the ramparts outside to join them.\n\nHelp them bring victory to the Frostwolf Clan!", objectives = "" }
WordHunterWoW_QuestEN[33410] = { title = "The Butcher of Bladespire", description = "After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces.\n\nI am still weak after using my magic, but at least I can help this orc in her recovery.\n\nHelp take Dorogg down, {name}.", objectives = "" }
WordHunterWoW_QuestEN[33412] = { title = "Mopping Up", description = "We've won the day, but our work here is far from finished.\n\nFrostwolves will scour the citadel and root out any survivors. To you, I offer the glory of cleansing the gladiator pits to the north.\n\nAs we launched our attack, we dispatched one of our best to recon that area. If you still thirst for blood, join her there. There's surely some sport left.", objectives = "" }
WordHunterWoW_QuestEN[33415] = { title = "Northshire Sprint Trial: 11", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and return here before the bell tolls 11 times.", objectives = "" }
WordHunterWoW_QuestEN[33416] = { title = "South Sprint 12", description = "For this challenge, run through the arch, then get to the red marker, the purple  marker, then return here before the bell tolls 12 times. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[33419] = { title = "A Matter of Life and Death", description = "Stranger, please help me!\n\nMy companions and I ventured here to seek the bounty on a monstrous wasp queen.\n\nAfter we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things!\n\nI don't know where my friends have gone, but I heard screams from further down the cavern.\n\nPlease, find my companions. I can't leave here without them!", objectives = "" }
WordHunterWoW_QuestEN[33423] = { title = "Northshire Dash Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nYou have all the time you need.", objectives = "" }
WordHunterWoW_QuestEN[33424] = { title = "Northshire Dash 12", description = "For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nGet back before you hear the bell toll 12 times.", objectives = "" }
WordHunterWoW_QuestEN[33426] = { title = "New Course: South Sprint", description = "You're running this trial well, but did you know there's another course here in Northshire?\n\nSpeak with my colleague down the road and learn about it.", objectives = "" }
WordHunterWoW_QuestEN[33427] = { title = "Ours is the Fury", description = "Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman.\n\nYou may wish to inform Warmaster Zog in your garrison of what has transpired here.\n\nHe should be able to deploy some of your troops to the area to further secure the area.", objectives = "" }
WordHunterWoW_QuestEN[33428] = { title = "Elwynn Forest Racing", description = "You've done great here, now are you ready to run bigger races?\n\nFind the Elwynn Race Official on the outskirts of Goldshire, and see what she has in store.", objectives = "" }
WordHunterWoW_QuestEN[33429] = { title = "Elwynn Long Distance Trial: 25", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here before the bell tolls 25 times.", objectives = "" }
WordHunterWoW_QuestEN[33430] = { title = "Northshire Sprint - 7", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and return here before the bell tolls 7 times.", objectives = "" }
WordHunterWoW_QuestEN[33431] = { title = "Elwynn South Distance Trial: 30", description = "For this challenge: run through the arch, then get to the red marker, the purple marker, and finally return here before the bell tolls 30 times.", objectives = "" }
WordHunterWoW_QuestEN[33433] = { title = "South Sprint 11", description = "If you want to practice...\n\nFor this challenge, run through the arch, then get to the red marker, the purple  marker, then return here before the bell tolls 11 times. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[33444] = { title = "Eatercology", description = "Drek'Thar thinks the portions of Exurotus consumed by the goren might be worthless. I am not about to step before the fury without at least trying to recover as many of these \"motes\" as possible.\n\nSlay any goren you find at Magnarok and see if you can extract the motes of Frostfire from them.", objectives = "" }
WordHunterWoW_QuestEN[33450] = { title = "The Warlord's Guard", description = "I don't know what you are accustomed to, traveler, but these lands devour the weak. Perhaps Durotan wishes to rid himself of you. We shall see.\n\nYou must kill the Warlord of the Circle of Blood. Do this and the ogres here will be defeated. But first, you must find him.\n\nI have located his bodyguards nearby. Slay them and bring me their heads. With them, we shall lure the Warlord into the open.", objectives = "" }
WordHunterWoW_QuestEN[33454] = { title = "The Cure", description = "Cowards! A curse on these wretched meatbags!\n\nThe Bladespire have always taunted the orc clans by taking our wounded as slaves to fight like dogs in their pits.\n\nIn retaliation for our assault they have poisoned their orc prisoners, leaving them to suffer and die an excruciating death.\n\nOnly their geomancers carry the antidote, traveler. Use it to cure the Frostwolf prisoners.", objectives = "" }
WordHunterWoW_QuestEN[33461] = { title = "Gloomshade Game Hunter", description = "<You find a list on a piece of parchment.\n\nArsenio needs some ingredients for a new recipe he's preparing at your garrison.>", objectives = "" }
WordHunterWoW_QuestEN[33462] = { title = "Thunderlord for a Day", description = "Pieces of a Thunderlord chain lay on the ground. It is of a very simple design, but effective.\n\nWith enough parts, even the most unskilled person could assemble a chain and grapple as effective as those used by the Thunderlord Grapplers.", objectives = "" }
WordHunterWoW_QuestEN[33467] = { title = "The Fall of the Warlord", description = "You've managed to survive this long, stranger. All that remains to be done here is to fell the Warlord of the arena.\n\nThis will be your first true test here. Bult would provide a challenge to even a battle-hardened Frostwolf.\n\nPlace the heads you've collected on spikes in the Frostfire Arena. They are sure to enrage the warlord and lure him into battle.\n\nCome out of the arena victorious and it will show that Durotan's trust in you was not misplaced.", objectives = "" }
WordHunterWoW_QuestEN[33468] = { title = "Save Wolf Home", description = "Cowardly Thunderlords...\n\nDuring the battle for the citadel, runners informed me that the Iron Wolf is striking at our home. He'll find no easy footing there, Draka will make them pay tenfold for any of ours that they slay, but we must return quickly and chase the mongrels off.\n\nYou and your forces have proven valuable allies of the Frostwolves. We'd welcome your aid in securing our Wor'gol.\n\nI'll see you on the battlefield if you choose to come.", objectives = "" }
WordHunterWoW_QuestEN[33469] = { title = "The Farseer", description = "The Thunderlord warleader... {name}, you have to stop him.\n\nHe went to attack Drek'Thar at the Pool of Visions to the northwest!", objectives = "" }
WordHunterWoW_QuestEN[33470] = { title = "Pool of Visions", description = "A terrible storm gathers on the horizon, {class}.\n\nI have prepared a ritual. You must consult the pool to see what destiny holds for us all.", objectives = "" }
WordHunterWoW_QuestEN[33473] = { title = "Back to Bladespire Citadel", description = "Durotan must be told of your vision. Pul Windcarver will offer you a flight back.\n\nThe fate of the Frostwolf... of Draenor, depends upon you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[33483] = { title = "Mulverick's Plight", description = "You were sent here to free me? It seems that makes us allies.\n\nSlavemaster Turgall within the Soostained Mines will certainly have the key to this cage.\n\nWhile you're in there, do you think you could see which of those spineless taskmasters took my axes?", objectives = "" }
WordHunterWoW_QuestEN[33484] = { title = "The Slavemaster's Demise", description = "Share word with the others of the Frostwolves you saved this day. They will be glad to know that some made it out of the mines alive.", objectives = "" }
WordHunterWoW_QuestEN[33492] = { title = "Northshire Sprint Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here.\n\nYou have all the time you need for this.", objectives = "" }
WordHunterWoW_QuestEN[33493] = { title = "Return to the Pack", description = "Part of me agrees with Karg - we COULD challenge the Iron Wolf right now. My fists clench at the mention of his name. My muscles scream for vengeance.\n\nBut then, in my heart, I feel Asha. Calming me. Guiding me. I do not deserve her wisdom, but it is a gift I will not waste.\n\n<Lokra squints at the sky.>\n\nDurotan and the others will be gathering at your garrison about now. We should meet them.", objectives = "" }
WordHunterWoW_QuestEN[33513] = { title = "Blackthorn's Lieutenants", description = "Amnennar's reincarnation is imminent. In order to protect the ceremony Death Speaker Blackthorn has placed his most trusted lieutenants between us and him.\n\nAarux, a plagued spider nests near his young, tended to by the Death's Head Aranomancers. Mordresh rallies Amnennar's forces upon the Bone Pile. Finally, Mushlump stands guarding the entrance to the Spiral of Thorns.\n\nOnce you defeat these guardians I will join you and together we will confront Blackthorn.", objectives = "" }
WordHunterWoW_QuestEN[33514] = { title = "The Ritual", description = "You are good to have come so quickly.  I must ask you to put your lives in danger once more in order to save Kalimdor.\n\nAmnennar's apprentice, Death Speaker Blackthorn, hopes to return his master to the realm of the living!  We must quickly make our way atop the Spiral of Thorns and defeat him before the ritual can be completed.  We must strike together, only with our combined force can we hope to stop him!", objectives = "" }
WordHunterWoW_QuestEN[33526] = { title = "These Colors Don't Run", description = "Bladespire has been a plague on my people for many years.\n\nThat ends today!\n\nNow to explain it to the ogres in a way they will understand.\n\nIf you still wish to help us, place our banner in the corpses of our adversaries. \n\nTheir courage will falter as they behold a field of Frostwolf trophies!\n\nThis is our way. I will meet with you ahead when you have completed this deed.", objectives = "" }
WordHunterWoW_QuestEN[33527] = { title = "Last Steps", description = "In a rage, Ga'nar ascended to fight Gorr'thog, the ogre king.\n\nHe is alone, and the ramp to the throne room is now blocked.\n\nYou've proven resourceful. Perhaps you could find another way up?\n\nI sustained wounds on my way here, but I will work to cut my way through and up the ramp so we may rejoin.\n\nHurry traveler, ensure that the Frostwolf clan wins our assault on the citadel.", objectives = "" }
WordHunterWoW_QuestEN[33530] = { title = "Nightmare in the Tomb", description = "Down there... horrible... bodies everywhere...\n\nDark ritual... please... you must stop it...", objectives = "" }
WordHunterWoW_QuestEN[33533] = { title = "The Secrets of Gorgrond", description = "Our victory today was costly. Too costly. There is no guarantee that we can turn another attack.\n\nWe need to know what the Iron Horde is up to, and there is only one place we can go to find out.\n\nGorgrond.\n\nIt is a savage land that few ever return from.\n\nI mean to go there, I mean to find their stronghold at Blackrock, and I mean to learn how we can defeat these vile orcs.\n\nWill you join me, Commander?", objectives = "" }
WordHunterWoW_QuestEN[33543] = { title = "The Laughing Skull", description = "Ah, {name}, good. I need someone who is not of my clan to negotiate with the Laughing Skull.\n\nWe could use their help navigating this land, but they are dangerous and unpredictable, much like Gorgrond itself.\n\nFollow this road and seek out someone willing to speak with you.\n\nPerhaps they will see you as something new and be willing to talk first and stab later.", objectives = "" }
WordHunterWoW_QuestEN[33544] = { title = "Goren, Goren, Gone!", description = "We... we left the goren alone for too long. They have grown bold and forgotten who we are.\n\nKill them! Kill them all. Rip them apart until they scream. Remind them what happens to anyone who tries to attack a Laughing Skull village.\n\nOh, and welcome to Gorgrond.", objectives = "" }
WordHunterWoW_QuestEN[33546] = { title = "Deeds Left Undone", description = "In his haste, Ga'nar advanced before this area was secured. He is a matchless warrior, mind you, but his tactics are sometimes costly.\n\nGol'kosh and his troops were ordered to destroy enemy supplies, but ogres have stolen the oil he needs.\n\nRetrieve the oil and see that their mission is carried out, traveler. Then, if they still live, direct them to rejoin me at the citadel's entrance.\n\nI must see my wounded brothers to safety.", objectives = "" }
WordHunterWoW_QuestEN[33548] = { title = "We Die Laughing!", description = "Are you here to help or hinder?\n\nThis village is being eaten, and we must move quickly to salvage what we can.\n\nGather the masks of our fallen Laughing Skull brothers and sisters and meet me on the western side of the village.\n\nI will need them if our clan is to rebuild.", objectives = "" }
WordHunterWoW_QuestEN[33562] = { title = "Trophy: Gorg'ak's Obsidian Spines", description = "", objectives = "" }
WordHunterWoW_QuestEN[33563] = { title = "Eye Candy", description = "You! Get in the fight or get out of our way.\n\nThis is no ordinary goren attack. Look over there, a gronnling is sacking our grubhall. That hunchbacked gorebucket bit a chunk out of my lovely Marrow!\n\nRip the eye out of its forehead and bring it to me.\n\nThat should buy me enough time to get her clear of this goren hole.", objectives = "" }
WordHunterWoW_QuestEN[33578] = { title = "Pyrophobia", description = "W- we have done n-n-nothing to provoke the arakkoa... w-why would they attack Aruuna? What do they want from us?\n\nI want to run, but I'm... too afraid. That leader of theirs will burn me to a crisp, I just know it!\n\nH-he's just inside the inn...", objectives = "" }
WordHunterWoW_QuestEN[33579] = { title = "What the Draenei Found", description = "They came here for an artifact? The miners must have found something in our crystal mine to the north.\n\nBy the Light, can you imagine how powerful that thing must be, to attract them all the way here from their spires?\n\nI suppose it is in their hands now... You'd have to be crazy to go looking for it...", objectives = "" }
WordHunterWoW_QuestEN[33580] = { title = "The Purge of Veil Shadar", description = "Not all arakkoa are alike.\n\n<Iskar lifts his sleeve to reveal a mangled, useless wing.>\n\nIt is no illusion. They did this to me. Before I was even given a name, I was given a place in society: at the bottom.\n\nWe are many. We make our homes in the places this world has forgotten.\n\nVeil Shadar was such a place, but the Adherents have found it and started a purge. For morale. For fun.\n\nHelp my people escape, and we'll be in your debt.\n\nWhen the sky burns, it pays to have allies in the shadows.", objectives = "" }
WordHunterWoW_QuestEN[33581] = { title = "Forbidden Knowledge", description = "<Darkscryer Raastok narrows his eyes and looks you up and down.>\n\nSo, you are Iskar's hired hand? Well, I care not whether you are a {race} or an overgrown moth, so long as you are willing to help.\n\nThe Adherents of Rukhmar are closed-minded fools! They forbid the study of shadow magic, branding as heretics anyone who dares to seek answers in the dark.\n\nWe kept many tomes of forbidden knowledge in Veil Shadar. Bring any you find to me, and I will reward you for keeping them from the flames.", objectives = "" }
WordHunterWoW_QuestEN[33582] = { title = "Kura's Vengeance", description = "I was a wing-guard myself, once upon a time.\n\nOne afternoon, I was caught away from my post. I just wanted an hour to watch the festival... Kuuan was supposed to cover for me, but instead he sold me out to gain favor with our superiors.\n\nThey plucked my eyes, broke my wings, and threw me off the spire.\n\nYet I am the fortunate one, for if Iskar hadn't found me, I'd have died there. And now Kuuan shows his face in Veil Shadar on the same day that you show up willing to kill for coin. Fortunate, indeed.", objectives = "" }
WordHunterWoW_QuestEN[33586] = { title = "Chasing Shadows", description = "Not all of the Shadowmoon orcs followed Ner'zhul's alliance with the Iron Horde.\n\nAmong them, there is one orc whom I befriended many years ago. She may be able to tell us more about Ner'zhul's plans for this \"Dark Star.\"\n\nShe can be found at Exile's Rise to the northeast. I will send word ahead so she expects your arrival.", objectives = "" }
WordHunterWoW_QuestEN[33593] = { title = "A Flare for the Dramatic", description = "I received a strange object with a note attached. Here, it seems to be written in your tongue, commander.\n\n<Dear Mister Durotan,\n\nI'm Penny... you know, from Azeroth? We met briefly back at {name}'s garrison. \n\nAnyway, like I told you, I have a fifth degree black hammer in engineering and I'm eager to serve. The more danger the better!\n\nYou just fire this old flare whenever you're in trouble and I'll be there, quick as a quark!\n\nHopefully,\n\nPenny>", objectives = "" }
WordHunterWoW_QuestEN[33609] = { title = "Northshire Dash Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nYou have all the time you need.", objectives = "" }
WordHunterWoW_QuestEN[33622] = { title = "To the Slaughter", description = "This entrance to the fortress is clear again, thanks to your help.\n\nInside is another story. Find your way inside and leave no ogre standing as you go.", objectives = "" }
WordHunterWoW_QuestEN[33633] = { title = "Rooter the Ravenous", description = "The stray boar is digging through garbage left behind by the iron horde. He stops chewing and stares at you-then he burps.\n\nHe smells terrible.\n\nIt looks like he's chewing on a chunk of rotten meat. Maybe you can find something a bit healthier for him to snack on?", objectives = "" }
WordHunterWoW_QuestEN[33657] = { title = "Moving In", description = "Gorr'thog is now dead. It is time now to secure our hold on Bladespire Citadel. Meet me below and we can begin strengthening our presence.", objectives = "" }
WordHunterWoW_QuestEN[33660] = { title = "The Sacking of the Saberon", description = "The stash mostly contains bits of old animal parts and other junk. Upon closer inspection there are remains of a bundle of herbs and plants.\n\nRakthoth might be more willing to help if some of these herb bundles were found and gathered for her...", objectives = "" }
WordHunterWoW_QuestEN[33661] = { title = "Steamscar \"Reagents\"", description = "Now we get to the heart of the matter, heh. Saberon have strong hearts, our shaman find many uses for them.\n\nI will search for the ancient's magic if you get me those hearts. Do we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[33662] = { title = "Beatface vs. Boulder", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a boulder, but it looks weak. A strong warrior, such as an ogre, could break it.\n\nI think you know an ogre gladiator...", objectives = "" }
WordHunterWoW_QuestEN[33663] = { title = "Shredder vs. Saberon", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a tangle of hard vines. I have heard you have a machine that could cut through that with ease.\n\nI would get on a shredder and take those vines down.", objectives = "" }
WordHunterWoW_QuestEN[33684] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "" }
WordHunterWoW_QuestEN[33685] = { title = "Ambassador to the Ancient", description = "I have seen a tough looking \"tree\" in that growth. It cries and moans but does not act hostile.\n\nIt may know how to get rid of these plants. Go and see if it does.", objectives = "" }
WordHunterWoW_QuestEN[33689] = { title = "Plant Pruning", description = "I have a hunting den not far from here where I gather my trophies as well as reagents for the Laughing Skull. Not long ago this giant plant monster charged in from the overgrowth and was killed by several of the giant rock monsters. Since it died smaller plant beasts have sprung up and made a mess of the place.\n\nThey have also cut me off from my best source of reagents. Kill them, I will attempt to reach my den and salvage what I can...", objectives = "" }
WordHunterWoW_QuestEN[33694] = { title = "Reagents from Rakthoth", description = "The destruction of our village will not be easy to come back from. Our best hunter, Rakthoth, \"finds\" reagents for our shaman.\n\nShe has not been seen for some time and we need those more than ever. Go to her hunting grounds and see if she still lives.", objectives = "" }
WordHunterWoW_QuestEN[33695] = { title = "Taking the Death Bloom", description = "You have helped me and now I will help you, {name}. The bloom you seek is within the nearby cave, being pawed over by the new leader of these saberon.\n\nKill him and take the bloom back to the ancient below. I hope this will clear out those plants and I can get back to my hunting...", objectives = "" }
WordHunterWoW_QuestEN[33706] = { title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", objectives = "" }
WordHunterWoW_QuestEN[33720] = { title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it in the cave on Talador beach until you've worked out the kinks.\n\nI will send Engineer Draxen to work on it in the meantime.\n\n- Orgrim Doomhammer", objectives = "" }
WordHunterWoW_QuestEN[33721] = { title = "Gazlowe's Solution", description = "I've identified some high value targets down in the forest below.\n\nWhen you get near one, you can deploy my solution.\n\nDeploy it and the objectives will be neutralized with great ceremony.", objectives = "" }
WordHunterWoW_QuestEN[33722] = { title = "Too Many Irons in the Fire", description = "We must not head into battle prematurely. Before we go after Orgrim, we must first deal with his troops.\n\nIf we are to succeed in our mission of wiping out the Iron Horde from Talador, we need to start on these shores.", objectives = "" }
WordHunterWoW_QuestEN[33724] = { title = "Vol. X Pages ?", description = "The manual for the shredder was wedged in there, but it's missing lots of pages. We need to find as many pages of that manual as possible and I might--MIGHT--be able to get this shredder operational.\n\nBased on the direction of the wind, I bet the pages flew toward Archenon Siegeyard.", objectives = "" }
WordHunterWoW_QuestEN[33727] = { title = "Heal Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[33728] = { title = "An Eye for a Spy", description = "Excellent, excellent! I'll make sense of these manual pages and will get the Iron Shredder operational immediately!\n\nWhile I do that, take a look through my Eye 'n' Ear. That's where you'll be headed soon!", objectives = "" }
WordHunterWoW_QuestEN[33729] = { title = "Born to Shred", description = "The Iron Shredder is operational! It should be primed and ready for you to shred our enemies in Tuurem!\n\nHead inside and see what damage you can do. Can't say I'm not jealous.", objectives = "" }
WordHunterWoW_QuestEN[33730] = { title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", objectives = "" }
WordHunterWoW_QuestEN[33731] = { title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", objectives = "" }
WordHunterWoW_QuestEN[33732] = { title = "Sabotage Siege Weapons", description = "", objectives = "" }
WordHunterWoW_QuestEN[33734] = { title = "Pieces of Us", description = "When the fires broke out, I took only my daughter's hand before we fled. It was the right decision, of course, but I do long for some of the things we left behind.\n\nI am an artificer, a shaper of crystals and gems. Without my tools I am just another refugee.\n\nOur town records are kept in a memory crystal in the main hall. With it, I can carry forward the knowledge and legacy of Aruuna.\n\nAlso, my daughter is terrified - it would be a great comfort for her to hold her favorite doll again.", objectives = "" }
WordHunterWoW_QuestEN[33735] = { title = "In Short Supply", description = "The enemy has explosive devices stored on the beach below. We must recover them so they are not used against us.\n\nReports indicate that crates of explosives are scattered along the shoreline.\n\nWhile you search, Durotan and I will carve deeper into Iron Horde territory.", objectives = "" }
WordHunterWoW_QuestEN[33736] = { title = "Iron Them Out", description = "The orcs themselves are not the only threat. We may have weakened them considerably, but they still have siege weapons of significant power.\n\nSabotage siege weapons you find with the explosives you collected from the beach.", objectives = "" }
WordHunterWoW_QuestEN[33740] = { title = "Burning Sky", description = "It happened so fast. A white-hot flash of light ignited the nearby woods, followed by terrible winds that swept the flames across Aruuna.\n\nMoments later, arakkoa began descending through the smoke.\n\nI need to get Melani to the Pilgrim's Road. From there we can head for Anchorite's Sojourn and the protection of the vindicators. With the arakkoa roaming the area freely, I fear we'll be run down or worse: taken by the spreading wildfires.", objectives = "" }
WordHunterWoW_QuestEN[33754] = { title = "Through the Looking Glass", description = "Your allies sent along a goblin, Gazlowe, to advise us against the Iron Horde. Thus far, he has proven a valuable asset.\n\nHe has a looking glass set up that can see a great distance and, he claims, even hear.\n\nUse this looking glass and report back what you've seen. I will stick to my standard spyglass.", objectives = "" }
WordHunterWoW_QuestEN[33761] = { title = "Barum's Notes", description = "<This hefty tome contains notes on the refining and shaping of Draenor's natural gems and crystals, including several full-page technical diagrams depicting complex cut patterns.\n\nThe most recent pages detail a series of cuts intended to aid the draenei vindicators in battle.>\n\n\"...honed to a fine edge, the material can expose weaknesses...\"\n\n\"when rounded and polished to such a degree, it wards off harmful...\"\n\n\"...this incredible discovery that a crystal can be attuned to the bearer's vitality!\"", objectives = "" }
WordHunterWoW_QuestEN[33765] = { title = "Dark Enemies", description = "Your arrival should be cause for celebration, hero, but I fear our troubles are just beginning.\n\nWarlord Ner'zhul and his Shadowmoon clan have launched a surprise attack on a draenei settlement to the north.\n\nProphet Velen has gone to aid the wounded at Teluuna Observatory, but we need more defenders.\n\nI must go to assist the others. If you wish to help us, go to Arbor Glen and kill any Shadowmoon enemies that you see.", objectives = "" }
WordHunterWoW_QuestEN[33782] = { title = "Keeping the Balance", description = "Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin.\n\nIt is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life.\n\nTrack down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.", objectives = "" }
WordHunterWoW_QuestEN[33784] = { title = "Gormaul Tower", description = "It is time for us to strike out against those who would enslave us!\n\nWe travel to Gormaul Tower to wrest it from the Bladespire ogres. I would welcome your company.\n\nMount up, and together we will ride to battle!", objectives = "" }
WordHunterWoW_QuestEN[33785] = { title = "Karg Unchained", description = "They took my brothers and sisters.\n\nThey took my wolf.\n\n<Karg lifts his axe and fixes his gaze upon its edge.>\n\nNow we take their heads.", objectives = "" }
WordHunterWoW_QuestEN[33786] = { title = "Crippled Caravan", description = "I'm getting reports that the botani have started leaving their bloom and attacking wandering travelers. This is most unusual.\n\nWe already dispatched a number of rangari to try and resolve this issue.\n\nA caravan from Azeroth passed through here recently, you should probably check on your people to ensure their safety.", objectives = "" }
WordHunterWoW_QuestEN[33787] = { title = "Fiona's Solution", description = "Gidwin was attacked by one of those plant creatures.\n\nFrom the looks of it, he is suffering from some kind of paralysis.\n\nI can make a cure, but I'll need some local ingredients.", objectives = "" }
WordHunterWoW_QuestEN[33788] = { title = "Cooking With Unstable Herbs", description = "The base is boiling and ready for those ingredients.\n\nAdd each of the ingredients, one at a time, and I will handle the mixing and frothing. Speak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[33793] = { title = "Harbingers of the Void", description = "Our scouts have made a horrifying discovery, {name}.\n\nThe souls of the prisoners are being used to summon creatures from the void.\n\nInside, three beings of darkness already await - the Essence of Shadow, the Essence of Darkness, and the Essence of Anguish.\n\nThey must be destroyed immediately, before their power can be unleashed.", objectives = "" }
WordHunterWoW_QuestEN[33794] = { title = "The Great Salvation", description = "We've located the prisoners. They are being held in captivity here, inside the Shadowmoon fortress.\n\nPlease rescue as many of them as you can. And hurry. We can hear their screams out here.", objectives = "" }
WordHunterWoW_QuestEN[33795] = { title = "Across the Stars", description = "A key source of the Shadowmoon clan's power comes from their understanding of the stars and their omens.\n\nFor centuries, they have recorded the patterns of the stars and their interpretations.\n\nWhile you are in the fortress, collect some of these documents for me.\n\nWe will take their own knowledge and use it against them.", objectives = "" }
WordHunterWoW_QuestEN[33807] = { title = "Free Our Brothers and Sisters", description = "These Thunderlord curs use coward's weapons like nets and chains.\n\nMany of our villagers and wolf-brothers and sisters have been trapped.\n\nIf you free them, they will fight at your side with honor.\n\nWe must quell this attack with haste so I may return to Bladespire Citadel and continue my preparations.", objectives = "" }
WordHunterWoW_QuestEN[33808] = { title = "Swamplighter Queen", description = "It looks like those plant creatures used some kind of poison when they attacked Gidwin.\n\nIt's a powerful concoction to say the least.\n\nIf we are going to cure Gidwin we need one more special ingredient. This one might be a bit harder to obtain than the others.\n\nYou up to the challenge, {name}?", objectives = "" }
WordHunterWoW_QuestEN[33813] = { title = "In Need of a Hero", description = "I...<sob>... I can't leave...<gulp>... without... Squiggy...!\n\nHe... he's... trapped!\n\nYou need... to put out... the fire!\n\n<Ariaana points across the room and bursts into tears.>", objectives = "" }
WordHunterWoW_QuestEN[33814] = { title = "Fast Expansion", description = "Greetings, Commander.\n\nI am here on behalf of architect Baros Alexston.\n\nWe have gathered enough resources for the next phase of expansion.\n\nHe wishes to speak to you at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[33815] = { title = "A Song of Frost and Fire", description = "You have rescued many of my clan from the slave pens of Tanaan. Their liberation and the destruction of the Dark Portal are more than enough for me to consider you one of us.\n\nHowever, you are still a stranger to our leader, Durotan. I would like to introduce you to him.", objectives = "" }
WordHunterWoW_QuestEN[33816] = { title = "Honor Has Its Rewards", description = "You have honored my people. Now, we wish to honor you.\n\nWe have a rite of initiation in my clan. When one comes of age, they cover themselves in the blood of their first hunt, and rest their hands upon a shamanstone to honor the ancestors who came before them.\n\nIn our brief time together you have already slain many foes more fierce than our hunters have ever had to face. Go, touch the shamanstone here in Wor'gol, and join our pack as an equal.", objectives = "" }
WordHunterWoW_QuestEN[33826] = { title = "Where's My Wolf?!", description = "My frost wolf, Nerok, was captured with me and the others. I do not know where they are keeping him, but I'll bet the so-called \"beastmaster\" who dragged us here does.\n\nHe is at the beast pens nearby, boasting about his catch to the younger hunters.\n\nWe'll see how he boasts with my axe in his skull.", objectives = "" }
WordHunterWoW_QuestEN[33828] = { title = "The Master Siegesmith", description = "Not long ago, the most advanced weapon a Thunderlord could make was a really, really big spear. The Blackrock orcs must have shipped in a fearsome master to have them producing cannons so rapidly.\n\nWe need to find that master.", objectives = "" }
WordHunterWoW_QuestEN[33833] = { title = "WANTED: Kuu'rat's Tusks", description = "Posted by: Eremor\n\nA ferocious elekk of unprecedented size has been seen near Gloomshade Grove.\n\nKnown to some as the ivory death, she is abnormally aggressive and has already taken the lives of several unwary travelers.\n\nThe rangari have as yet been unable to corner this creature. Anyone capable of taking down this beast should exchange proof of her demise to Eremor for a hefty bounty.", objectives = "" }
WordHunterWoW_QuestEN[33834] = { title = "WANTED: Kliaa's Stinger", description = "Posted by: Dyuna\n\nA vicious queen swamplighter has made the northern forests of Shadowmoon its home.\n\nUnfortunately, this poisonous pest terrorizes the forest between Embaari Village and Shattrath. As local traders put their lives at risk, prices of goods will continue to rise.\n\nAnyone who can put an end to the beast should detach its stinger as proof and bring it to Dyuna in Embaari Village. The merchant traders will reward generously.", objectives = "" }
WordHunterWoW_QuestEN[33836] = { title = "WANTED: Maa'run's Hoof", description = "Posted by: Orrin\n\nA wild talbuk called \"Maa'run\" wanders the hills southeast of Embaari Village and west of The Draakorium.\n\nMy brother was injured by this foul beast, and now lays in recovery.\n\nFor the safety of all the nearby villages, we must put an end to this vicious, rampaging creature!\n\nA handsome reward will be given to anyone who can bring me his hoof as proof of his demise.", objectives = "" }
WordHunterWoW_QuestEN[33837] = { title = "Darkness Falls", description = "It is already beginning, over the hills to the southeast.\n\nNer'zhul has everything he needs to summon the Dark Star. The Iron Horde attack on Karabor is imminent. This is where everything ends.\n\nChampion, I must ask you to ride ahead and delay Ner'zhul. I will join you as quickly as I can.", objectives = "" }
WordHunterWoW_QuestEN[33838] = { title = "Smeltcraft", description = "Stranger! Thank the spirits for them sending you to me now. I am forging a blade and cannot leave it at this delicate state.\n\nBut I need more ore to complete this task.\n\nHere, take my mining pick. It is crafted from the teeth and acid of the local goren and will cut through the ore of this area as if it were air.\n\nBring me the ore and I will lend this blade to your cause.", objectives = "" }
WordHunterWoW_QuestEN[33868] = { title = "The Home of the Frostwolves", description = "You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.", objectives = "" }
WordHunterWoW_QuestEN[33871] = { title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far south of here, and fulfill your destiny.", objectives = "" }
WordHunterWoW_QuestEN[33872] = { title = "Dust of the Dead", description = "I thought if I could just bring him here that I might be able to correct his transgression against the Light. That perhaps I could save my son! Now my beloved Arumel is a twisted phantasm.\n\nI'm left with no choice but to right my wrongs and I need your help.\n\nBring me duskwing dust from the moths on Duskfall Island. With your aid I can craft an elixir that will let us travel to the realm of the dead and lay Arumel to rest.", objectives = "" }
WordHunterWoW_QuestEN[33873] = { title = "Cure of Aruunem", description = "I need your help in creating an elixir that will allow us passage into the realm of the dead.\n\nIn order to create it I require a sampling of the local vegetation. You will find Aruunem berries scattered about on the island. Bring me as many as you can carry.\n\nBe warned, {name}: do not eat them raw! The poison in the berries would kill you within minutes!", objectives = "" }
WordHunterWoW_QuestEN[33874] = { title = "Aruumel's Rest", description = "It is my job to see what others cannot. I keep the memories and read them for others, but I can no longer do so because of my son.\n\nMy son turned his back on the light. When he perished I could not stand the thought that his spirit might not be welcomed into Auchindoun.\n\nI interfered and trapped him here. Now he twists and tortures the memories until they cannot be read.\n\nYou must do what I cannot bear to do myself. Use this elixir to enter the spirit realm...\n\n...and destroy my son's spirit.", objectives = "" }
WordHunterWoW_QuestEN[33882] = { title = "Just Peachicky", description = "That mean old Sher'khaan! He's always been a bully to these poor peachicks, but this is crossing the line!\n\nI was trying to move this poor clutch out of the way of the demons when he attacked! Now the peachicks are spread out all over and they're scared!\n\nPlease help me bring them all back!", objectives = "" }
WordHunterWoW_QuestEN[33884] = { title = "Sher'KHAAAAAAANNNN!", description = "The tigers here have gotten out of control! They're everywhere and meaner than ever!\n\nSher'khaan is the worst of them! He's huge and mean! Maybe a brave adventurer like you could take care of Sher'khaan and the other tigers once and for all.", objectives = "" }
WordHunterWoW_QuestEN[33898] = { title = "Slaying Slavers", description = "These ogres keep takin' my clan and turnin' them into slaves!\n\nSlay some ogres and I'll hold 'em off if they try to run.", objectives = "" }
WordHunterWoW_QuestEN[33905] = { title = "Closing the Door", description = "The Shadowmoon orcs are using portals to bring in reinforcements and smuggle away draenei captives.\n\nIf we are to have any hope of retaking the village, we must destroy the portals at once.\n\nThe only way to do this is to kill the portalmasters who keep the rifts open.", objectives = "" }
WordHunterWoW_QuestEN[33915] = { title = "Young Hearts", description = "My nephew never pays attention to his surroundings. In his eagerness to prove himself, he has strayed from the pack -- again.\n\nHe reminds me of myself when I was a youngling.\n\nIf you see Orac, tell him to return home. We need to finish preparing for tomorrow's hunt.", objectives = "" }
WordHunterWoW_QuestEN[33917] = { title = "Disrupting the Flow", description = "You there, we need to stop the flow of demon reinforcements!\n\nDo you see the floating fel crystals spread throughout the front? Those resonators are powering the portals unleashing hell on our forces. I need you to take them out!", objectives = "" }
WordHunterWoW_QuestEN[33918] = { title = "WANTED: Grondo's Bounty", description = "Grondo, a mad gronn, has been seen roaming the Crackling Plains.\n\nThis beast has been killing entire herds of clefthoof and devouring innocent frost wolves. We must destroy this threat before it reaches the Garrison.", objectives = "" }
WordHunterWoW_QuestEN[33919] = { title = "WANTED: Gutsmash the Destroyer", description = "Gutsmash has proven to be more than a worthy adversary. Gather a small group together and end his reign of terror once and for all.", objectives = "" }
WordHunterWoW_QuestEN[33920] = { title = "The Heart of Auchindoun", description = "A band of Shadow Council orcs stole the Heart of Auchindoun!\n\nThe Heart powers all of Auchindoun's defenses. Thankfully we were able to save its core and one of its four pieces.\n\nThe warlock O'mogg Blackheart is using Karab'uun, one of the stolen pieces, to power the largest portal in the Burning Front. Return Karab'uun to me.", objectives = "" }
WordHunterWoW_QuestEN[33928] = { title = "A Wrong of Earth and Fire", description = "The molten core appears to be the mutated remains of an elemental that consisted of both earth and fire.\n\nSlag elementals should not exist upon the plateau where the elements live in purity.\n\nYou decide that the core should be taken to Incineratus at the Throne of Elements for examination.\n\nPerhaps the great fury of fire will know what to make of this core and your battle with Magmire.", objectives = "" }
WordHunterWoW_QuestEN[33929] = { title = "Shivertail's Den", description = "The Frostwolf pup looks at you with his big eyes. He howls and stares into the cave.\n\nIt's unusual for a wolf this young to be wandering around by itself. Shivertail's parents must be nearby.", objectives = "" }
WordHunterWoW_QuestEN[33931] = { title = "This Is Not a Quest", description = "We need help! But not from you...", objectives = "" }
WordHunterWoW_QuestEN[33944] = { title = "And the Elekk Too?!", description = "The little stuffed elekk has seen better days. It's torn and the stuffing is poking out.\n\nThe name Caleb is sewn onto the bottom of the left back foot. Sher'khaan must have snatched it from the cart. The little draenei might appreciate its return.", objectives = "" }
WordHunterWoW_QuestEN[33955] = { title = "Missing Pack", description = "Strange, I wonder where little Shivertail and his pack are? They normally show up for a feeding about now.\n\nI hope everything is alright.", objectives = "" }
WordHunterWoW_QuestEN[33957] = { title = "A Gift for Raa'la", description = "I need to pack up this kill.  I promised my daughter Raa'la I would bring her home a gift from the hunt.\n\nThere are a couple baby Rylaks in the cave nearby. Maybe Raa'la would like one as a pet?\n\nWould you mind catching one while I finish up here?", objectives = "" }
WordHunterWoW_QuestEN[33958] = { title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", objectives = "" }
WordHunterWoW_QuestEN[33967] = { title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", objectives = "" }
WordHunterWoW_QuestEN[33969] = { title = "Vile Defilers", description = "The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information.\n\nOur scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions!\n\nWe must destroy the defiling crystals so this madness does not spread.", objectives = "" }
WordHunterWoW_QuestEN[33970] = { title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", objectives = "" }
WordHunterWoW_QuestEN[33971] = { title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", objectives = "" }
WordHunterWoW_QuestEN[33972] = { title = "Vile Defilers", description = "The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims.\n\nWe are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions!\n\nWe must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!", objectives = "" }
WordHunterWoW_QuestEN[33973] = { title = "Dying Wish", description = "I am too far gone to rescue, but thank you for speaking with me.\n\nBlademaster Bralok had his men starve and beat me, and he stole an heirloom that has been in my family since before we arrived on Draenor.\n\nShould you find it, please let me see it once more so I may die in peace.", objectives = "" }
WordHunterWoW_QuestEN[33974] = { title = "Dying Wish", description = "This appears to be an ancient Draenei heirloom. Blood stains on it would indicate that it was taken from its owner by force.\n\nAn inscription on the back says \"Ahm,\" which is likely its rightful owner.", objectives = "" }
WordHunterWoW_QuestEN[33976] = { title = "The Final Piece", description = "I am too injured to fight, {class}. I have failed my city and its people. This battle is yours.\n\nVorpil waits just ahead. He's trying to use Auch'naaru's powers for some sort of dark ritual.\n\nYou must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!", objectives = "" }
WordHunterWoW_QuestEN[33988] = { title = "Invasion of the Soul Eaters", description = "<The note is scrawled hurriedly across the parchment.>\n\nTelmor is lost. The Shadow Council is dragging our fallen into piles and feeding the souls to their leader. There is blood on my hands...\n\nPlease, if anyone reads this message, burn the bodies of our fallen so our enemy cannot use them.\n\n- Restalaan, Captain of the Guard", objectives = "" }
WordHunterWoW_QuestEN[34012] = { title = "Need More Teeth", description = "<Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.>\n\n<It has several knots that appear to be missing additional teeth.>", objectives = "" }
WordHunterWoW_QuestEN[34013] = { title = "Never Forget", description = "We had to escape Telmor with what few we could save.\n\nSomeone disabled Leafshadow's cloaking field; I know not who, but I suspect it had to have been one of our own.\n\nWe will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts.\n\nIf you are able, bring Leafshadow, our town registry, and our prayerbook to safety.", objectives = "" }
WordHunterWoW_QuestEN[34019] = { title = "Shadows Awaken", description = "We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him.\n\nHe has taken Yrel's sister, Samaara.\n\nI am needed to hold the line here. Please, do whatever you can to save her, hero.", objectives = "" }
WordHunterWoW_QuestEN[34026] = { title = "Garrison Campaign: Seismic Matters", description = "One of our junior surveyors has been harassing me about unusual seismic activity. I find it hard to believe that we accidentally built on some kind of fault line - we triple checked!\n\nCan you have a word with him?", objectives = "" }
WordHunterWoW_QuestEN[34027] = { title = "Groundbreaking Data", description = "Aye, we triple-checked the site before we set up here. Nary a peep from the ol' earthly deep.\n\nBut there's been rumblin's today, and they're gettin' closer! I tell ya somethin' ain't right!\n\nYe don't have to take my word for it - the Tremor-Tracker is just about finished collecting data. Check it out an' see fer yerself!", objectives = "" }
WordHunterWoW_QuestEN[34028] = { title = "These Look Familiar...", description = "So what is the Iron Horde doing with Dark Iron technology? I know who ta ask!\n\nThaelin Darkanvil is a genius engineer from the Dark Iron clan who's been helping us here on Draenor. You may have already met him in yer travels, eh?\n\nWord is he set up a bunker somewhere in Gorgrond, a secret workshop so-to-speak. If ye can find him, he may know somethin' about this.\n\nEr, and be cautious, eh? The Dark Iron may be our allies now, but I trust 'em about as far as I can throw 'em.", objectives = "" }
WordHunterWoW_QuestEN[34029] = { title = "The Prototype", description = "A few days ago a bunch of Iron Horde orcs showed up and kidnapped Thaelin. They've been keeping me alive as collateral to make sure he cooperates.\n\nI don't know where they took him, but I know how to get us there.\n\nThaelin keeps a tracking device on him at all times - don't ask where he hides it. Anything he makes that can move has a \"Come to Papa\" button that sends it straight to him.\n\nIn retrospect, not a great feature for the walking bombs... but perfect for the mole machine! Jump in and let's go!", objectives = "" }
WordHunterWoW_QuestEN[34030] = { title = "The Captive Engineer", description = "Argh... I'm sorry, {name}, but I'm too weak to fight. They kept me alive, but just barely.\n\nI'll keep an eye on the mole machine while you look for Thaelin. He should be somewhere close!", objectives = "" }
WordHunterWoW_QuestEN[34031] = { title = "Something to Remember Me By", description = "The Iron Horde want my inventions so bad? Then we'll leave some behind.\n\nThese little beauties will blow the treads clear off a tank AND melt her chassis into the dirt. Let's see them try and drive their shoddy cannons out of this place!", objectives = "" }
WordHunterWoW_QuestEN[34032] = { title = "Privileged Information", description = "I'm not the only prize the Iron Horde brought back after raiding my workshop.\n\nOverlord Blackhammer, the maniac in charge of this operation, took my notebook as his own personal treasure.\n\nManufacturing techniques; schematics for new inventions; embarrassing doodles.\n\nIt's got all my secrets!\n\nCan I count on you to help me get it back?", objectives = "" }
WordHunterWoW_QuestEN[34033] = { title = "And The Mole You Rode In On", description = "I think we've kept Hansel waiting long enough. Can you take me to him? Then we can all hitch a ride out of here on the mole machine.", objectives = "" }
WordHunterWoW_QuestEN[34034] = { title = "Garrison Campaign: Grinding Gears", description = "Commanda! Da Frostwolf orcs at Thunder Pass have reported a horrible grinding noise boomin' tru da canyon. We suspect it's some kind of Iron Horde war machine.\n\nGazlowe has agreed ta investigate, but he be wantin' a cash bonus. Goblins! Meet wit him at Thunder Pass and deliver dis payment.", objectives = "" }
WordHunterWoW_QuestEN[34035] = { title = "I Know The Drill!", description = "It's a machine alright. A drill - a BIG one! Fortunately, we don't have to take apart the whole thing.\n\nThey're relying on forced induction, using twin superchargers to pipe extra boost into the engine. Without that boost, the drill is useless.\n\nGet in there and open the clutch on the back of the drill. That'll draw some attention away from the turbines.\n\nI'll take care of the turbines - you just worry about the hordes of bloodthirsty orcs.", objectives = "" }
WordHunterWoW_QuestEN[34039] = { title = "WANTED: Overlord Blackhammer", description = "So, we COULD just leave now. We got what we came for, and I even did a little charity work to help Thaelin escape.\n\nBut there's also this.\n\n<Gazlowe holds up a scrap of paper showing a hand-drawn depiction of an especially mean looking orc.>\n\nIt's an SI:7 bounty for one Overlord Blackhammer, who just happens to operate out of this very facility. You help me take him out, I pay you. Then I take his head to the Alliance and collect on the bounty. Everyone wins!\n\nWell, everyone except for Blackhammer.", objectives = "" }
WordHunterWoW_QuestEN[34040] = { title = "Maker's Mark", description = "I don't get it - most of the Iron Horde junk is about as advanced as strapping cannons to a gronn. Even the drill itself is nothing special. But that induction system was a work of art...\n\nThis don't add up at all!\n\nDespite my better judgment, I gotta find out who made this. I wanna look at more of what they got in the Iron Siegeworks, see if anything's been signed.\n\n<Gazlowe pats the sack of coins on his belt.>\n\nWhaddaya say? Wanna be my bodyguard?", objectives = "" }
WordHunterWoW_QuestEN[34041] = { title = "Four Finger Discount", description = "I gotta admit, establishing a supply chain to a primal world on the wrong side of time is tough, even for me. Gotta make due with, uh... \"locally sourced\" goods.\n\nSay what you want about the Iron Horde, but when it comes to raw materials, they got connections!\n\nKeep an eye out for some of the more valuable goods in the Iron Siegeworks. I packed a few rocket chickens we can use to send the good stuff back to your garrison.", objectives = "" }
WordHunterWoW_QuestEN[34042] = { title = "A Fellow Gearhead", description = "There's no way Thaelin sold out. NO way! They gotta be holdin' him here somewhere.\n\nCome on, {name}. I know he's with the Alliance, and I know they aren't your favorite people, but we do NOT want the Iron Horde having access to his work - trust me!", objectives = "" }
WordHunterWoW_QuestEN[34043] = { title = "Darkest Night", description = "This keystone will grant its bearer entry into Anguish Fortress.\n\nTake it and meet Prophet Velen outside the Shadowmoon fortress.\n\nHe intends to face Ner'zhul head-on.", objectives = "" }
WordHunterWoW_QuestEN[34048] = { title = "\"Mole Machine, Go Home\"", description = "My patented \"Come to Papa\" voice command was only the first step.\n\nI also programmed all of my mole machines with a \"Go Home\" command that'll send 'em auto-diggin' to a pre-determined location - my workshop in Gorgrond!\n\nLet's send the mole machines home before the orcs stink 'em all up with their stupid breath and their sweaty... leather... thongs.\n\n<You hear Thaelin gagging a little from inside The Suit.>\n\nBlech!", objectives = "" }
WordHunterWoW_QuestEN[34054] = { title = "The Dark Side of the Moon", description = "<Prophet Velen's voice continues.>\n\nYrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", objectives = "" }
WordHunterWoW_QuestEN[34063] = { title = "Enemies Above", description = "We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf {name}, but we can not rest yet.\n\nThe Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us.\n\nI sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. \n\n Lok'tar {name}!", objectives = "" }
WordHunterWoW_QuestEN[34066] = { title = "Savage Vengeance", description = "The Thunderlord are a blight {name}.\n\n<Ruk'gan spits in disgust.>\n\nMy daughter, Grishna, was killed by those monsters. Only their blood will bring me peace now.\n\nIf you would help me then I need you to cause a distraction so I can sneak to a position closer to their camp.\n\nKilling a few of their so called \"Iron Thunderguard\" would be perfect.", objectives = "" }
WordHunterWoW_QuestEN[34067] = { title = "A Collection of Coils", description = "This coil of rope has been woven thick, the better for the Thunderlord Wranglers to handle the dangerous beasts they tame.\n\nScout Ruk'gan might have a use for this and a few more like it.", objectives = "" }
WordHunterWoW_QuestEN[34069] = { title = "Getting the Points", description = "The Thunderlord Spear is extremely light and strong.\n\nScout Ruk'gan might be able to use this and a few more like it.", objectives = "" }
WordHunterWoW_QuestEN[34070] = { title = "At the End of Your Rope", description = "With the spears and rope you gathered the Thunderlord Sky Riders will no longer be out of our reach. Even they will feel our wrath!\n\nI've tied the rope to the spears you brought me to fashion a harpoon. Hunt the Sky Riders that are flying all over the valley. Take the Harpoon and throw it at them as they circle by. If your aim is true the barbs should allow the spear a firm hold allowing you to yank the rider right towards you!\n\nIf your aim is bad... well... try not to miss.", objectives = "" }
WordHunterWoW_QuestEN[34072] = { title = "Tar Get of Opportunity", description = "General Vul'gath leads this band of Thunderlord. He is a coward and hides in his hut, yelling orders at his warriors through the walls.\n\nWe will need to show him that his flimsy defenses can not stand against the Frostwolves!\n\nI'll need some tar to carry this out. There are a couple of tar pits to the south, go gather a few globs from the oozes that reside there and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[34073] = { title = "Burn Them Down", description = "Now, we begin our assault, {name}!\n\nGet down to Agurak's Fall and use these tarbombs to destroy their rylak egg incubators.\n\nWhile you are busy I will sneak down into their camp and prepare for the next phase of our attack. Meet me there once you have burned everything.", objectives = "" }
WordHunterWoW_QuestEN[34075] = { title = "Vul'gath's End", description = "Vul'gath's time has come to an end, {name}. My daughter's blood is upon his hands, now his blood will be on ours!\n\nShow no mercy and strike him down!", objectives = "" }
WordHunterWoW_QuestEN[34078] = { title = "Payment Due for Services Rendered", description = "I'm ready to get outta here, and I ain't hoofin' it back through all those orcs.\n\nFortunately, I kept a few extra rocket chickens to get us back to your garrison in style! Let's get up to the roof and find a decent place to take off.", objectives = "" }
WordHunterWoW_QuestEN[34079] = { title = "Mission Successful", description = "The Thunderlords are finished {name} and our job is complete. I'll stay here and watch over the area.\n\nYou should head back to Sergeant Gil'nath. I'm certain he will have another task for you.", objectives = "" }
WordHunterWoW_QuestEN[34087] = { title = "Through the Looking Glass", description = "An ally of yours, Thaelin, is helping us counter the Iron Horde.\n\nHe claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance.\n\nI do not trust such devices. Use it and let me know what you see.", objectives = "" }
WordHunterWoW_QuestEN[34088] = { title = "Too Many Irons in the Fire", description = "We must slay the Iron Horde troops who infest our lands.\n\nFind those who would sully our great forest and show them the hand of justice.", objectives = "" }
WordHunterWoW_QuestEN[34089] = { title = "In Short Supply", description = "The Iron Horde has explosive devices stored throughout the heart of their logging camp.\n\nWe must recover them so they are not used against us.\n\nI will keep an eye on Maraad... I worry for him in his anger.", objectives = "" }
WordHunterWoW_QuestEN[34090] = { title = "Thaelin's Quick Fix", description = "Those orcs sure like to pile things up in one place. That gave me an idea...\n\nI've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!", objectives = "" }
WordHunterWoW_QuestEN[34091] = { title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it out of the way until you've worked out the kinks.\n\nI will send Engineer Trak to work on it in the meantime.\n\n- Orgrim Doomhammer", objectives = "" }
WordHunterWoW_QuestEN[34092] = { title = "Desperate Measures", description = "We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly.\n\nThe cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding.\n\nPerform the ritual described within at their altar to lift their curse and seek their aid.\n\nIt's a long shot, but we don't have any other options.", objectives = "" }
WordHunterWoW_QuestEN[34093] = { title = "Getting the Points", description = "Those Thunderlords circling above us are a problem {name}.\n\nThey fly their pathetic Rylaks leisurely across the valley, thinking they are safe to rain spears down on our heads. We need to show them they are not safe from Frostwolf Vengeance!\n\nI have a plan but we will need to gather some material. Go hunt across the valley for any of their spears that survived intact. I think five should be enough.", objectives = "" }
WordHunterWoW_QuestEN[34094] = { title = "Vol. X Pages ?", description = "That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again.\n\nI coulda swore I saw a few of those pages floatin' about in  Archenon Siegeyard. Maybe the orcs there carry them.", objectives = "" }
WordHunterWoW_QuestEN[34095] = { title = "Iron Them Out", description = "The orcs themselves are not the only threat. They still have siege weapons of significant power.\n\nThey've already been used against Tuurem, and we must not allow for their continued operation.\n\nSabotage siege weapons using the explosives you collected from the logging camp.", objectives = "" }
WordHunterWoW_QuestEN[34096] = { title = "An Eye for a Spy", description = "I'll get the prototype shredder working right now!\n\nTake a look through my Observicopter. You'll see what you're about to head into...", objectives = "" }
WordHunterWoW_QuestEN[34097] = { title = "Born to Shred", description = "I've got this prototype shredder operating on most cylinders.\n\nBoy, will they be surprised when you stomp them with their own machine!\n\nCan't wait to watch you from the safety of the Observicopter.", objectives = "" }
WordHunterWoW_QuestEN[34098] = { title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", objectives = "" }
WordHunterWoW_QuestEN[34099] = { title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", objectives = "" }
WordHunterWoW_QuestEN[34102] = { title = "The Mark of Defiance", description = "As you look upon the Frostwolf banner you remember struggles that have led you and the Frostwolves to this point.\n\nRuk'gan has suffered in his battles with the Thunderlord and would appreciate an extra show of defiance. \n\nAs the banner rustles in the wind you're inspired to mark the foes of the Frostwolf with its standard.", objectives = "" }
WordHunterWoW_QuestEN[34103] = { title = "WANTED: Kil'uun", description = "I have a bounty set on a bird, commander. Yes, a bird.\n\nThe issue is this thing is massive, and it was last sighted a stone's throw away from the Horde base to the south in the forest. The locals call it Kil'uun.\n\nIf you'd like to track the creature down and bring back its beak I wager it would fetch a sack or two of gold for your coffers!", objectives = "" }
WordHunterWoW_QuestEN[34104] = { title = "WANTED: Hilaani", description = "O'riley wants to thank our peasants for their hard work with a riverbeast dinner.\nI don't want to waste your time asking you to slaughter the things all day, commander. We've gotten reports of a huge riverbeast called Hilaani that would feed the whole fort twice over living in the lake to the south.\n\nIf you have a chance to bring cuts of her meat back, the men would be grateful.", objectives = "" }
WordHunterWoW_QuestEN[34105] = { title = "WANTED: Ra'tok the Hammer", description = "I've got an issue that could use your assistance, commander.\n\nA few of our men spotted an Iron Horde lieutenant wandering in the cliffs near here. We suspect she's directing their forces to strategic ground as they land on the Orunai Coast.\n\nI would feel much better about the safety of this fort if you could take her out.", objectives = "" }
WordHunterWoW_QuestEN[34106] = { title = "WANTED: Ra'tok the Hammer", description = "The Iron Horde have no honor. They disgust me.\n\nWe spotted one of their lieutenants wandering the cliffs not far from our base. I believe that she is tracking our movements to prepare for some sort of assault from the Orunai Coast.\n\nI understand you have much to do, commander. If you have the time, I believe it would be beneficial to our position's integrity.", objectives = "" }
WordHunterWoW_QuestEN[34107] = { title = "WANTED: Hilaani", description = "We need more meat, commander.\n\nI know what you're thinking. What about all of that meat right behind me?\n\nThat's the problem. It'll be gone in a day if we're lucky.\n\nThere's a riverbeast that lives in the lake to the south. Locals call her Hilaani. Massive, lots of meat.\n\nIf you would take down the beast and bring me her meat, your wolves will be better off for it.", objectives = "" }
WordHunterWoW_QuestEN[34108] = { title = "WANTED: Kil'uun", description = "It's that damned bird!\n\nEvery few hours, this blasted thing flies right past here, and none of these idiots will stop it.\n\n\"It's got the crazy in its eyes,\" they tell me. Pah!\n\nCommander, this bird will be the end of me. If you see it, could you cut off its stupid head and give it to me?\n\nIt'd make me feel better.", objectives = "" }
WordHunterWoW_QuestEN[34122] = { title = "Ogre Diplomacy", description = "They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that.\n\nBy killing them.\n\nYou should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.", objectives = "" }
WordHunterWoW_QuestEN[34123] = { title = "To Thunder Pass", description = "There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass.\n\nI advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves.\n\nIt is time to show this Iron Horde what a united Frostwolf clan can do.", objectives = "" }
WordHunterWoW_QuestEN[34124] = { title = "The Battle of Thunder Pass", description = "The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak.\n\nDurotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of.\n\nHe will need your expertise.\n\nPlease, go to him.", objectives = "" }
WordHunterWoW_QuestEN[34144] = { title = "Retribution for the Light", description = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.\n\nYou have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", objectives = "" }
WordHunterWoW_QuestEN[34154] = { title = "Destination: Unknown", description = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them.\n\nI'll hold open the portal as long as I can. It will be up to you to strike the killing blow.\n\nOur fate is in your hands, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34157] = { title = "Into the Heart of Madness", description = "{name}, Nyami ran off to 'take down Teron'gor herself.'\n\nYou need to find her. She has no chance against him on her own.\n\nI must remain here and organize our ranks should another attack fall upon us. I'm counting on you.", objectives = "" }
WordHunterWoW_QuestEN[34163] = { title = "Hiding in the Shadows", description = "<The voice of Teron'gor enters your mind.>\n\nOur final move must remain concealed from the Auchenai, my minions. Use the shadow orbs Gul'dan provided for us to veil Gul'rok in darkness.\n\nPrepare our forces, we march on Auchindoun on my order. We will feast on the souls of the draenei and usher our demonic allies into this world!\n\n<Destroying these shadow orbs would help the defenders at Auchindoun greatly.>", objectives = "" }
WordHunterWoW_QuestEN[34164] = { title = "Book Burning", description = "Please, {name}... I don't have much time.\n\nThe Shadow Council have allowed themselves to be turned into demons by Teron'gor and his warlocks!\n\nI have reason to believe that the shadowborne dementors are using spells given to them by Gul'dan to empower the demonic orcs. Take their spellbooks and cast them into the fire by me... it will be a pleasant sight to die to.", objectives = "" }
WordHunterWoW_QuestEN[34192] = { title = "Things Are Not Goren Our Way", description = "The abandoned mine shaft has been overrun with goren!  They seem to be responding to commands from a big one farther down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those goren cleared out, we can get that mine up and working!", objectives = "" }
WordHunterWoW_QuestEN[34193] = { title = "Clearing the Garden", description = "This cave is the perfect climate to grow herbs for our Garrison, there is just one little problem.  All these damn nibblers!\n\nI need you to clear them out and we can get this garden growing.", objectives = "" }
WordHunterWoW_QuestEN[34194] = { title = "Looking For Help", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Head northwest and see if you can find anyone on the shoreline.", objectives = "" }
WordHunterWoW_QuestEN[34209] = { title = "Vouchsafe Our Arrival", description = "A matter of great importance has arisen. While you were away, Archmage Khadgar contacted me.\n\nHe is investigating demonic influences to the north.\n\nBeing a human, the Frostwolves will not accept Khadgar without you there to vouch for him, nor will they accept a night elf such as myself.\n\nI will wait for you outside Throm'var in the Frostwind Crag.", objectives = "" }
WordHunterWoW_QuestEN[34213] = { title = "They Have My Son", description = "Please, {name}! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde.\n\nHe has my son!\n\nHe made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process.\n\nCan you go to Gron'mar for me and rescue my son?\n\nHis name is Corki.", objectives = "" }
WordHunterWoW_QuestEN[34216] = { title = "Safe Passage", description = "Being a human and a night elf, the archmage and I aren't likely to be well-received by the orcs of the Frostwolf clan.\n\nWe need you to make an introduction for us with the Throm'var farseer.\n\nThere is much to discuss. Shall I bring you up to speed on the way to the village?", objectives = "" }
WordHunterWoW_QuestEN[34217] = { title = "Smash Blon'sky!", description = "Grulk not choose to be mutated. Grulk not monster like Blon'sky! Blon'sky evil... chose mutation for power!\n\nYou go to Grommar? Smash Blon'sky before he hurt innocents, make Grulk happy!", objectives = "" }
WordHunterWoW_QuestEN[34227] = { title = "What Must Be Done", description = "I believe we have seen this demonic corruption your friends speak of.\n\nThe Mother of Wolves has not been herself lately. Now, her pack has her surrounded.\n\nThe wolves are protecting our hunters and will not let them near. They're not likely to stop you, though.\n\nIf the alpha mother is infected with this fel-energy, then she must be put down.\n\nYou would greatly honor the Frostwolves by returning with her corpse and giving it a proper burial.", objectives = "" }
WordHunterWoW_QuestEN[34228] = { title = "A Clew of Worms", description = "While I was scouting, I noticed that most of Frostwind Crag is crawling with an odd species of worm.\n\nThe worst thing about them is that these things burrow under the ground and then spring on you from out of nowhere.\n\nI saw the worms attacking the frost wolves and other wildlife in the wastes. I'm certain the orcs would appreciate you helping out.", objectives = "" }
WordHunterWoW_QuestEN[34229] = { title = "The Sleeper Has Awakened", description = "Something has awakened the great Shui Halad. She is causing the ground to quake.\n\n<The farseer makes a sign of warding in the air, and then continues.>\n\nPerhaps those who have disturbed the great worm are the same ones your friends are tracking down?\n\nEither way, Shui Halad must be put to eternal rest before her thrashing collapses all of the north into the ocean.", objectives = "" }
WordHunterWoW_QuestEN[34230] = { title = "Eye Need That", description = "The Mother of Wolves was infected with demon magic. The Shadow Council must have hoped to spread the corruption to the other frost wolves and then to Throm'var.\n\nThe hunters are reporting they've seen glowing green eyes down in the Icescar Boneyard to the west. We both know what that means.\n\nI have an idea... we're going to use the Shadow Council's \"eyes\" against them to reveal their base. All we need is the lead warlock's All-Seeing Ring.", objectives = "" }
WordHunterWoW_QuestEN[34234] = { title = "Payback", description = "We thought we were safe behind Leafshadow's cloaking veil.\n\n<Vindicator Kaluud wipes the blood from his face.>\n\nSomeone told the Shadow Council's forces how to disable it. We were able to hold them off at first...\n\nMost of the town was slaughtered in the attack. Please, you must avenge our fallen. Rout these invaders out from Telmor forever!", objectives = "" }
WordHunterWoW_QuestEN[34240] = { title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. As you know, there may be Shadow Council forces anywhere around Auchindoun, including near Telmor.\n\nTuulani's powers as a soulpriest have not yet fully manifested; she isn't capable of protecting the shard alone. I need you to join her at Telmor to make sure the crystal makes it to Auchindoun safely.", objectives = "" }
WordHunterWoW_QuestEN[34242] = { title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. There may be Shadow Council forces all around Auchindoun, including near Telmor.\n\nI want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.", objectives = "" }
WordHunterWoW_QuestEN[34245] = { title = "Demonic Barrier", description = "If I am reading this correctly, there might be a way to use the power of Draenor to effectively purge a demon.\n\nAccording to my father's notes, a place of snow and earth is required for the ritual. He will also need an untapped ley line to power the ritual.\n\nThere is a cave in northern Frostfire Ridge  whose power might suffice. I will mark it on your map. Head north as soon as you can and I will join you there.", objectives = "" }
WordHunterWoW_QuestEN[34246] = { title = "Break The Seals", description = "Curses! I cannot cross these wards. They specifically are designed to keep my bloodline out.\n\nHowever, I could give you a blessing so that you may pass through the outer layer of these wards. You could enter this cave and destroy the runes within that these barriers are drawing their power from.\n\nProceed with caution, for I suspect these barriers are not the only dangers we will face.", objectives = "" }
WordHunterWoW_QuestEN[34247] = { title = "To Cleanse an Eredar", description = "It... it is my mother! She is an eredar? How? When? To join the ranks of the Legion is the greatest evil our people can commit.\n\nMy father's ritual is breaking. He isn't strong enough to defeat her by himself. We need to act now!", objectives = "" }
WordHunterWoW_QuestEN[34264] = { title = "A Collection of Coils", description = "None of the Thunderlord can escape my wrath! We need something to pull them out of the skies so that they can greet our blades.\n\nTheir wranglers should carry rope with them for handling their beasts. Slay them, if they have any coils in good condition bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[34271] = { title = "The Fate of Gordawg", description = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements.\n\nGordawg stands before us enthralled; a slave to the pale and their mysterious master. My heart is heavy with grief to see such a great creature mindless and enslaved by evil.\n\nThere is no going back, in order to push forward you must go through Gordawg.\n\nIt pains me, but Gordawg must be slain.\n\nWhen the deed is done, we will return the fury's heart to the Throne of Elements.", objectives = "" }
WordHunterWoW_QuestEN[34277] = { title = "Stop the Flow", description = "The Shadow Council down in the boneyard are going to have magic circles. It's not enough to simply kill them; we also have to eliminate their infernal devices.\n\nIf you destroy the circles, you'll stop the flow of demons they're summoning to inhabit the bones of the dead.", objectives = "" }
WordHunterWoW_QuestEN[34278] = { title = "Desecration of the Dead", description = "These filthy warlocks are desecrating the dead in the boneyard!\n\n<The farseer trembles as he fails to keep his composure.>\n\nI WANT THEM DEAD!\n\nDestroy the necrophytes. Destroy their demonic abominations.", objectives = "" }
WordHunterWoW_QuestEN[34279] = { title = "I Am Blook", description = "", objectives = "" }
WordHunterWoW_QuestEN[34280] = { title = "All is Revealed", description = "Tell me when you're ready.\n\nWe'll invoke the power of the ring to summon one of their 'eyes.' Through it, we'll discover where the Shadow Council is located and what they're really up to.", objectives = "" }
WordHunterWoW_QuestEN[34281] = { title = "Out of the Chains", description = "They roughed me up real good an' I have a splitting headache but I'll survive. I need to get out of this bit o' chain here though.\n\nCould ye get the key to it for me? A big ogre called Nub has it, he's over on the far side of the terrace.", objectives = "" }
WordHunterWoW_QuestEN[34284] = { title = "Garrison Campaign: The Search for Owynn Graddock", description = "Commander, I have bad news to report.\n\nAgent Graddock was out on assignment to keep an eye on the Bloodmaul and he missed his deadline to check back in.\n\nSomething's not right, {name}.\n\nIf Owynn was captured they may have locked him away with their slaves.\n\nHead over to Stonefury Cliffs and see if you can locate him.", objectives = "" }
WordHunterWoW_QuestEN[34285] = { title = "Gearing Up", description = "When I was captured they took my gear and left me in rags. My mace is being used to crack stones and they're even using me best dagger as a dinner fork! I'd hate to know what happened to me armor but I hope its still usable.\n\nI'll need a wee bit to recover from me wounds and without my stuff I'm no help in a fight. Could ye go find my gear for me?\n\nLast I saw my armors in a chest next to that big tower south of here, my dagger was to the south west, and my mace over near that lava field to the west.", objectives = "" }
WordHunterWoW_QuestEN[34286] = { title = "Seeking the Truth", description = "Okay, now down to business.\n\nThe Bloodmaul have unearthed some monstrous artifact I've heard them call the Soulgrinder. It's a nasty bit o' sorcery that their chief uses to give himself incredible magical power, but it comes at the cost of needing to feed upon souls to maintain it. Every day, more and more corpses pile up from the slaves killed to maintain it.\n\nWe need to go find Borgal and get rid of this Soulgrinder!", objectives = "" }
WordHunterWoW_QuestEN[34287] = { title = "Cleansing the Souls", description = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened.\n\nEnd their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", objectives = "" }
WordHunterWoW_QuestEN[34288] = { title = "The Totems That Bind", description = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service.\n\nIf we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us!\n\nGo find me a few of those totems and I might be able to pull this off, I think five should do it.", objectives = "" }
WordHunterWoW_QuestEN[34289] = { title = "Soulgrinder Survivor", description = "It is time for Borgal to die.\n\nWe must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us.\n\nYour job will be the difficult one, kill him!", objectives = "" }
WordHunterWoW_QuestEN[34291] = { title = "Have a Heart", description = "Did you notice the magical barrier protecting the cave's entrance? It's being powered by demon crystals.\n\nThe Burning Legion has a habit of making demon parts serve as the keys to such devices.\n\nTravel west to the Ruins of Ata'gar. Look for a powerful demon therein and bring me its heart.\n\nI'll project an image of myself into the ruins. You won't have to come back here until we're done.", objectives = "" }
WordHunterWoW_QuestEN[34292] = { title = "Eliminate the Shadow Council", description = "Those ruins are going to be full of Shadow Council flunkies. We can't afford to let them scatter all over Draenor once you've dealt with Gul'dan.\n\nNo, we need to eliminate every one of them down to the last orc.", objectives = "" }
WordHunterWoW_QuestEN[34293] = { title = "Eliminate the Shadow Council", description = "These ruins are full of Shadow Council adherents. We can't afford to let them scatter all over Draenor once Gul'dan has been dealt with.\n\nNo, we need to eliminate every one of them down to the last orc.", objectives = "" }
WordHunterWoW_QuestEN[34294] = { title = "The Fel Crystals", description = "You have the key. Now use it to destroy the fel crystals.\n\nOnce they are eliminated, the magical barrier blocking the entrance to the Gloomspire will come down.\n\nAnd once the barrier is down, you'll go inside to confront Gul'dan.", objectives = "" }
WordHunterWoW_QuestEN[34295] = { title = "To Capture Gul'dan", description = "Gul'dan is in the cave further into the Gloomspire.\n\nWe know that he's about to leave for Talador and Shadowmoon Valley. You must capture him by any means necessary, {name}.\n\nI'll see you back at Throm'var. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[34309] = { title = "Garrison Campaign: The Search for Shadow Hunter Bwu'ja", description = "It be a long time since we hear from Shadow Hunter Bwu'ja, commander. \n\nLast we know she be on assignment keeping an eye on dem Bloodmaul ogres up in Frostfire.\n\nDem ogres just be a bunch a slavers so something really big must be happening ta keep her from reporting in.\n\nGo over ta de Stonefury Cliffs an' find her.", objectives = "" }
WordHunterWoW_QuestEN[34314] = { title = "Out of the Chains", description = "Lissen mon, dem ogres, got da jump on me wid an artifact wid powerful mojo. Next t'ing I know I wake here wid broken bones an' dis chain on me leg. I called to da spirits ta break it, but da spirits here no answer.\n\nGotta go wid da old methods ta get out. Dere be a big ogre in da cave here called Rugrum who has da key to me shackle. Could ye go put a blade in his belly and get me dat key?", objectives = "" }
WordHunterWoW_QuestEN[34315] = { title = "Gearing Up", description = "Dem ogres whipped me real good. My arm be broke, a few ribs snapped, t'ink even me spleen be hurtin' from dat beatin'. Nothin' a troll can't handle though but I be needin' a moment ta recover.\n\nWhat I really be needin' is me gear dem ogres took from me. Dey got me garb in a chest near a hut to da south, me glave in a chest next to da tower wid da Bonecrushers, dey even got me mask, it over near da lava! Could ye go find dem while I take a breather?", objectives = "" }
WordHunterWoW_QuestEN[34316] = { title = "Seeking the Truth", description = "Lissen mon, a few nights ago dem ogres found a bit o' old and powerful mojo.\n\nI was snooping around da cave across de lava flows when dere was a huge scream from da spirit world. I went in and saw Borgal, de ogre chief, he be draining da spirits from de slaves wid some big stone wheel dat I heard dem call de Soulgrinder. I tried ta take 'em out but a single shot from dat thing took all de strength from me.\n\nDat mojo too much of a threat in de hands of dem ogres.", objectives = "" }
WordHunterWoW_QuestEN[34318] = { title = "The Totems That Bind", description = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service.\n\nIf we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us!\n\nGo find me a few of those totems and I might be able to pull this off, I think five should do it.", objectives = "" }
WordHunterWoW_QuestEN[34319] = { title = "Soulgrinder Survivor", description = "It is time for Borgal to die.\n\nWe must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us.\n\nYour job will be the difficult one, kill him!", objectives = "" }
WordHunterWoW_QuestEN[34321] = { title = "Ashes Of The Past", description = "The ogres are a plague upon my kind. They summon my kin and force them into servitude, working them without rest till their heat fades away and they crumble into dust.\n\nTheir ashes must return to the lava flows so that they can be reborn!\n\nThe Ogres keep the dust in pouches on their person thinking it would enhance their strength. Go slay them and recover the ashes of my people!", objectives = "" }
WordHunterWoW_QuestEN[34325] = { title = "Flames Of The Earth", description = "I've searched the depths of the earth and found the means to break the spells that hold my people captive, but it only functions to free one who is completely bound. I would be unable to prevent myself from becoming bound by the same magic.\n\nYou, flesh creature, are not of the flames below so their binding spells should not affect you.\n\nPlease take my jewel, use its power to free my people!", objectives = "" }
WordHunterWoW_QuestEN[34326] = { title = "Changing the Tide", description = "It is time to retaliate against this foe. Meet me at Retribution Point and we will take this fight to the Shadow Council.\n\nTeron'gor shall not feast on another soul so long as we stand in his way! His reign of terror ends today.", objectives = "" }
WordHunterWoW_QuestEN[34335] = { title = "Garrison Campaign: Crows In The Field", description = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand.\n\nWe've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond.\n\nWe have reason to believe that these orcs are pursuing a valuable artifact deep in the desert.\n\nI'm putting together a small mission for a focused, surgical strike, and we could use a capable {class} like yourself. I'd like you to be part of that team.", objectives = "" }
WordHunterWoW_QuestEN[34336] = { title = "Ambushing the Enemy", description = "See that Iron Horde camp to the south, across the water? We've been watching their movements for days.\n\nWe've seen a lot of correspondence between their lieutenant and the Iron Horde command in Nagrand.\n\nWe need to disrupt their operation.\n\nGather their supplies, and bring me their leader's head.", objectives = "" }
WordHunterWoW_QuestEN[34337] = { title = "The Giant Cauldron", description = "A high value artifact at Cragplume Canyon, hmmm?\n\nLet's see if we can't beat the Iron Horde to it.\n\nLet's move fast. Speak to Choluna, and we'll be on our way.", objectives = "" }
WordHunterWoW_QuestEN[34338] = { title = "The Descent", description = "Whatever lies at the bottom of this cauldron is of great use to the Iron Horde, and therefore, of great interest to us.\n\nI need you to investigate the bottom of this crater.\n\nYou go ahead. I'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[34339] = { title = "A Goren's Feast", description = "Goren. This caldera is full of them. I can even smell their stench from here.\n\nI suspect that these goren are more than just primitive beasts, but in order to prove my theories, I need more data.\n\nDuring your mission, if you should slay a goren or two, would you examine their stomachs for me? I'd like to know what these curious creatures eat.", objectives = "" }
WordHunterWoW_QuestEN[34340] = { title = "Heating Up", description = "Greetings, {name}. I have been conducting research on the steam geysers of Gorgrond for some time now.\n\nCragplume Cauldron is one of the largest caldera in this region, but we have been unable to do a geographical survey due to the dangerous creatures in this area.\n\nSince you are venturing into the depths, could you take a temperature reading for me?\n\nIt would add greatly to our understanding of these natural caverns.", objectives = "" }
WordHunterWoW_QuestEN[34341] = { title = "The Beating Heart", description = "One thing is certain. We now possess an item of great value to the Iron Horde.\n\nWe had better secure this... \"Heart of Gorgorek\" at once.", objectives = "" }
WordHunterWoW_QuestEN[34344] = { title = "Lurkers", description = "Dis be a dangerous place, boss-mon.\n\nFilled with big monsters and savage giants.\n\nWell, like my family loa say, 'If ya can't beat it, poison it.'\n\nWe gonna be needin' some venom from the lurkers out there on the Cracking Plains. Dem lurkers be mighty sneaky, and mighty creepy. Be watchin the ground for rumbles and shakes.\n\nI'll be stayin' here to make a cure in case you accidentally get too poisoned.", objectives = "" }
WordHunterWoW_QuestEN[34345] = { title = "Poulticide", description = "We be huntin' something so big, so savage, we gonna need anotha poison. We gonna need a big ol' poultice of poison!\n\nSo...  boss-mon? Ya think ya up for a little flower pickin'? We gonna need the leaves of them frostbloom plants that be growing along the shadows of rocks and ledges along the sides of the Cracking Plains.\n\nBe careful when pickin' them,  boss-mon! They not always be by themselves...", objectives = "" }
WordHunterWoW_QuestEN[34346] = { title = "Frosted Fury", description = "The furies of Draenor are different than the elementals of Azeroth. But don't be fooled. Some be wicked, boss-mon. Wicked.\n\nThe trap we are making be needing some proper frostshards. You can get them, if ya willing, from the ice furies.\n\nDey be wandering the Cracking Plains, freezin' all dat dey touch, an' bein' wicked.\n\nBring us some o' these frostshards,  boss-mon, an' we gonna whip ya up one deadly trap.", objectives = "" }
WordHunterWoW_QuestEN[34347] = { title = "Bladefury's Orders", description = "Lieutenant O'rok:\n\nSend an elite strike team to Cragplume Cauldron.\n\nRetrieve a high-value artifact from the crater and deliver it to my command post in northern Talador.\n\nWith your remaining forces, go to Gorgorek's Fall. Protect and prepare the ancient magnaron specimen for retrieval.\n\nImmediate action is required.\n\n- Bladefury", objectives = "" }
WordHunterWoW_QuestEN[34348] = { title = "The Real Prey", description = "Eh boss-mon. Time for us to be huntin' the real prey now. To the north, there be a cave. In the cave, there be right mean ogron dey call \"Grosh the Mighty.\" That ogron got a big stash of pillaged hides and leathers we gonna be needin' for the troops at the garrison.\n\nI made a special poison from the stuff ya gathered. Dis be a magic poison, and it gonna put that ogron down to sometin' a bit more manageable. \n\nTake these vials to the cave and see if ya can't win us a treasure.", objectives = "" }
WordHunterWoW_QuestEN[34351] = { title = "We Must Construct Additional Pylons", description = "We came here to retrieve a reserve pylon to power Auchindoun's defenses, but we've been pinned to this position by the Shadow Council for hours!\n\nI need to get these injured back to Exarch's Refuge, but we still need the backup system!\n\nPlease, gather Arkonite crystals and an Arkonite pylon from the tomb and meet me at the refuge as quickly as you can!", objectives = "" }
WordHunterWoW_QuestEN[34352] = { title = "Darktide Defender", description = "<Rexxar looks at you as you inspect the dead goblin. It's clear what he wants you to do.>", objectives = "" }
WordHunterWoW_QuestEN[34353] = { title = "Shredder Suppressor", description = "The rylaks have no defense against the Iron Horde's technology. A true hunter would not need machines to capture their prey.\n\nDestroy the Iron Shredders and the scum that pilot them. Spirit will join you on your quest.", objectives = "" }
WordHunterWoW_QuestEN[34354] = { title = "A Good Death", description = "These fools have no honor.\n\nThey seem to enjoy torturing these poor beasts. The only humane thing we can do at this point is find injured rylaks and put them out of their misery.\n\nTake this axe and aim for their vitals, {name}.  These rylaks deserve a good death.", objectives = "" }
WordHunterWoW_QuestEN[34355] = { title = "Dirty Rats", description = "These shredders are more of a hassle than I expected.\n\nI've been peering through the eyes of the rats on the island. There are number of unmanned shredders west of here.\n\nThe rats have an uncontrollable appetite for this bait. Throw it onto Unmanned Shredders and let the rats destroy them from the inside.", objectives = "" }
WordHunterWoW_QuestEN[34362] = { title = "The Shadow Gate", description = "Okay, we're gonna have to be quick. \n\nI've seen Borgal form magical portals before so he might try to use one to escape. If he does that our only option will be to follow after 'em. On top of that he always keeps his lieutenant Grubnor nearby so we may have a bit of a tussle in store.\n\n<Owynn peeks into the cave.>\n\nKeep yer head down, something's going on in there.", objectives = "" }
WordHunterWoW_QuestEN[34364] = { title = "For the Horde!", description = "Without you, none of us would have made it to the shores of my homeland. You will be the one to lead our forces here on Draenor. This is your garrison to found.\n\nI leave it to you to plant the banner and claim this territory. When you are ready, I will have Khadgar open a portal to bring through a few necessary reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[34365] = { title = "Releasing Rylak", description = "These goblins have been conducting horrible experiments on the rylaks. This fool gave me the location for three of their prized experiments.\n\nSet these mutated rylaks free. Maybe freedom will help these tortured souls find some peace in life.", objectives = "" }
WordHunterWoW_QuestEN[34375] = { title = "Back to Work", description = "Alright, boss. We're gonna need some lumber if we're gonna get this garrison started off right.\n\nIf you mark some trees to be cut down, your peons will do the rest.", objectives = "" }
WordHunterWoW_QuestEN[34378] = { title = "Establish Your Garrison", description = "It's time for the main event! We've got the materials, we've got the manpower, we've got another thing that starts with \"m.\"\n\nLet's build this thing!\n\nI got a gaggle of assistants up on that ridge to the west.\n\nThey should have your personal surveying stand set up by now.\n\nHead on over there and you should be able to watch our progress from it.", objectives = "" }
WordHunterWoW_QuestEN[34379] = { title = "Den of Wolves", description = "Durotan wishes for us to join him now that you have established your foothold. I hope he will accept your help.", objectives = "" }
WordHunterWoW_QuestEN[34380] = { title = "Rally the Frostwolves", description = "My brother, in his haste, has already taken some of my clan with him and has begun an assault on Bladespire Citadel before we were ready.\n\nDraka awaits by our war horn. Please let her know that it is time to rally the clan!\n\nWith the aid of you and your forces, we might actually stand a chance at victory against the ogres.", objectives = "" }
WordHunterWoW_QuestEN[34381] = { title = "The Shadow Gate", description = "Dere be ogres in da cave, I smell de stink of 'em.\n\nKeep ye weapon handy, we gonna have ta move quick and take down de ogres before dey start tossing da mojo.\n\n<Bwu'ja peeks into the cave.>\n\nWatch ye self mon, something be going down in dere.", objectives = "" }
WordHunterWoW_QuestEN[34392] = { title = "Onslaught's End", description = "\"Guard Gul'dan and his Shadow Council with your lives! The portal cannot function without our prisoners' fel magic. Fail me and watch all that you hold dear turn to ash.\n\n-Grommash Hellscream.\"\n\nThe Iron Horde appear to be holding prisoners that are crucial to keeping the portal open. Search the nearby spires!", objectives = "" }
WordHunterWoW_QuestEN[34393] = { title = "The Portal's Power", description = "This portal is fueled by powers neither mechanical nor arcane.\n\nLook to either side of us, {name}. The screaming souls of slain prisoners are being channeled into the heart of the portal itself.\n\nAnd they are channeling these souls through the body of Gul'dan.\n\nFind a way into the chamber beneath us, and do whatever it takes to get Gul'dan to stop his channeling. Our last hope rests on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34397] = { title = "Downsizing the Darktide", description = "This pathetic excuse for life sold out all of his companions. All it took was a little squeeze of the neck.\n\nFind the leaders of this operation and bring me their heads. Haratha will accompany you on your quest.", objectives = "" }
WordHunterWoW_QuestEN[34398] = { title = "Warlords of Draenor: The Dark Portal", description = "\n             ATTENTION HEROES\n                 ADVENTURERS\n        DEFENDERS OF AZEROTH\n\nArchmage Khadgar, hero of the Second War, is assembling a coalition of Azeroth's strongest to bravely step through the Dark Portal and stop the Iron Horde's invasion of Azeroth.\n\nChampions who are interested in glory can meet Khadgar at the base of the Dark Portal in Blasted Lands.\n\nSafety not guaranteed.", objectives = "" }
WordHunterWoW_QuestEN[34399] = { title = "Trouble In The Mine", description = "The Jorune Mine is in trouble!\n\nWe recently unearthed an exceedingly large and powerful arcane crystal; however, something has gone terribly wrong and the energy from the crystal is flooding the mine.\n\nThe Auchenai have already sent their Vindicators into the mine to assist us.\n\nSpeak with Vindicator Doruu inside of the mine, he'll know how you can help.", objectives = "" }
WordHunterWoW_QuestEN[34400] = { title = "Frenzied Manafeeders", description = "There is a rare breed of moth in Talador known as the Manafeeder. These moths sustain themselves by feeding on arcane crystal dust from the mine.\n\nTypically speaking, these moths are nothing more than an occasional nuisance. However, they are now gorging themselves upon the intense arcane energy flooding out of the mine and have become highly territorial and aggressive.\n\nI have attuned this crystal to disperse arcane energy. Please use it on the Frenzied Manafeeders to soothe them.", objectives = "" }
WordHunterWoW_QuestEN[34401] = { title = "Arcane Essence", description = "Kaelynara will not stop until she has drained every last drop of arcane energy from the crystal...and destroyed this entire mine in the process. The arcane shield she guards herself with cannot be penetrated by normal means, but I have a plan.\n\nIf I had a focusing crystal powerful enough to momentarily pierce her shield, Kaelynara could then be dealt with.\n\nFortunately, we are in the perfect place to build one. Start by bringing me arcane essence from the creatures rampaging throughout the mine.", objectives = "" }
WordHunterWoW_QuestEN[34402] = { title = "Of Wolves and Warriors", description = "The return of many of my people is a boon to us, and I thank you for your part in their survival.\n\nCome, ride with me. We have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[34403] = { title = "Arcane Essence", description = "Kaelynara's lust for arcane power has consumed her and she threatens the safety of all in this mine. She must be stopped.\n\nUnfortunately, there is nothing we can do while she shields herself. We will need to find a way to penetrate her shielding spell.\n\nPerhaps if I were to build a focusing crystal, I could use it to lower her shield...I'll need you to search the crystal mine for the necessary components.\n\nFirst, I'll need arcane essence from the Crystal Ragers and Arcane Wraiths in the mine.", objectives = "" }
WordHunterWoW_QuestEN[34404] = { title = "Crystals of Unusual Power", description = "Arcane crystals of this size and power are quite rare even on Draenor. It is no coincidence that the Draenei built Shattrath and Auchindoun so close to this mine.\n\nI am interested in learning more about these particular crystals and their arcane nature.\n\nReturn to me with any unrefined power crystals that you may find and I will make sure that you are adequately compensated for your effort.", objectives = "" }
WordHunterWoW_QuestEN[34406] = { title = "Caught In The Chaos", description = "Not all of the Draenei miners made it out when the chaos erupted, {name}. Many of them are injured and still trapped inside the mine.\n\nKaelynara's disruption has caused all hell to break loose. Arcane Wraiths are forming from the unleashed energy and attacking everything they see. The elementals that slumbered beneath the ground are emerging from the rocks frenzied and dangerous.\n\nPlease find as many injured miners as you can and ensure that they return safely.", objectives = "" }
WordHunterWoW_QuestEN[34407] = { title = "Holding the Line", description = "It is good to see you again, champion.\n\nDemons are assaulting Auchindoun and we are barely standing our ground against them.\n\nWe need to push our front lines forward lest our losses reach critical mass.\n\nIf your blade is with us, shove it into these foul creatures' throats.", objectives = "" }
WordHunterWoW_QuestEN[34409] = { title = "Garrison Campaign: Crows In The Field", description = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand.\n\nWe've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond.\n\nWe have reason to believe that these orcs are pursuing a valuable artifact deep in the desert.\n\nI'm putting together a small mission for a focused, surgical strike. I'd like you to be part of that team.", objectives = "" }
WordHunterWoW_QuestEN[34410] = { title = "The Beating Heart", description = "One thing is certain. We now possess an item of great value to the Iron Horde.\n\nWe had better secure this... \"Heart of Gorgorek\" at once.", objectives = "" }
WordHunterWoW_QuestEN[34413] = { title = "Lumberstruck", description = "[Test Quest - Do Not Translate]\n\nThis box is empty, begging to be filled with wood.\n\nProtect your peasants as they gather materials from the region.", objectives = "" }
WordHunterWoW_QuestEN[34414] = { title = "An'dure The Giant", description = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality.\n\nWithin the mine is a crystal giant known to the Draenei as An'dure. The giant has slept beneath the rocky earth for ages, but due to Kaelynara's recklessness it has awakened.\n\nThe heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart. Once I have the heart, I will have everything I need to construct the focusing crystal!", objectives = "" }
WordHunterWoW_QuestEN[34415] = { title = "An'dure The Giant", description = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality.\n\nWithin the mine is a crystal giant known to the Draenei as An'dure. The giant has slept far beneath the earth for ages, but due to Kaelynara's recklessness it has awakened.\n\nThe heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart.\n\nWhen you return I will construct the focusing crystal and together we will stop Kaelynara.", objectives = "" }
WordHunterWoW_QuestEN[34418] = { title = "Holding the Line", description = "Auchindoun is under attack!\n\nThe Auchenai are valiant warriors in their own right, but they cannot hold against these endless demon hordes alone. We came here to stop the Legion from engulfing Draenor... working together is our best shot.\n\nI need you to thin out the demons' numbers so we can regroup our forces safely and push forward into the Burning Front.\n\nWe will stop their march here and now!", objectives = "" }
WordHunterWoW_QuestEN[34420] = { title = "The Cost of War", description = "They called this operation a suicide mission, but I don't plan on throwing away any lives meaninglessly.\n\nEverybody, with me!", objectives = "" }
WordHunterWoW_QuestEN[34421] = { title = "Bled Dry", description = "<The orc spits out his last words.>\n\nThey kept us in cages. They... drain our blood, for... rituals...\n\n<The Frostwolf coughs violently.>\n\n...many left --\n\n    -- my... people...\n\n<The orc dies.>", objectives = "" }
WordHunterWoW_QuestEN[34422] = { title = "Blaze of Glory", description = "We can't stay here forever. We NEED to keep moving. But first - we need a distraction.\n\n<Khadgar conjures a small gem.>\n\nThis bead should burn anything flammable that you get close to. With your skill, and a bit of luck, you might be able to take the attention of the Bleeding Hollow orcs off our group.", objectives = "" }
WordHunterWoW_QuestEN[34423] = { title = "Altar Altercation", description = "You see that altar down there? There's a magical eye settled at its peak, and I fear our group will not survive if it sees us.\n\nDistract the eye, {name}. Cause a commotion, kill some ritualists, whatever you have to do - just occupy that thing long enough for me to guide the rest of our group past its gaze.\n\n<Khadgar looks over his shoulder.>\n\nBring that strapping orc with you. The one that's not Thrall.", objectives = "" }
WordHunterWoW_QuestEN[34425] = { title = "The Kargathar Proving Grounds", description = "The orcs in this area look like members of the Shattered Hand clan. You can tell by looking at their hands.\n\nLet's join up with the others. We must find a way out of here.", objectives = "" }
WordHunterWoW_QuestEN[34427] = { title = "A Potential Ally", description = "One of the captured orcs is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the amusement of his captors.\n\nUse this runestone. It should handily deal with the ring of fire that surrounds him.", objectives = "" }
WordHunterWoW_QuestEN[34429] = { title = "Kill Your Hundred", description = "I see only one way out of this trap, {name}, and it's right through the middle of that arena.\n\nThis might be the end of us.", objectives = "" }
WordHunterWoW_QuestEN[34431] = { title = "Masters of Shadow", description = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding.\n\nAll of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me.\n\n<Luuka takes a deep breath.>\n\nUngra, Gurran, and... umm... oh! Ankova.\n\nWill you protect me from them?", objectives = "" }
WordHunterWoW_QuestEN[34432] = { title = "The Shadowmoon Clan", description = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34434] = { title = "Yrel", description = "Forgive me if I'm a bit flustered - I've never killed anyone before.\n\nMy name is Yrel, and I am a student of Karabor.\n\nYou say you have an ARMY with you? The Light must truly be watching over me today.\n\nI will follow you, then. Lead the way, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34436] = { title = "Keli'dan the Breaker", description = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him.\n\nI will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", objectives = "" }
WordHunterWoW_QuestEN[34437] = { title = "The Prodigal Frostwolf", description = "I can get back to Drek'Thar myself... after I run this stinking shovel through a few Blackrock stomachs.", objectives = "" }
WordHunterWoW_QuestEN[34439] = { title = "The Battle of the Forge", description = "Our troops are armed - the time to strike is now!\n\nStrike swift and true, {name}!", objectives = "" }
WordHunterWoW_QuestEN[34442] = { title = "Ga'nar of the Frostwolf", description = "We must move on, there isn't time to waste!\n\nOne of the elders of my clan, Ga'nar, is out there somewhere. I can sense him, but I cannot find him.\n\nKeep an eye out for Ga'nar. He is a strong-willed orc, and will languish in captivity.", objectives = "" }
WordHunterWoW_QuestEN[34445] = { title = "A Taste of Iron", description = "The way I see it, there's two ways to keep this tank from going through the portal: break the tank, or USE the dang tank ta' BLOW UP the dang portal.\n\nI can get 'er workin', I just need time. Hop in that turret off the starboard bow and keep 'em off my back.", objectives = "" }
WordHunterWoW_QuestEN[34446] = { title = "The Home Stretch", description = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank!\n\nLet's join up with the rest and get out of here!!", objectives = "" }
WordHunterWoW_QuestEN[34447] = { title = "Kaelynara Sunchaser", description = "The focusing crystal is complete, {name}. When you are ready I will use the crystal to shatter Kaelynara's shield.\n\nHowever, it is unsafe to confront her within the mine. The moment her shield is down I will teleport us to a safe location outside of the Jorune Mine. She will be much easier to deal with when she is far away from the crystal.\n\nSpeak with me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[34448] = { title = "Kaelynara Sunchaser", description = "The focusing crystal is complete, {name}. When you are ready I will use the crystal to shatter Kaelynara's shield.\n\nHowever, it is unsafe to confront her within the mine. The moment her shield is down I will teleport us to a safe location outside of the Jorune Mine. She will be much easier to deal with when she is far away from the crystal.\n\nSpeak with me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[34450] = { title = "Rylak Rescue", description = "I managed to squeeze even more information out of our little friend here.\n\nThe Darktide Matriarch is at the top of the hill.\n\nOne of their lead engineers is attempting to tame the matriarch with his technology. We must stop him, {name}.", objectives = "" }
WordHunterWoW_QuestEN[34451] = { title = "Sunsworn Camp", description = "We no longer have a need to work alongside the Auchenai, champion. I have arranged for their lead soulbinders to continue to advise us, but I believe any action is best left to us at this point.\n\nMeet me at Sunsworn Camp, southeast of here. I can sense more demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", objectives = "" }
WordHunterWoW_QuestEN[34452] = { title = "Light's Rest", description = "With the brute force of our enemy neutralized, we must turn our sights on quelling the aftermath and preparing for any future assaults. We still need Auchindoun's defenses reinvigorated.\n\nMeet me at Light's Rest, not far south of here. We have reports coming in of demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", objectives = "" }
WordHunterWoW_QuestEN[34455] = { title = "Free their Minds", description = "This device is what the goblins are using to control the rylaks.\n\nThere is a button on the controller labeled do not touch.\n\nGet within range of a Controlled Rylak and touch the button.", objectives = "" }
WordHunterWoW_QuestEN[34458] = { title = "Powering the Defenses", description = "What few soulpriests we don't have on the front lines are working fervently to maintain Auchindoun's defenses. They aren't going to be able to keep it up much longer alone.\n\nSoulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. I need you to find her and get her and the pylon back here safely.", objectives = "" }
WordHunterWoW_QuestEN[34461] = { title = "Build Your Barracks", description = "You are going to want to build your barracks, which you're gonna need to properly bash faces.\n\nThe first step is to go find the blueprints and learn 'em. I think I left some blueprints lying around here somewhere.\n\nNext ya gotta pick which plot you want us to build it on. Just point it out on my architect table and we'll get started constructing that thing right away.", objectives = "" }
WordHunterWoW_QuestEN[34462] = { title = "Winds of Change", description = "Commander, I have bad news. Olin Umberhide, the tauren who escaped with you from Tanaan, was ambushed when near the eastern perimeter of the Garrison.\n\nHe was seen being dragged off by the pale. These are dangerous, disturbing creatures that some believe were once orcs. Now they are husks of barely living flesh bent by dark magics.\n\nOlin is resourceful, but outnumbered. I would advise travelling east to effect a rescue as soon as possible, before they eat him alive... slowly.", objectives = "" }
WordHunterWoW_QuestEN[34463] = { title = "Mysterious Ring", description = "This elegantly crafted ring is covered in ornate decorations and symbols, the most prominent of which being the letter \"V\" in a glowing rune. The ring seems to fade in and out of view as if passing back and forth through time.\n\nSomeone at Khadgar's Tower may have an interest in such an artifact.", objectives = "" }
WordHunterWoW_QuestEN[34464] = { title = "Mysterious Boots", description = "Phasing back and forward in time, these flickering ornate boots are adorned with a lavish \"V\" on them.\n\nSomeone at Khadgar's Tower might have insights to the nature of these strange items.", objectives = "" }
WordHunterWoW_QuestEN[34465] = { title = "Mysterious Hat", description = "Energy flows from this mystical hat with an unseen strength. It hums as it drifts back and forward in time where it rests on the ground.\n\nThis is the sort of object that someone at Khadgar's Tower would find very interesting.", objectives = "" }
WordHunterWoW_QuestEN[34466] = { title = "Mysterious Staff", description = "Fluctuations in reality surround this staff so much that it is hard to identify any recognizable markings aside from a large, lavish \"V\" on its apex.\n\nThis might require help to identify by someone from Khadgar's Tower.", objectives = "" }
WordHunterWoW_QuestEN[34469] = { title = "Cleansing the Souls", description = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened.\n\nEnd their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", objectives = "" }
WordHunterWoW_QuestEN[34472] = { title = "Temporal Juxtaposition", description = "I think I figured out what those mysterious artifacts you collected were for.\n\nIt would seem someone is attempting to affect a temporal shift by sending items back into this timeline from your own timeline.\n\nTechnically that shouldn't be possible. But whoever this is found a way.\n\nI think I may try a ritual to bring the traveler through.", objectives = "" }
WordHunterWoW_QuestEN[34478] = { title = "A Potential Ally", description = "One of the captured draenei is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the orcs' amusement.\n\nUse this runestone. It should handily deal with the ring of fire that surrounds this draenei.", objectives = "" }
WordHunterWoW_QuestEN[34508] = { title = "Restalaan, Captain of the Guard", description = "They killed Aedraa and took the crystal from her! The captain of the guard, Restalaan, tried to stop them and they took him into the cathedral!\n\nIf we can just get this crystal, we can reunite the Heart of Auchindoun and turn its defenses on fully! We can't afford to fail now.\n\n{name}, you're the only one left that can do it. You have to find Restalaan! He'll know where they took it.", objectives = "" }
WordHunterWoW_QuestEN[34512] = { title = "Declawing The Competition", description = "These saberon freaks have cost me a lot of money, {class}.\n\nI'm not one to forgive a debt and it's time to collect!\n\nThe saberon that have been causing us the most trouble are the ones living in Sabermaw. They keep ambushing our trade shipments along the road.\n\n<Pyxni grins.>\n\nIt's time to declaw the competition. Bring me their claws; we'll sell the best ones as good luck charms here at the arena.\n\nIf the claw sales don't cover their debt, we'll just have to charge them an arm and a leg too!", objectives = "" }
WordHunterWoW_QuestEN[34513] = { title = "WANTED: Razorpaw!", description = "Wanted for crimes against the innocent at the Ring of Trials!\n\nRazorpaw is responsible for leading several raids and ambushes against travelers on the road near Sabermaw.\n\nLast seen in the vicinity of the saberon den known as Sabermaw.\n\nExercise extreme caution!\n\nUpon completion, this bounty will be fulfilled by Pyxni Pennypocket of the Steamwheedle Cartel.", objectives = "" }
WordHunterWoW_QuestEN[34514] = { title = "They've Got The Goods!", description = "The Saberon...they weren't just after prisoners...\n\n<Cough>...they took all the merchandise too.\n\nKidnapping is one thing...but stealing a goblin's merchandise? That's making things personal!\n\n<Cough>...Pyxni ain't going to be happy unless you get all of the stolen goods back. Make your way into Sabermaw and steal back all our merch.\n\nWhen you're done, make your way back to Pyxni at the Ring of Trials.\n\nShe'll make it worth your while...", objectives = "" }
WordHunterWoW_QuestEN[34515] = { title = "Gobnapped", description = "We never even saw the ambush coming...\n\nThe saberon hit us so hard and fast we barely had time to think.\n\nThose overgrown mongrels dragged the others away and left me here for dead...they probably thought I was too close to dying.\n\nI hear they like their meat fresh...\n<cough>....well I ain't going down that easy!\n\nDon't worry about me...<cough>...I've been through worse! You're gonna have to go to Sabermaw and get the other merchants out though.\n\nThey've probably got 'em all caged up in there...", objectives = "" }
WordHunterWoW_QuestEN[34516] = { title = "My Precious!", description = "You've got to help me!\n\nI was hiding on the trade wagon that got ambushed just down the road from here. I snuck away before the saberon spotted me...but...but...\n\nTHEY STOLE MY MOST PRIZED POSSESSION!\n\nYou've got to help me get it back! I watched them drag it into Sabermaw and up that giant hill!\n\nWho knows what those filthy saberon will do to it!\n\nPlease, I'm just a kid! You've got to help me out, right?", objectives = "" }
WordHunterWoW_QuestEN[34558] = { title = "At Your Command", description = "I'm glad you're here!\n\nFort Wrynn is nearly complete. We only need to fill this last plot.\n\nBaros provided us with blueprints for two different structures that would fit this space - an Artillery Tower or an Arcane Sanctum.\n\nIt's your call, commander. The plans are on the drafting table for your perusal.", objectives = "" }
WordHunterWoW_QuestEN[34563] = { title = "The Quarry Quandary", description = "Now that we have the artillery tower built, we're going to need some skilled hands to run it.\n\nI've heard that Ared, one of the best smiths in Shattrath, managed to escape the city's fall. He should be just outside the north wall with the rest of the refugees.\n\nSee if you can convince him to work for us.", objectives = "" }
WordHunterWoW_QuestEN[34564] = { title = "Destination: Unknown", description = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them.\n\nI'll hold open the portal as long as I can. It will be up to you to strike the killing blow.\n\nOur fate is in your hands, {name}.", objectives = "" }
